-- P12/P13/P14: complete physical source scope is qualified before any write.
-- Operational DATE columns are projections; exact events and original decisions
-- remain in an immutable tenant-bound ledger. No consumer/grant is deleted.
BEGIN;
ALTER TABLE public.customer_supply_periods ADD COLUMN market_start_at timestamptz, ADD COLUMN market_end_at timestamptz, ADD COLUMN market_state_version bigint NOT NULL DEFAULT 0, ADD COLUMN source_end_message_id uuid REFERENCES public.ediel_messages(id);
CREATE TABLE gridex_received_sources.regulated_supply_ground_versions (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),environment text NOT NULL CHECK(environment IN ('test','production')),
 legal_actor_id uuid NOT NULL,dso_actor_id uuid NOT NULL,grid_area_code text NOT NULL,process text NOT NULL CHECK(process IN ('assigned_supply','production_receipt_obligation')),
 bilateral_agreement_id uuid NOT NULL REFERENCES public.tenant_bilateral_agreements(id),consumption_supply_period_id uuid REFERENCES public.customer_supply_periods(id),
 source_reference text NOT NULL CHECK(length(source_reference)>0),source_sha256 text NOT NULL CHECK(source_sha256~'^[a-f0-9]{64}$'),legal_decision_reference text NOT NULL CHECK(length(legal_decision_reference)>0),registry_version text NOT NULL CHECK(length(registry_version)>0),
 approved_by uuid NOT NULL REFERENCES auth.users(id),approved_at timestamptz NOT NULL,valid_from timestamptz NOT NULL,valid_to timestamptz CHECK(valid_to>valid_from),revoked_at timestamptz,
 UNIQUE(company_id,environment,legal_actor_id,dso_actor_id,grid_area_code,process,registry_version)
);
-- No approval API or seed: authentic mandate/decision and versioned registry
-- import must be established independently before these held capabilities run.
ALTER TABLE gridex_received_sources.regulated_supply_ground_versions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON gridex_received_sources.regulated_supply_ground_versions FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE gridex_received_sources.supply_source_transitions (
 source_message_id uuid PRIMARY KEY REFERENCES public.ediel_messages(id) ON DELETE RESTRICT,company_id uuid NOT NULL REFERENCES public.companies(id),
 payload_hash text NOT NULL,source_code text NOT NULL,source_objects jsonb NOT NULL,previous_states jsonb NOT NULL,resulting_states jsonb NOT NULL,
 qualified_switch_ids uuid[] NOT NULL,actor_user_id uuid NOT NULL,applied_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE gridex_received_sources.supply_source_transitions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON gridex_received_sources.supply_source_transitions FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER supply_source_transition_immutable BEFORE UPDATE OR DELETE ON gridex_received_sources.supply_source_transitions FOR EACH ROW EXECUTE FUNCTION gridex_received_sources.permission_transition_immutable_v1();
CREATE TRIGGER supply_source_transition_no_truncate BEFORE TRUNCATE ON gridex_received_sources.supply_source_transitions FOR EACH STATEMENT EXECUTE FUNCTION gridex_received_sources.permission_transition_immutable_v1();
CREATE FUNCTION gridex_received_sources.supply_wire_v1(p_raw text)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE tokens jsonb:=gridex_received_sources.closure_wire_tokens_v2(p_raw);t jsonb;e jsonb;out jsonb:='{}';objects jsonb:='[]';obj jsonb;characteristic text;key text;value text;
BEGIN
 IF tokens IS NULL THEN RETURN NULL; END IF;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens) x ORDER BY (x->>'index')::int LOOP
  e:=t->'elements';
  IF t->>'tag'='BGM' THEN out:=out||jsonb_build_object('code',e#>>'{1,0}','bgmId',e#>>'{2,0}'); END IF;
  IF t->>'tag'='NAD' AND obj IS NULL AND e#>>'{1,0}' IN ('FR','DO') THEN
   key:=CASE e#>>'{1,0}' WHEN 'FR' THEN 'sender' ELSE 'receiver' END;
   IF out ? key OR e#>>'{2,1}' IS DISTINCT FROM '160' OR e#>>'{2,2}' IS DISTINCT FROM 'SVK' THEN RETURN NULL; END IF;
   out:=out||jsonb_build_object(key,e#>>'{2,0}');
  END IF;
  IF t->>'tag'='LIN' THEN
   IF obj IS NOT NULL THEN objects:=objects||jsonb_build_array(obj); END IF;
   obj:=jsonb_build_object('point',nullif(e#>>'{3,0}',''),'line',e#>>'{1,0}');characteristic:=NULL;
  ELSIF obj IS NOT NULL THEN
   key:=NULL;value:=NULL;
   IF t->>'tag'='RFF' AND e#>>'{1,0}' IN ('LI','Z05','Z07') THEN key:=CASE e#>>'{1,0}' WHEN 'LI' THEN 'li' WHEN 'Z05' THEN 'gridArea' ELSE 'consumptionPoint' END;value:=e#>>'{1,1}';
   ELSIF t->>'tag'='NAD' AND e#>>'{1,0}'='UD' THEN key:='customerIdentity';value:=e#>>'{2,0}';
   ELSIF t->>'tag'='DTM' AND e#>>'{1,0}' IN ('92','93') THEN
    key:=CASE e#>>'{1,0}' WHEN '92' THEN 'start' ELSE 'end' END;value:=e#>>'{1,1}';
    IF e#>>'{1,2}' IS DISTINCT FROM '203' THEN RETURN NULL; END IF;
   ELSIF t->>'tag'='CCI' THEN characteristic:=e#>>'{2,0}';
   ELSIF t->>'tag'='CAV' THEN key:=CASE characteristic WHEN 'Z13' THEN 'reason' WHEN 'Z23' THEN 'status' END;value:=e#>>'{1,0}';
   END IF;
   IF key IS NOT NULL THEN IF obj ? key THEN RETURN NULL; END IF;obj:=obj||jsonb_build_object(key,nullif(value,''));END IF;
  END IF;
 END LOOP;
 IF obj IS NOT NULL THEN objects:=objects||jsonb_build_array(obj);END IF;
 IF (out->>'code' IN ('Z03','Z04','Z05','Z09')) IS NOT TRUE OR nullif(out->>'sender','') IS NULL OR nullif(out->>'receiver','') IS NULL OR jsonb_array_length(objects)=0 THEN RETURN NULL;END IF;
 RETURN out||jsonb_build_object('objects',objects);
END $$;
REVOKE ALL ON FUNCTION gridex_received_sources.supply_wire_v1(text) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.ediel_apply_supply_source_v1(p_company_id uuid,p_source_message_id uuid,p_actor_user_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE m public.ediel_messages%rowtype;sp public.customer_supply_periods%rowtype;sw public.supplier_switch_requests%rowtype;origin public.ediel_messages%rowtype;
 prior gridex_received_sources.supply_source_transitions%rowtype;ground gridex_received_sources.regulated_supply_ground_versions%rowtype;
 wire jsonb;original jsonb;own jsonb;entry jsonb;plan jsonb;plans jsonb:='[]';before_states jsonb:='[]';after_states jsonb;old jsonb;
 ids uuid[];point public.metering_points%rowtype;consumption public.metering_points%rowtype;legal_actor uuid;dso_actor uuid;
 event_at timestamptz;start_at timestamptz;reason text;period_id uuid;expected_version bigint;qualified boolean;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR p_actor_user_id IS NULL THEN RETURN jsonb_build_object('applied',false,'reason','supply_source_unavailable');END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.id FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active') OR NOT coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,m.company_id,'metering.write'),false)
 OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL) THEN RETURN jsonb_build_object('applied',false,'reason','supply_execution_actor_unqualified');END IF;
 SELECT * INTO prior FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=m.id;
 IF FOUND THEN IF prior.company_id IS DISTINCT FROM m.company_id OR prior.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'supply_replay_conflict';END IF;RETURN jsonb_build_object('applied',true,'idempotent',true,'periods',prior.resulting_states);END IF;
 IF NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments v WHERE v.source_message_id=m.id AND v.company_id=m.company_id AND v.environment=m.environment AND v.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
 AND v.facts_text::jsonb->>'syntaxDecision'='accepted' AND v.facts_text::jsonb->>'applicationDecision'='accepted' AND v.facts_text::jsonb->>'functionalDecision'='accepted' AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)) THEN RETURN jsonb_build_object('applied',false,'reason','canonical_supply_source_not_accepted');END IF;
 wire:=gridex_received_sources.supply_wire_v1(m.raw_payload);
 IF wire IS NULL OR (wire->>'code' IN ('Z04','Z05')) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','supply_wire_unavailable');END IF;
 -- No mixed physical subtype, duplicate point, or partially applied message.
 SELECT o->>'reason' INTO reason FROM jsonb_array_elements(wire->'objects') o LIMIT 1;
 IF nullif(reason,'') IS NULL OR EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE o->>'reason' IS DISTINCT FROM reason OR nullif(o->>'point','') IS NULL OR nullif(o->>'li','') IS NULL)
 OR (SELECT count(DISTINCT o->>'point') FROM jsonb_array_elements(wire->'objects') o)<>jsonb_array_length(wire->'objects') THEN RETURN jsonb_build_object('applied',false,'reason','supply_object_scope_unqualified');END IF;
 PERFORM tp.id FROM public.tenant_ediel_profiles tp WHERE tp.company_id=m.company_id AND tp.environment=m.environment ORDER BY tp.id FOR SHARE;
 PERFORM i.id FROM public.tenant_actor_identifiers i WHERE i.company_id=m.company_id AND i.environment=m.environment ORDER BY i.id FOR SHARE;
 PERFORM r.id FROM public.tenant_actor_roles r WHERE r.company_id=m.company_id AND r.environment=m.environment ORDER BY r.id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.tenant_ediel_profiles tp WHERE tp.company_id=m.company_id AND tp.environment=m.environment AND tp.market='electricity' AND tp.is_enabled AND tp.valid_from<=m.message_received_at AND (tp.valid_to IS NULL OR m.message_received_at<tp.valid_to)) THEN RETURN jsonb_build_object('applied',false,'reason','supply_tenant_profile_unqualified');END IF;
 SELECT array_agg(DISTINCT i.actor_id) INTO ids FROM public.tenant_actor_identifiers i JOIN public.tenant_actor_roles r ON r.company_id=i.company_id AND r.environment=i.environment AND r.actor_id=i.actor_id
 WHERE i.company_id=m.company_id AND i.environment=m.environment AND i.identifier_type='EdielId' AND i.identifier_value=wire->>'receiver' AND i.valid_from<=m.message_received_at AND (i.valid_to IS NULL OR m.message_received_at<i.valid_to)
 AND r.role_code='electricity_supplier' AND r.valid_from<=m.message_received_at AND (r.valid_to IS NULL OR m.message_received_at<r.valid_to);
 IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','supply_legal_actor_unqualified');END IF;legal_actor:=ids[1];
 FOR own IN SELECT o FROM jsonb_array_elements(wire->'objects') o ORDER BY o->>'point' LOOP
  event_at:=gridex_received_sources.permission_time_v1(own->>CASE WHEN wire->>'code'='Z04' THEN 'start' ELSE 'end' END);
  IF event_at IS NULL THEN RETURN jsonb_build_object('applied',false,'reason','supply_effective_time_unavailable');END IF;
  IF wire->>'code'='Z04' AND reason IN ('Z26','Z70') THEN
   SELECT array_agg(mp.id ORDER BY mp.id) INTO ids FROM public.metering_points mp WHERE mp.company_id=m.company_id AND mp.ediel_metering_point_id=own->>'point' AND mp.grid_area_code=own->>'gridArea' AND mp.grid_owner_ediel_id=wire->>'sender'
    AND mp.customer_id IS NOT NULL AND (m.customer_id IS NULL OR m.customer_id=mp.customer_id) AND (m.metering_point_id IS NULL OR m.metering_point_id=mp.id);
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_exact_object_unavailable');END IF;
   SELECT * INTO point FROM public.metering_points WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
   PERFORM customer.id FROM public.customers customer WHERE customer.id=point.customer_id AND customer.company_id=m.company_id FOR SHARE;
   IF NOT EXISTS(SELECT FROM public.customers customer WHERE customer.id=point.customer_id AND customer.company_id=m.company_id AND own->>'customerIdentity'=coalesce(nullif(btrim(customer.org_number),''),nullif(btrim(customer.personal_number),''))) THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_customer_identity_unqualified');END IF;
   PERFORM ai.id FROM public.platform_actor_identifiers ai WHERE lower(ai.identifier_type) IN ('edielid','ediel_id') AND ai.identifier_value=wire->>'sender' ORDER BY ai.id FOR SHARE;
   SELECT array_agg(DISTINCT ai.actor_id) INTO ids FROM public.platform_actor_identifiers ai WHERE lower(ai.identifier_type) IN ('edielid','ediel_id') AND ai.identifier_value=wire->>'sender' AND ai.is_verified AND (ai.valid_from IS NULL OR ai.valid_from<=(m.message_received_at AT TIME ZONE 'Etc/GMT-1')::date) AND (ai.valid_to IS NULL OR (m.message_received_at AT TIME ZONE 'Etc/GMT-1')::date<=ai.valid_to);
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_dso_registry_unavailable');END IF;dso_actor:=ids[1];
   PERFORM ba.id FROM public.tenant_bilateral_agreements ba WHERE ba.company_id=m.company_id AND ba.environment=m.environment AND ba.counterparty_actor_id=dso_actor ORDER BY ba.id FOR SHARE;
   PERFORM g.id FROM gridex_received_sources.regulated_supply_ground_versions g WHERE g.company_id=m.company_id AND g.environment=m.environment AND g.legal_actor_id=legal_actor AND g.dso_actor_id=dso_actor AND g.grid_area_code=own->>'gridArea' ORDER BY g.id FOR SHARE;
   SELECT array_agg(g.id ORDER BY g.id) INTO ids FROM gridex_received_sources.regulated_supply_ground_versions g JOIN public.tenant_bilateral_agreements ba ON ba.id=g.bilateral_agreement_id AND ba.company_id=g.company_id AND ba.environment=g.environment AND ba.counterparty_actor_id=g.dso_actor_id
   WHERE g.company_id=m.company_id AND g.environment=m.environment AND g.legal_actor_id=legal_actor AND g.dso_actor_id=dso_actor AND g.grid_area_code=own->>'gridArea' AND g.process=CASE reason WHEN 'Z26' THEN 'assigned_supply' ELSE 'production_receipt_obligation' END
    AND g.approved_at<=m.message_received_at AND g.revoked_at IS NULL AND g.valid_from<=event_at AND (g.valid_to IS NULL OR event_at<g.valid_to) AND ba.is_enabled AND ba.valid_from<=event_at AND (ba.valid_to IS NULL OR event_at<ba.valid_to) AND ba.source_reference=g.source_reference;
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_authentic_ground_required');END IF;
   SELECT * INTO ground FROM gridex_received_sources.regulated_supply_ground_versions WHERE id=ids[1] FOR SHARE;
   IF reason='Z70' THEN
    SELECT cp.* INTO consumption FROM public.customer_supply_periods rel JOIN public.metering_points cp ON cp.id=rel.metering_point_id AND cp.company_id=rel.company_id JOIN public.customer_contracts cc ON cc.id=coalesce(rel.customer_contract_id,rel.contract_id) AND cc.company_id=rel.company_id AND cc.customer_id=rel.customer_id
    WHERE rel.id=ground.consumption_supply_period_id AND rel.company_id=m.company_id AND rel.customer_id=point.customer_id AND cp.ediel_metering_point_id=own->>'consumptionPoint' AND cp.product_direction='consumption' AND cc.energy_direction='consumption' AND cc.status IN ('signed','active') AND rel.status IN ('active','confirmed_by_grid_owner')
    AND rel.start_date<=gridex_received_sources.permission_date_v1(own->>'start') AND (rel.end_date IS NULL OR rel.end_date>gridex_received_sources.permission_date_v1(own->>'start')) FOR SHARE OF rel,cp,cc;
    IF NOT FOUND OR point.product_direction IS DISTINCT FROM 'production' THEN RETURN jsonb_build_object('applied',false,'reason','production_obligation_own_consumption_link_required');END IF;
   END IF;
   IF EXISTS(SELECT FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.metering_point_id=point.id AND p.status NOT IN ('cancelled','ended') AND (p.end_date IS NULL OR p.end_date>gridex_received_sources.permission_date_v1(own->>'start'))) THEN RETURN jsonb_build_object('applied',false,'reason','regulated_supply_conflicting_period');END IF;
   period_id:=gen_random_uuid();plans:=plans||jsonb_build_array(jsonb_build_object('kind','regulated','periodId',period_id,'pointId',point.id,'customerId',point.customer_id,'eventAt',event_at,'groundId',ground.id,'object',own));
  ELSIF wire->>'code'='Z04' AND reason='Z24' THEN
   -- Match every cancellation to its sealed, actually sent original Z03.
   SELECT array_agg(s.id ORDER BY s.id) INTO ids FROM public.supplier_switch_requests s JOIN public.ediel_messages z ON z.id=s.outbound_z03_message_id AND z.company_id=s.company_id AND z.environment=m.environment
    WHERE s.company_id=m.company_id AND z.direction='outbound' AND z.message_sent_at IS NOT NULL AND z.status='sent' AND z.immutable_rendered_at IS NOT NULL AND z.immutable_payload_hash=encode(sha256(convert_to(z.raw_payload,'UTF8')),'hex')
    AND EXISTS(SELECT FROM jsonb_array_elements(gridex_received_sources.supply_wire_v1(z.raw_payload)->'objects') o WHERE o->>'point'=own->>'point' AND o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason' IN ('Z22','Z23'))
    AND gridex_received_sources.supply_wire_v1(z.raw_payload)->>'sender'=wire->>'receiver' AND gridex_received_sources.supply_wire_v1(z.raw_payload)->>'receiver'=wire->>'sender';
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','z04c_exact_original_unavailable');END IF;
   SELECT * INTO sw FROM public.supplier_switch_requests WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
   SELECT * INTO origin FROM public.ediel_messages WHERE id=sw.outbound_z03_message_id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
   original:=gridex_received_sources.supply_wire_v1(origin.raw_payload);
   IF NOT FOUND OR origin.direction IS DISTINCT FROM 'outbound' OR origin.status IS DISTINCT FROM 'sent' OR origin.message_sent_at IS NULL OR origin.immutable_rendered_at IS NULL OR origin.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(origin.raw_payload,'UTF8')),'hex')
    OR original IS NULL OR original->>'code' IS DISTINCT FROM 'Z03' OR original->>'sender' IS DISTINCT FROM wire->>'receiver' OR original->>'receiver' IS DISTINCT FROM wire->>'sender'
    OR origin.customer_id IS DISTINCT FROM sw.customer_id OR origin.metering_point_id IS DISTINCT FROM sw.metering_point_id OR (m.customer_id IS NOT NULL AND m.customer_id<>sw.customer_id) OR (m.metering_point_id IS NOT NULL AND m.metering_point_id<>sw.metering_point_id)
    OR NOT EXISTS(SELECT FROM jsonb_array_elements(original->'objects') o WHERE o->>'point'=own->>'point' AND o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason' IN ('Z22','Z23'))
    THEN RETURN jsonb_build_object('applied',false,'reason','z04c_locked_original_mismatch');END IF;
   IF (sw.status IN ('draft','prepared','queued','sent','submitted','waiting','waiting_for_z04','accepted','cancellation_requested','cancelled_before_start')) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','z04c_effect_already_executed_compensation_required');END IF;
   SELECT array_agg(p.id ORDER BY p.id) INTO ids FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.customer_id=sw.customer_id AND p.metering_point_id=sw.metering_point_id AND (p.source_switch_request_id=sw.id OR p.source_message_id=sw.inbound_z04_message_id);
   IF coalesce(cardinality(ids),0)>1 THEN RETURN jsonb_build_object('applied',false,'reason','z04c_conflicting_periods');END IF;
   IF coalesce(cardinality(ids),0)=1 THEN
    SELECT * INTO sp FROM public.customer_supply_periods WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
    IF sp.status IS DISTINCT FROM 'confirmed_by_grid_owner' OR sp.customer_id IS DISTINCT FROM sw.customer_id OR sp.metering_point_id IS DISTINCT FROM sw.metering_point_id OR sp.start_date IS DISTINCT FROM gridex_received_sources.permission_date_v1(own->>'start') OR coalesce(sp.market_start_at,sp.start_date::timestamp AT TIME ZONE 'Etc/GMT-1')<=now() THEN RETURN jsonb_build_object('applied',false,'reason','z04c_effect_already_executed_compensation_required');END IF;
    before_states:=before_states||jsonb_build_array(to_jsonb(sp));period_id:=sp.id;
   ELSE period_id:=NULL;END IF;
   plans:=plans||jsonb_build_array(jsonb_build_object('kind','cancel_start','periodId',period_id,'switchId',sw.id,'object',own));
  ELSIF wire->>'code'='Z05' AND reason='Z24' THEN
   SELECT array_agg(p.id ORDER BY p.id) INTO ids FROM public.customer_supply_periods p JOIN gridex_received_sources.supply_source_transitions tr ON tr.source_message_id=p.source_end_message_id AND tr.company_id=p.company_id
    JOIN public.ediel_messages z ON z.id=tr.source_message_id AND z.company_id=tr.company_id AND z.environment=m.environment
    WHERE p.company_id=m.company_id AND z.direction='inbound' AND tr.payload_hash=encode(sha256(convert_to(z.raw_payload,'UTF8')),'hex') AND gridex_received_sources.supply_wire_v1(z.raw_payload)->>'sender'=wire->>'sender' AND gridex_received_sources.supply_wire_v1(z.raw_payload)->>'receiver'=wire->>'receiver'
    AND EXISTS(SELECT FROM jsonb_array_elements(tr.source_objects) o WHERE o->>'point'=own->>'point' AND o->>'li'=own->>'li' AND o->>'end'=own->>'end')
    AND EXISTS(SELECT FROM jsonb_array_elements(tr.resulting_states) state WHERE state->>'id'=p.id::text AND (state->>'market_state_version')::bigint=p.market_state_version AND (state-ARRAY['updated_at','status'])=(to_jsonb(p)-ARRAY['updated_at','status']));
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','z05c_exact_original_ending_unavailable');END IF;
   SELECT * INTO sp FROM public.customer_supply_periods WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
   SELECT * INTO prior FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=sp.source_end_message_id AND company_id=m.company_id;
   SELECT state INTO old FROM jsonb_array_elements(prior.previous_states) state WHERE state->>'id'=sp.id::text;
   IF old IS NULL OR NOT EXISTS(SELECT FROM jsonb_array_elements(prior.resulting_states) saved WHERE saved->>'id'=sp.id::text AND (sp.status=saved->>'status' OR sp.status='ended' AND saved->>'status'='ending' AND sp.market_end_at<=now())) OR EXISTS(SELECT FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.metering_point_id=sp.metering_point_id AND p.id<>sp.id AND p.status NOT IN ('ended','cancelled') AND (p.end_date IS NULL OR p.end_date>sp.start_date)) THEN RETURN jsonb_build_object('applied',false,'reason','z05c_conflicting_continuation');END IF;
   before_states:=before_states||jsonb_build_array(to_jsonb(sp));plans:=plans||jsonb_build_array(jsonb_build_object('kind','restore_end','periodId',sp.id,'previous',old,'object',own));
  ELSIF wire->>'code'='Z05' AND reason IN ('Z22','Z23') THEN
   -- Actual accepted baseline owner ties the physical object to a relationship;
   -- a unique local row or DATE similarity is never sufficient authority.
   SELECT array_agg(p.id ORDER BY p.id) INTO ids FROM public.customer_supply_periods p
    WHERE p.company_id=m.company_id AND p.status IN ('active','confirmed_by_grid_owner','ending') AND p.source_end_message_id IS NULL AND (
     EXISTS(SELECT FROM gridex_received_sources.object_assessments assessment JOIN gridex_received_sources.sources src ON src.source_message_id=assessment.source_message_id AND src.company_id=assessment.company_id AND src.payload_hash=assessment.source_payload_hash
      JOIN public.ediel_messages base ON base.id=src.source_message_id AND base.company_id=src.company_id AND base.environment=src.environment AND base.direction='inbound' AND src.payload_hash=encode(sha256(convert_to(base.raw_payload,'UTF8')),'hex')
      CROSS JOIN LATERAL jsonb_array_elements(assessment.facts_text::jsonb->'objects') object
      WHERE assessment.company_id=p.company_id AND assessment.environment=m.environment AND assessment.source_message_id=p.source_message_id
       AND object->>'disposition'='accepted' AND object#>>'{object,objectId}'=own->>'point' AND object#>>'{object,identityAgency}'='9'
       AND object#>>'{business,supplyPeriodId}'=p.id::text AND object#>>'{business,customerId}'=p.customer_id::text AND object#>>'{business,meteringPointId}'=p.metering_point_id::text
       AND object#>>'{business,owner}' IN ('inbound-z04-switch-confirmation-v1','reviewed-received-structure-v1')
       AND object#>>'{party,parties,legalSender}'=wire->>'sender' AND object#>>'{party,parties,legalReceiver}'=wire->>'receiver'
       AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments child WHERE child.previous_assessment_id=assessment.id))
     OR EXISTS(SELECT FROM gridex_received_sources.supply_source_transitions tr JOIN public.ediel_messages base ON base.id=tr.source_message_id AND base.company_id=tr.company_id AND base.environment=m.environment AND base.direction='inbound'
      WHERE tr.company_id=p.company_id AND tr.source_message_id=p.source_message_id AND tr.source_code='Z04' AND tr.payload_hash=encode(sha256(convert_to(base.raw_payload,'UTF8')),'hex')
       AND EXISTS(SELECT FROM jsonb_array_elements(tr.resulting_states) state WHERE state->>'id'=p.id::text AND state->>'customer_id'=p.customer_id::text AND state->>'metering_point_id'=p.metering_point_id::text)
       AND EXISTS(SELECT FROM jsonb_array_elements(tr.source_objects) object WHERE object->>'point'=own->>'point' AND object->>'customerIdentity'=own->>'customerIdentity' AND object->>'gridArea'=own->>'gridArea' AND object->>'reason' IN ('Z26','Z70')))
    );
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','z05_accepted_relationship_baseline_required');END IF;
   SELECT * INTO sp FROM public.customer_supply_periods WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
   SELECT * INTO origin FROM public.ediel_messages WHERE id=sp.source_message_id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
   original:=gridex_received_sources.supply_wire_v1(origin.raw_payload);
   IF original IS NULL OR original->>'code' IS DISTINCT FROM 'Z04' OR original->>'sender' IS DISTINCT FROM wire->>'sender' OR original->>'receiver' IS DISTINCT FROM wire->>'receiver'
    OR NOT EXISTS(SELECT FROM jsonb_array_elements(original->'objects') o WHERE o->>'point'=own->>'point' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'gridArea'=own->>'gridArea' AND gridex_received_sources.permission_time_v1(o->>'start')<event_at)
    OR (m.customer_id IS NOT NULL AND m.customer_id<>sp.customer_id) OR (m.metering_point_id IS NOT NULL AND m.metering_point_id<>sp.metering_point_id) THEN RETURN jsonb_build_object('applied',false,'reason','z05_original_object_mismatch');END IF;
   before_states:=before_states||jsonb_build_array(to_jsonb(sp));plans:=plans||jsonb_build_array(jsonb_build_object('kind','end','periodId',sp.id,'eventAt',event_at,'object',own));
  ELSE RETURN jsonb_build_object('applied',false,'reason','supply_profile_not_qualified');END IF;
 END LOOP;
 -- All owned objects, current originals and ground records are locked/qualified.
 FOR plan IN SELECT x FROM jsonb_array_elements(plans) x LOOP
  IF plan->>'kind'='regulated' THEN
   INSERT INTO public.customer_supply_periods(id,company_id,customer_id,metering_point_id,start_date,market_start_at,source,source_process,source_message_id,status,market_state_version,metadata)
    VALUES((plan->>'periodId')::uuid,m.company_id,(plan->>'customerId')::uuid,(plan->>'pointId')::uuid,gridex_received_sources.permission_date_v1(plan#>>'{object,start}'),(plan->>'eventAt')::timestamptz,'ediel_qualified_source',CASE reason WHEN 'Z26' THEN 'assigned_supply' ELSE 'production_receipt_obligation' END,m.id,'confirmed_by_grid_owner',1,jsonb_build_object('sourceGroundId',plan->>'groundId','sourceObject',plan->'object','sourceReceivedAt',m.message_received_at));
  ELSIF plan->>'kind'='cancel_start' THEN
   UPDATE public.supplier_switch_requests SET status='cancelled_before_start',inbound_z04_message_id=m.id,completed_at=now(),updated_at=now() WHERE id=(plan->>'switchId')::uuid AND company_id=m.company_id;
   UPDATE public.customer_supply_periods SET status='cancelled',market_state_version=market_state_version+1,updated_at=now(),metadata=coalesce(metadata,'{}')||jsonb_build_object('startCancellationSource',m.id) WHERE id=(plan->>'periodId')::uuid AND company_id=m.company_id;
  ELSIF plan->>'kind'='end' THEN
   UPDATE public.customer_supply_periods SET end_date=gridex_received_sources.permission_date_v1(plan#>>'{object,end}'),market_end_at=(plan->>'eventAt')::timestamptz,source_end_message_id=m.id,status=CASE WHEN (plan->>'eventAt')::timestamptz<=now() THEN 'ended' ELSE 'ending' END,market_state_version=market_state_version+1,updated_at=now() WHERE id=(plan->>'periodId')::uuid AND company_id=m.company_id;
  ELSIF plan->>'kind'='restore_end' THEN
   UPDATE public.customer_supply_periods SET status=plan#>>'{previous,status}',end_date=(plan#>>'{previous,end_date}')::date,market_end_at=(plan#>>'{previous,market_end_at}')::timestamptz,source_end_message_id=(plan#>>'{previous,source_end_message_id}')::uuid,market_state_version=market_state_version+1,updated_at=now(),metadata=coalesce(metadata,'{}')||jsonb_build_object('endCancellationSource',m.id) WHERE id=(plan->>'periodId')::uuid AND company_id=m.company_id;
  END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.id),'[]'::jsonb) INTO after_states FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.id IN (SELECT (plan->>'periodId')::uuid FROM jsonb_array_elements(plans) plan);
 INSERT INTO gridex_received_sources.supply_source_transitions(source_message_id,company_id,payload_hash,source_code,source_objects,previous_states,resulting_states,qualified_switch_ids,actor_user_id) VALUES(m.id,m.company_id,encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),wire->>'code',wire->'objects',before_states,after_states,ARRAY(SELECT (plan->>'switchId')::uuid FROM jsonb_array_elements(plans) plan WHERE plan->>'kind'='cancel_start'),p_actor_user_id);
 RETURN jsonb_build_object('applied',true,'periods',after_states,'regulated',wire->>'code'='Z04' AND reason IN ('Z26','Z70'));
END $$;
REVOKE ALL ON FUNCTION public.ediel_apply_supply_source_v1(uuid,uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ediel_apply_supply_source_v1(uuid,uuid,uuid) TO service_role;
CREATE FUNCTION public.ediel_supply_start_is_cancelled_v1(p_company_id uuid,p_switch_request_id uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT EXISTS(SELECT FROM public.supplier_switch_requests sw JOIN gridex_received_sources.supply_source_transitions tr ON tr.source_message_id=sw.inbound_z04_message_id AND tr.company_id=sw.company_id WHERE sw.id=p_switch_request_id AND sw.company_id=p_company_id AND sw.status='cancelled_before_start' AND sw.id=ANY(tr.qualified_switch_ids) AND tr.source_code='Z04' AND EXISTS(SELECT FROM jsonb_array_elements(tr.source_objects) o WHERE o->>'reason'='Z24'))
$$;
REVOKE ALL ON FUNCTION public.ediel_supply_start_is_cancelled_v1(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ediel_supply_start_is_cancelled_v1(uuid,uuid) TO service_role;
CREATE FUNCTION public.ediel_advance_supply_deadlines_v1(p_company_id uuid,p_actor_user_id uuid,p_limit integer DEFAULT 100)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE changed integer;activated integer;
BEGIN
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 IF p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active') THEN RETURN jsonb_build_object('updated',0);END IF;
 WITH due AS (SELECT p.id FROM public.customer_supply_periods p JOIN gridex_received_sources.supply_source_transitions tr ON tr.source_message_id=p.source_end_message_id AND tr.company_id=p.company_id JOIN public.ediel_messages m ON m.id=tr.source_message_id AND m.company_id=tr.company_id WHERE (p_company_id IS NULL OR p.company_id=p_company_id) AND coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p.company_id,'metering.write'),false) AND EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p.company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL) AND p.status='ending' AND p.market_end_at<=now() AND tr.payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND EXISTS(SELECT FROM jsonb_array_elements(tr.resulting_states) s WHERE s->>'id'=p.id::text AND (s->>'market_state_version')::bigint=p.market_state_version AND (s->>'market_end_at')::timestamptz=p.market_end_at) ORDER BY p.market_end_at,p.id LIMIT least(greatest(coalesce(p_limit,100),1),200) FOR UPDATE OF p SKIP LOCKED)
 UPDATE public.customer_supply_periods p SET status='ended',updated_at=now() FROM due WHERE p.id=due.id AND (p_company_id IS NULL OR p.company_id=p_company_id) AND p.status='ending';
 GET DIAGNOSTICS changed=ROW_COUNT;
 -- These are separate regulated market relationships. No ordinary Z03 or
 -- consumer-contract activation/notification is introduced by this profile.
 WITH due AS (
  SELECT p.id FROM public.customer_supply_periods p JOIN gridex_received_sources.supply_source_transitions tr ON tr.source_message_id=p.source_message_id AND tr.company_id=p.company_id
  JOIN public.ediel_messages m ON m.id=tr.source_message_id AND m.company_id=tr.company_id
  JOIN gridex_received_sources.regulated_supply_ground_versions g ON g.id::text=p.metadata->>'sourceGroundId' AND g.company_id=p.company_id AND g.environment=m.environment
  JOIN public.tenant_bilateral_agreements ba ON ba.id=g.bilateral_agreement_id AND ba.company_id=g.company_id AND ba.environment=g.environment AND ba.counterparty_actor_id=g.dso_actor_id
  JOIN public.tenant_actor_roles role ON role.company_id=p.company_id AND role.environment=m.environment AND role.actor_id=g.legal_actor_id AND role.role_code='electricity_supplier' AND role.valid_from<=now() AND (role.valid_to IS NULL OR now()<role.valid_to)
  JOIN public.tenant_ediel_profiles profile ON profile.company_id=p.company_id AND profile.environment=m.environment AND profile.market='electricity' AND profile.is_enabled AND profile.valid_from<=now() AND (profile.valid_to IS NULL OR now()<profile.valid_to)
  WHERE (p_company_id IS NULL OR p.company_id=p_company_id) AND p.status='confirmed_by_grid_owner' AND p.source_process IN ('assigned_supply','production_receipt_obligation') AND p.market_start_at<=now()
   AND coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p.company_id,'metering.write'),false) AND EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p.company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
   AND tr.payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND g.revoked_at IS NULL AND g.valid_from<=now() AND (g.valid_to IS NULL OR now()<g.valid_to) AND ba.is_enabled AND ba.source_reference=g.source_reference AND ba.valid_from<=now() AND (ba.valid_to IS NULL OR now()<ba.valid_to)
      AND EXISTS(SELECT FROM jsonb_array_elements(tr.resulting_states) saved WHERE saved->>'id'=p.id::text AND (saved->>'market_state_version')::bigint=p.market_state_version AND (saved->>'market_start_at')::timestamptz=p.market_start_at AND saved->>'customer_id'=p.customer_id::text AND saved->>'metering_point_id'=p.metering_point_id::text AND saved->>'source_process'=p.source_process AND saved->'metadata'=p.metadata)
   ORDER BY p.market_start_at,p.id LIMIT least(greatest(coalesce(p_limit,100),1),200) FOR UPDATE OF p SKIP LOCKED FOR SHARE OF g,ba,role,profile)
 UPDATE public.customer_supply_periods p SET status='active',updated_at=now() FROM due WHERE p.id=due.id AND p.status='confirmed_by_grid_owner';
 GET DIAGNOSTICS activated=ROW_COUNT;RETURN jsonb_build_object('updated',changed+activated);

END $$;
REVOKE ALL ON FUNCTION public.ediel_advance_supply_deadlines_v1(uuid,uuid,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ediel_advance_supply_deadlines_v1(uuid,uuid,integer) TO service_role;
COMMIT;

20260930174333_ediel_production_contract.body:
-- P08 / CASE-Z09D-SUPPLIER: a signed/ceased production contract event owns
-- field210 XOR211. DATE projections and an ordinary supplier switch never do.
-- This unseeded evidence ledger has no application approval/write API.
BEGIN;
CREATE TABLE gridex_received_sources.production_contract_events (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id),
 environment text NOT NULL CHECK(environment IN ('test','production')), contract_id uuid NOT NULL REFERENCES public.customer_contracts(id),
 customer_id uuid NOT NULL REFERENCES public.customers(id), metering_point_id uuid NOT NULL REFERENCES public.metering_points(id),
 legal_actor_id uuid NOT NULL, dso_actor_id uuid NOT NULL, dso_registry_version text NOT NULL CHECK(length(dso_registry_version)>0), dso_registry_sha256 text NOT NULL CHECK(dso_registry_sha256~'^[a-f0-9]{64}$'), legal_sender_id text NOT NULL, legal_receiver_id text NOT NULL,
 point_id text NOT NULL, identity_agency text NOT NULL CHECK(identity_agency IN ('9','89')), grid_area_code text NOT NULL,
 event_kind text NOT NULL CHECK(event_kind IN ('signed','ceased')), boundary_at timestamptz NOT NULL CHECK(extract(second FROM boundary_at)=0),
 start_event_id uuid REFERENCES gridex_received_sources.production_contract_events(id),
 contract_reference text NOT NULL CHECK(length(contract_reference)>0), contract_revision text NOT NULL CHECK(length(contract_revision)>0),
 protected_contract_hash text NOT NULL CHECK(protected_contract_hash~'^[a-f0-9]{64}$'),
 source_reference text NOT NULL CHECK(length(source_reference)>0), source_sha256 text NOT NULL CHECK(source_sha256~'^[a-f0-9]{64}$'),
 source_version text NOT NULL CHECK(length(source_version)>0), approved_by uuid NOT NULL REFERENCES auth.users(id), approved_at timestamptz NOT NULL,
 CHECK((event_kind='signed' AND start_event_id IS NULL) OR (event_kind='ceased' AND start_event_id IS NOT NULL)),
 UNIQUE(company_id,environment,source_reference,source_version)
);
CREATE TABLE gridex_received_sources.production_contract_revocations (
 event_id uuid PRIMARY KEY REFERENCES gridex_received_sources.production_contract_events(id), revoked_at timestamptz NOT NULL,
 source_reference text NOT NULL CHECK(length(source_reference)>0), source_sha256 text NOT NULL CHECK(source_sha256~'^[a-f0-9]{64}$'), actor_user_id uuid NOT NULL
);
CREATE TABLE gridex_received_sources.production_contract_origins (
 event_id uuid PRIMARY KEY REFERENCES gridex_received_sources.production_contract_events(id), intent_id uuid NOT NULL UNIQUE REFERENCES public.ediel_message_intents(id),
 company_id uuid NOT NULL REFERENCES public.companies(id), actor_user_id uuid NOT NULL, outbound_request_id uuid NOT NULL REFERENCES public.outbound_requests(id), message_id uuid UNIQUE REFERENCES public.ediel_messages(id),
 payload_hash text, reserved_at timestamptz NOT NULL DEFAULT now(), CHECK((message_id IS NULL)=(payload_hash IS NULL))
);
CREATE TABLE gridex_received_sources.production_contract_periods (
 start_event_id uuid PRIMARY KEY REFERENCES gridex_received_sources.production_contract_events(id), company_id uuid NOT NULL REFERENCES public.companies(id),
 environment text NOT NULL, contract_id uuid NOT NULL REFERENCES public.customer_contracts(id), customer_id uuid NOT NULL, metering_point_id uuid NOT NULL,
 start_at timestamptz NOT NULL, end_at timestamptz CHECK(end_at>start_at), end_event_id uuid UNIQUE REFERENCES gridex_received_sources.production_contract_events(id)
);
CREATE UNIQUE INDEX production_contract_one_open_period ON gridex_received_sources.production_contract_periods(company_id,environment,contract_id,metering_point_id) WHERE end_event_id IS NULL;
DO $$ DECLARE t text; BEGIN
 FOR t IN SELECT unnest(ARRAY['production_contract_events','production_contract_revocations','production_contract_origins','production_contract_periods']) LOOP
 EXECUTE format('ALTER TABLE gridex_received_sources.%I ENABLE ROW LEVEL SECURITY',t);
 EXECUTE format('REVOKE ALL ON gridex_received_sources.%I FROM PUBLIC,anon,authenticated,service_role',t);
 END LOOP;
 FOR t IN SELECT unnest(ARRAY['production_contract_events','production_contract_revocations']) LOOP
 EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON gridex_received_sources.%I FOR EACH ROW EXECUTE FUNCTION gridex_received_sources.permission_transition_immutable_v1()',t||'_immutable',t);
 EXECUTE format('CREATE TRIGGER %I BEFORE TRUNCATE ON gridex_received_sources.%I FOR EACH STATEMENT EXECUTE FUNCTION gridex_received_sources.permission_transition_immutable_v1()',t||'_no_truncate',t);
 END LOOP;
END $$;
CREATE FUNCTION gridex_received_sources.production_contract_origin_guard_v1()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
 IF TG_OP<>'UPDATE' THEN RAISE EXCEPTION 'production_contract_origin_immutable';END IF;
 IF (to_jsonb(NEW)-ARRAY['message_id','payload_hash']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['message_id','payload_hash'])
 OR OLD.message_id IS NOT NULL OR NEW.message_id IS NULL OR NEW.payload_hash IS NULL THEN RAISE EXCEPTION 'production_contract_origin_immutable';END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION gridex_received_sources.production_contract_origin_guard_v1() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER production_contract_origin_immutable BEFORE UPDATE OR DELETE ON gridex_received_sources.production_contract_origins FOR EACH ROW EXECUTE FUNCTION gridex_received_sources.production_contract_origin_guard_v1();
CREATE TRIGGER production_contract_origin_no_truncate BEFORE TRUNCATE ON gridex_received_sources.production_contract_origins FOR EACH STATEMENT EXECUTE FUNCTION gridex_received_sources.production_contract_origin_guard_v1();
CREATE FUNCTION gridex_received_sources.production_contract_revocation_lock_v1()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 -- A revocation cannot race a qualified source read/message binding: all readers
 -- hold SHARE on the same immutable parent until their atomic effect commits.
 PERFORM e.id FROM gridex_received_sources.production_contract_events e WHERE e.id=NEW.event_id FOR UPDATE;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION gridex_received_sources.production_contract_revocation_lock_v1() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER production_contract_revocation_lock BEFORE INSERT ON gridex_received_sources.production_contract_revocations FOR EACH ROW EXECUTE FUNCTION gridex_received_sources.production_contract_revocation_lock_v1();
CREATE FUNCTION gridex_received_sources.production_contract_hash_v1(c public.customer_contracts)
RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$
 SELECT encode(sha256(convert_to(jsonb_build_object('id',c.id,'companyId',c.company_id,'customerId',c.customer_id,'pointId',c.metering_point_id,
 'contractVersion',c.contract_version,'signedVersion',c.signed_version,'signedAt',c.signed_at,'versionSnapshot',c.version_snapshot)::text,'UTF8')),'hex')
$$;
REVOKE ALL ON FUNCTION gridex_received_sources.production_contract_hash_v1(public.customer_contracts) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.ediel_production_contract_source_v1(p_company_id uuid,p_event_id uuid,p_actor_user_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE e gridex_received_sources.production_contract_events%rowtype;c public.customer_contracts%rowtype;mp public.metering_points%rowtype;ids uuid[];start gridex_received_sources.production_contract_events%rowtype;
BEGIN
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.id FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active')
 OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
 OR NOT coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.write'),false)
 THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_execution_actor_unqualified'));END IF;
 SELECT * INTO e FROM gridex_received_sources.production_contract_events WHERE id=p_event_id AND company_id=p_company_id FOR SHARE;
 IF NOT FOUND OR e.approved_at>now() OR EXISTS(SELECT FROM gridex_received_sources.production_contract_revocations r WHERE r.event_id=e.id)
 THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('authentic_production_contract_event_required'));END IF;
 PERFORM customer.id FROM public.customers customer WHERE customer.id=e.customer_id AND customer.company_id=e.company_id FOR SHARE;
 IF NOT FOUND THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_owned_customer_required'));END IF;
 SELECT * INTO c FROM public.customer_contracts WHERE id=e.contract_id AND company_id=e.company_id FOR SHARE;
 SELECT * INTO mp FROM public.metering_points WHERE id=e.metering_point_id AND company_id=e.company_id FOR SHARE;
 IF c.id IS NULL OR mp.id IS NULL OR c.customer_id IS DISTINCT FROM e.customer_id OR c.metering_point_id IS DISTINCT FROM e.metering_point_id
 OR mp.customer_id IS DISTINCT FROM e.customer_id OR mp.product_direction IS DISTINCT FROM 'production'
 OR mp.ediel_metering_point_id IS DISTINCT FROM e.point_id OR mp.grid_owner_ediel_id IS DISTINCT FROM e.legal_receiver_id OR mp.grid_area_code IS DISTINCT FROM e.grid_area_code
 OR c.signed_at IS NULL OR nullif(c.signed_version,'') IS NULL OR c.signed_version IS DISTINCT FROM e.contract_revision
 OR gridex_received_sources.production_contract_hash_v1(c) IS DISTINCT FROM e.protected_contract_hash
 THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_current_owner_scope_changed'));END IF;
 PERFORM p.id FROM public.tenant_ediel_profiles p WHERE p.company_id=e.company_id AND p.environment=e.environment ORDER BY p.id FOR SHARE;
 PERFORM i.id FROM public.tenant_actor_identifiers i WHERE i.company_id=e.company_id AND i.environment=e.environment ORDER BY i.id FOR SHARE;
 PERFORM r.id FROM public.tenant_actor_roles r WHERE r.company_id=e.company_id AND r.environment=e.environment ORDER BY r.id FOR SHARE;
 PERFORM i.id FROM public.platform_actor_identifiers i WHERE i.identifier_value=e.legal_receiver_id ORDER BY i.id FOR SHARE;
 PERFORM a.id FROM public.platform_market_actors a WHERE a.id=e.dso_actor_id FOR SHARE;
 PERFORM r.id FROM public.platform_actor_roles r WHERE r.actor_id=e.dso_actor_id ORDER BY r.id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.tenant_ediel_profiles p WHERE p.company_id=e.company_id AND p.environment=e.environment AND p.market='electricity' AND p.is_enabled AND p.valid_from<=now() AND (p.valid_to IS NULL OR now()<p.valid_to))
 OR NOT EXISTS(SELECT FROM public.tenant_actor_roles r WHERE r.company_id=e.company_id AND r.environment=e.environment AND r.actor_id=e.legal_actor_id AND r.role_code='electricity_supplier' AND r.valid_from<=now() AND (r.valid_to IS NULL OR now()<r.valid_to))
 OR (SELECT count(DISTINCT (i.actor_id,i.identifier_value)) FROM public.tenant_actor_identifiers i WHERE i.company_id=e.company_id AND i.environment=e.environment AND i.identifier_type='EdielId' AND i.valid_from<=now() AND (i.valid_to IS NULL OR now()<i.valid_to))<>1
 OR NOT EXISTS(SELECT FROM public.tenant_actor_identifiers i WHERE i.company_id=e.company_id AND i.environment=e.environment AND i.actor_id=e.legal_actor_id AND i.identifier_type='EdielId' AND i.identifier_value=e.legal_sender_id AND i.valid_from<=now() AND (i.valid_to IS NULL OR now()<i.valid_to))
 THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_current_legal_supplier_required'));END IF;
 SELECT array_agg(DISTINCT i.actor_id) INTO ids FROM public.platform_actor_identifiers i WHERE lower(i.identifier_type) IN ('edielid','ediel_id') AND i.identifier_value=e.legal_receiver_id AND i.is_verified AND (i.valid_from IS NULL OR i.valid_from<=current_date) AND (i.valid_to IS NULL OR current_date<=i.valid_to);
 IF coalesce(cardinality(ids),0)<>1 OR ids[1] IS DISTINCT FROM e.dso_actor_id
 OR NOT EXISTS(SELECT FROM public.platform_actor_identifiers i WHERE i.actor_id=e.dso_actor_id AND i.identifier_type='EdielId' AND i.identifier_value=e.legal_receiver_id AND i.is_verified AND (i.valid_from IS NULL OR i.valid_from<=current_date) AND (i.valid_to IS NULL OR current_date<=i.valid_to))
 OR NOT EXISTS(SELECT FROM public.platform_market_actors a WHERE a.id=e.dso_actor_id AND a.status='active' AND a.match_status='verified')
 OR NOT EXISTS(SELECT FROM public.platform_actor_roles r WHERE r.actor_id=e.dso_actor_id AND r.actor_role='grid_owner' AND r.is_active) THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_verified_dso_identity_required'));END IF;
 IF e.event_kind='ceased' THEN
 SELECT * INTO start FROM gridex_received_sources.production_contract_events WHERE id=e.start_event_id AND company_id=e.company_id FOR SHARE;
 IF start.id IS NULL OR start.event_kind IS DISTINCT FROM 'signed' OR start.environment IS DISTINCT FROM e.environment OR start.contract_id IS DISTINCT FROM e.contract_id OR start.metering_point_id IS DISTINCT FROM e.metering_point_id OR start.customer_id IS DISTINCT FROM e.customer_id OR start.boundary_at>=e.boundary_at OR EXISTS(SELECT FROM gridex_received_sources.production_contract_revocations r WHERE r.event_id=start.id)
 THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_original_start_required'));END IF;
 END IF;
 RETURN jsonb_build_object('status','authorized','companyId',e.company_id,'environment',e.environment,'eventId',e.id,'eventKind',e.event_kind,'sourceDigest',e.source_sha256,'sourceVersion',e.source_version,'sourceReference',e.source_reference,
 'legalActorId',e.legal_actor_id,'legalSenderId',e.legal_sender_id,'legalReceiverId',e.legal_receiver_id,'contractId',e.contract_id,'customerId',e.customer_id,'meteringPointId',e.metering_point_id,'pointId',e.point_id,'identityAgency',e.identity_agency,'gridArea',e.grid_area_code,
 'contractReference',e.contract_reference,'contractRevision',e.contract_revision,'boundaryAt',e.boundary_at);
END $$;
REVOKE ALL ON FUNCTION public.ediel_production_contract_source_v1(uuid,uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ediel_production_contract_source_v1(uuid,uuid,uuid) TO service_role;
CREATE FUNCTION public.ediel_reserve_production_contract_origin_v1(p_company_id uuid,p_event_id uuid,p_actor_user_id uuid,p_intent_id uuid,p_outbound_request_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE b jsonb;e gridex_received_sources.production_contract_events%rowtype;o gridex_received_sources.production_contract_origins%rowtype;i public.ediel_message_intents%rowtype;period gridex_received_sources.production_contract_periods%rowtype;
BEGIN
 SELECT * INTO e FROM gridex_received_sources.production_contract_events WHERE id=p_event_id AND company_id=p_company_id FOR UPDATE;
 PERFORM mp.id FROM public.metering_points mp WHERE mp.id=e.metering_point_id AND mp.company_id=e.company_id FOR UPDATE;
 b:=public.ediel_production_contract_source_v1(p_company_id,p_event_id,p_actor_user_id);IF b->>'status' IS DISTINCT FROM 'authorized' THEN RETURN b;END IF;
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=p_intent_id AND company_id=p_company_id FOR SHARE;
 IF i.id IS NULL OR i.environment IS DISTINCT FROM e.environment OR i.message_family IS DISTINCT FROM 'PRODAT' OR i.message_code IS DISTINCT FROM 'Z09' OR i.customer_id IS DISTINCT FROM e.customer_id OR i.metering_point_id IS DISTINCT FROM e.point_id OR i.operation_id IS DISTINCT FROM e.id
 THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_intent_scope_mismatch'));END IF;
 SELECT * INTO o FROM gridex_received_sources.production_contract_origins WHERE event_id=e.id FOR UPDATE;
 IF FOUND THEN IF o.intent_id IS DISTINCT FROM i.id THEN RAISE EXCEPTION 'production_contract_origin_conflict';END IF;RETURN jsonb_build_object('status','reserved','messageId',o.message_id,'outboundRequestId',o.outbound_request_id);END IF;
 IF NOT EXISTS(SELECT FROM public.outbound_requests r WHERE r.id=p_outbound_request_id AND r.company_id=e.company_id AND r.customer_id=e.customer_id AND r.source_type='manual' AND r.source_id=i.id::text AND r.request_type='customer_masterdata') THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_owned_request_required'));END IF;
 IF e.event_kind='signed' THEN
 IF EXISTS(SELECT FROM gridex_received_sources.production_contract_periods p WHERE p.company_id=e.company_id AND p.environment=e.environment AND p.metering_point_id=e.metering_point_id AND (p.end_at IS NULL OR p.end_at>e.boundary_at)) THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_overlapping_owned_period'));END IF;
 INSERT INTO gridex_received_sources.production_contract_periods(start_event_id,company_id,environment,contract_id,customer_id,metering_point_id,start_at) VALUES(e.id,e.company_id,e.environment,e.contract_id,e.customer_id,e.metering_point_id,e.boundary_at);
 ELSE
 SELECT * INTO period FROM gridex_received_sources.production_contract_periods WHERE start_event_id=e.start_event_id AND company_id=e.company_id FOR UPDATE;
 IF NOT FOUND OR period.end_event_id IS NOT NULL THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_owned_open_period_required'));END IF;
 UPDATE gridex_received_sources.production_contract_periods SET end_at=e.boundary_at,end_event_id=e.id WHERE start_event_id=period.start_event_id;
 END IF;
 INSERT INTO gridex_received_sources.production_contract_origins(event_id,intent_id,company_id,actor_user_id,outbound_request_id) VALUES(e.id,i.id,e.company_id,p_actor_user_id,p_outbound_request_id);
 RETURN jsonb_build_object('status','reserved','messageId',null,'outboundRequestId',p_outbound_request_id);
END $$;
REVOKE ALL ON FUNCTION public.ediel_reserve_production_contract_origin_v1(uuid,uuid,uuid,uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ediel_reserve_production_contract_origin_v1(uuid,uuid,uuid,uuid,uuid) TO service_role;
CREATE FUNCTION gridex_received_sources.bind_production_contract_origin_v1()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE o gridex_received_sources.production_contract_origins%rowtype;e gridex_received_sources.production_contract_events%rowtype;b jsonb;w jsonb;obj jsonb;tokens jsonb;dates jsonb;
BEGIN
 SELECT * INTO o FROM gridex_received_sources.production_contract_origins WHERE intent_id=NEW.intent_id;
 IF NOT FOUND THEN RETURN NEW;END IF;
 SELECT * INTO e FROM gridex_received_sources.production_contract_events WHERE id=o.event_id FOR SHARE;
 b:=public.ediel_production_contract_source_v1(o.company_id,e.id,o.actor_user_id);IF b->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION 'production_contract_source_changed';END IF;
 SELECT * INTO STRICT o FROM gridex_received_sources.production_contract_origins WHERE intent_id=NEW.intent_id FOR UPDATE;
 w:=gridex_received_sources.prodat_recovery_wire_v1(NEW.raw_payload);tokens:=gridex_received_sources.closure_wire_tokens_v2(NEW.raw_payload);
 IF NEW.company_id IS DISTINCT FROM e.company_id OR NEW.environment IS DISTINCT FROM e.environment OR NEW.direction IS DISTINCT FROM 'outbound' OR NEW.message_family IS DISTINCT FROM 'PRODAT' OR NEW.message_code IS DISTINCT FROM 'Z09' OR NEW.source_operation_id IS DISTINCT FROM e.id::text
 OR NEW.outbound_request_id IS DISTINCT FROM o.outbound_request_id OR NEW.customer_id IS DISTINCT FROM e.customer_id OR NEW.metering_point_id IS DISTINCT FROM e.metering_point_id OR w->>'family' IS DISTINCT FROM 'PRODAT' OR w->>'code' IS DISTINCT FROM 'Z09' OR w->>'legalSender' IS DISTINCT FROM e.legal_sender_id OR w->>'legalReceiver' IS DISTINCT FROM e.legal_receiver_id OR jsonb_array_length(w->'objects') IS DISTINCT FROM 1
 THEN RAISE EXCEPTION 'production_contract_message_scope_mismatch';END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}' IN ('FR','DO') AND (t#>>'{elements,2,1}' IS DISTINCT FROM '160' OR t#>>'{elements,2,2}' IS DISTINCT FROM 'SVK')) THEN RAISE EXCEPTION 'production_contract_legal_party_qualifier_mismatch';END IF;
 obj:=w->'objects'->0;
 IF obj->>'point' IS DISTINCT FROM e.point_id OR obj->>'identityAgency' IS DISTINCT FROM e.identity_agency OR obj->>'reason' IS DISTINCT FROM 'Z70'
 THEN RAISE EXCEPTION 'production_contract_physical_object_mismatch';END IF;
 SELECT jsonb_agg(t->'elements'->1) INTO dates FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='DTM' AND t#>>'{elements,1,0}' IN ('92','93','157');
 IF jsonb_array_length(dates) IS DISTINCT FROM 1 OR dates#>>'{0,0}' IS DISTINCT FROM (CASE e.event_kind WHEN 'signed' THEN '92' ELSE '93' END)
 OR dates#>>'{0,1}' IS DISTINCT FROM to_char(e.boundary_at AT TIME ZONE 'Etc/GMT-1','YYYYMMDDHH24MI') OR dates#>>'{0,2}' IS DISTINCT FROM '203'
 THEN RAISE EXCEPTION 'production_contract_boundary_mismatch';END IF;
 IF o.message_id IS NOT NULL AND (o.message_id IS DISTINCT FROM NEW.id OR o.payload_hash IS DISTINCT FROM encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex')) THEN RAISE EXCEPTION 'production_contract_message_already_bound' USING ERRCODE='23505';END IF;
 UPDATE gridex_received_sources.production_contract_origins SET message_id=NEW.id,payload_hash=encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex') WHERE event_id=e.id;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION gridex_received_sources.bind_production_contract_origin_v1() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER bind_production_contract_origin AFTER INSERT ON public.ediel_messages FOR EACH ROW EXECUTE FUNCTION gridex_received_sources.bind_production_contract_origin_v1();
CREATE FUNCTION public.ediel_production_contract_message_basis_v1(p_company_id uuid,p_message_id uuid,p_actor_user_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE o gridex_received_sources.production_contract_origins%rowtype;m public.ediel_messages%rowtype;b jsonb;
BEGIN
 SELECT * INTO o FROM gridex_received_sources.production_contract_origins WHERE company_id=p_company_id AND message_id=p_message_id;
 IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR SHARE;
 IF m.intent_id IS DISTINCT FROM o.intent_id OR m.source_operation_id IS DISTINCT FROM o.event_id::text OR o.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'production_contract_bound_payload_changed';END IF;
 b:=public.ediel_production_contract_source_v1(p_company_id,o.event_id,p_actor_user_id);
 IF b->>'status' IS DISTINCT FROM 'authorized' THEN RETURN b;END IF;
 RETURN jsonb_build_object('basis',b,'intentId',o.intent_id);
END $$;
REVOKE ALL ON FUNCTION public.ediel_production_contract_message_basis_v1(uuid,uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ediel_production_contract_message_basis_v1(uuid,uuid,uuid) TO service_role;
COMMIT;

20260930175405_ediel_billing_qualified_e.body:
BEGIN;
CREATE SCHEMA gridex_billing_source;
REVOKE ALL ON SCHEMA gridex_billing_source FROM PUBLIC,anon,authenticated,service_role;

-- U p97: quality belongs to the preceding own SG11/QTY; absence means
-- exact/approved. No QTY qualifier or sibling's quality is a quality decision.
CREATE FUNCTION gridex_billing_source.observation_v1(tokens jsonb,tx text,ordinal integer,decimal_mark text DEFAULT '.') RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE start_at integer;stop_at integer;first_seq integer;sequence_at integer;quantity jsonb;next_qty integer;q text;count_q integer;product text;app text;code text;register text;
 unit text;amount numeric;period text;resolution text;format text;offset_raw text;offset_mins integer;energy_index integer;duration interval;local_start timestamp;local_end timestamp;quantity_kwh numeric;period_start timestamp;period_end timestamp;
BEGIN
 SELECT (t->>'index')::integer INTO STRICT start_at FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='IDE' AND t#>>'{elements,2,0}'=tx;
 SELECT min((t->>'index')::integer) INTO stop_at FROM jsonb_array_elements(tokens) t WHERE (t->>'index')::integer>start_at AND t->>'tag' IN ('IDE','UNT');
 SELECT min((t->>'index')::integer) INTO first_seq FROM jsonb_array_elements(tokens) t WHERE (t->>'index')::integer>start_at AND (t->>'index')::integer<stop_at AND t->>'tag'='SEQ';
 SELECT t INTO quantity FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='QTY' AND (t->>'index')::integer>start_at AND (t->>'index')::integer<stop_at ORDER BY (t->>'index')::integer OFFSET ordinal LIMIT 1;
 IF quantity IS NULL OR first_seq IS NULL THEN RETURN NULL; END IF;
 SELECT coalesce(min((t->>'index')::integer),stop_at) INTO next_qty FROM jsonb_array_elements(tokens) t WHERE (t->>'index')::integer>(quantity->>'index')::integer AND (t->>'index')::integer<stop_at AND t->>'tag' IN ('QTY','SEQ');
 SELECT count(*),min(t#>>'{elements,2,0}') INTO count_q,q FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='STS' AND t#>>'{elements,1,0}'='8' AND (t->>'index')::integer>(quantity->>'index')::integer AND (t->>'index')::integer<next_qty;
 IF count_q>1 OR (count_q=1 AND (q IS NULL OR q NOT IN ('21','46','56','113','125'))) THEN RETURN NULL; END IF;
 SELECT t#>>'{elements,3,0}' INTO product FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN' AND (t->>'index')::integer>start_at AND (t->>'index')::integer<first_seq;
 SELECT max((t->>'index')::integer) INTO sequence_at FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='SEQ' AND (t->>'index')::integer< (quantity->>'index')::integer AND (t->>'index')::integer>=first_seq;
 SELECT t#>>'{elements,1,1}' INTO register FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='AES' AND (t->>'index')::integer>sequence_at AND (t->>'index')::integer<(quantity->>'index')::integer;
 SELECT t#>>'{elements,3,0}' INTO unit FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='MEA' AND (t->>'index')::integer>start_at AND (t->>'index')::integer<first_seq;
 amount:=gridex_utilts_binding.canonical_decimal_v2(quantity#>>'{elements,1,1}',decimal_mark)::numeric;
 quantity_kwh:=amount*CASE unit WHEN 'KWH' THEN 1 WHEN 'MWH' THEN 1000 WHEN 'GWH' THEN 1000000 END;
 SELECT t#>>'{elements,1,1}' INTO period FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='DTM' AND t#>>'{elements,1,0}'='324' AND t#>>'{elements,1,2}'='719' AND (t->>'index')::integer>start_at AND (t->>'index')::integer<first_seq;
 SELECT t#>>'{elements,1,1}',t#>>'{elements,1,2}' INTO resolution,format FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='DTM' AND t#>>'{elements,1,0}'='354' AND (t->>'index')::integer>start_at AND (t->>'index')::integer<first_seq;
 SELECT t#>>'{elements,1,1}' INTO STRICT offset_raw FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='DTM' AND t#>>'{elements,1,0}'='735' AND t#>>'{elements,1,2}'='406' AND (t->>'index')::integer<start_at;
 IF period !~ '^[0-9]{24}$' OR offset_raw !~ '^[+-][0-9]{4}$' OR resolution !~ '^[0-9]+$' THEN RETURN NULL; END IF;
 IF substring(offset_raw,2,2)::integer>23 OR substring(offset_raw,4,2)::integer>59 THEN RETURN NULL; END IF;
 period_start:=to_timestamp(left(period,12),'YYYYMMDDHH24MI')::timestamp;period_end:=to_timestamp(right(period,12),'YYYYMMDDHH24MI')::timestamp;
 IF to_char(period_start,'YYYYMMDDHH24MI') IS DISTINCT FROM left(period,12) OR to_char(period_end,'YYYYMMDDHH24MI') IS DISTINCT FROM right(period,12) OR period_end<=period_start THEN RETURN NULL; END IF;
 offset_mins:=(substring(offset_raw,2,2)::integer*60+substring(offset_raw,4,2)::integer)*CASE left(offset_raw,1) WHEN '-' THEN -1 ELSE 1 END;
 duration:=CASE format WHEN '806' THEN make_interval(mins=>resolution::integer) WHEN '805' THEN make_interval(hours=>resolution::integer) WHEN '802' THEN make_interval(months=>resolution::integer) WHEN '801' THEN make_interval(years=>resolution::integer) END;
 IF duration IS NULL OR duration<=interval '0' THEN RETURN NULL; END IF;
 SELECT count(*) INTO energy_index FROM jsonb_array_elements(tokens) prior_qty WHERE prior_qty->>'tag'='QTY' AND prior_qty#>>'{elements,1,0}'='136'
  AND (prior_qty->>'index')::integer>start_at AND (prior_qty->>'index')::integer<(quantity->>'index')::integer
  AND (SELECT ref#>>'{elements,1,1}' FROM jsonb_array_elements(tokens) ref WHERE ref->>'tag'='RFF' AND ref#>>'{elements,1,0}'='AES'
    AND (ref->>'index')::integer>(SELECT max((seq->>'index')::integer) FROM jsonb_array_elements(tokens) seq WHERE seq->>'tag'='SEQ' AND (seq->>'index')::integer<(prior_qty->>'index')::integer AND (seq->>'index')::integer>=first_seq)
    AND (ref->>'index')::integer<(prior_qty->>'index')::integer) IS NOT DISTINCT FROM register;
 local_start:=period_start+duration*energy_index;
 local_end:=local_start+duration;
 IF local_end>period_end THEN RETURN NULL; END IF;
 SELECT t#>>'{elements,7,0}' INTO STRICT app FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNB';
 SELECT t#>>'{elements,1,0}' INTO STRICT code FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM';
 RETURN jsonb_build_object('quantityType',quantity#>>'{elements,1,0}','quantityKwh',gridex_utilts_binding.canonical_decimal_v2(quantity_kwh::text),'quality',q,'qualityEstablished',true,'productCode',nullif(product,''),'registerCode',nullif(register,''),'applicationReference',app,'messageCode',code,
  'periodStart',(local_start-make_interval(mins=>offset_mins)) AT TIME ZONE 'UTC','periodEnd',(local_end-make_interval(mins=>offset_mins)) AT TIME ZONE 'UTC');
EXCEPTION WHEN no_data_found OR too_many_rows OR invalid_parameter_value OR datetime_field_overflow THEN RETURN NULL;
END $$;

-- Discovery never grants authority. Lock every discovered physical source first,
-- then meter values, normalized values and supply period. Re-read the discovery
-- under those locks; a concurrent reassignment/revision is retried, never followed
-- by acquiring a new source lock after the consumer rows.
CREATE FUNCTION gridex_billing_source.lock_values_v1(p_company uuid,p_values uuid[],p_period uuid DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE discovery jsonb;actual jsonb;period_before jsonb;period_after jsonb;sources uuid[];meters uuid[];
BEGIN
 SELECT jsonb_agg(jsonb_build_object('id',n.id,'source',n.source_message_id,'meter',n.source_metering_value_id) ORDER BY n.id),array_agg(DISTINCT n.source_message_id),array_agg(DISTINCT n.source_metering_value_id)
 INTO discovery,sources,meters FROM public.normalized_metering_values n WHERE n.company_id=p_company AND n.id=ANY(p_values);
 IF jsonb_array_length(coalesce(discovery,'[]'))<>cardinality(p_values) THEN RAISE EXCEPTION 'billing_source_value_missing' USING ERRCODE='P0002'; END IF;
 IF p_period IS NOT NULL THEN
  SELECT to_jsonb(p) INTO period_before FROM public.customer_supply_periods p WHERE p.company_id=p_company AND p.id=p_period;
  sources:=sources||ARRAY(SELECT t.source_message_id FROM gridex_received_sources.supply_source_transitions t WHERE t.company_id=p_company AND
   (t.source_message_id=(period_before->>'source_message_id')::uuid OR EXISTS(SELECT FROM jsonb_array_elements(t.resulting_states) own WHERE own->>'id'=p_period::text AND (own->>'market_state_version')::bigint=(period_before->>'market_state_version')::bigint)));
 END IF;
 PERFORM s.id FROM public.ediel_messages s WHERE s.company_id=p_company AND s.id=ANY(sources) ORDER BY s.id FOR UPDATE;
 PERFORM m.id FROM public.metering_values m WHERE m.company_id=p_company AND m.id=ANY(meters) ORDER BY m.id FOR SHARE;
 PERFORM n.id FROM public.normalized_metering_values n WHERE n.company_id=p_company AND n.id=ANY(p_values) ORDER BY n.id FOR UPDATE;
 SELECT jsonb_agg(jsonb_build_object('id',n.id,'source',n.source_message_id,'meter',n.source_metering_value_id) ORDER BY n.id) INTO actual FROM public.normalized_metering_values n WHERE n.company_id=p_company AND n.id=ANY(p_values);
 IF actual IS DISTINCT FROM discovery THEN RAISE EXCEPTION 'billing_source_discovery_changed' USING ERRCODE='40001'; END IF;
 IF p_period IS NOT NULL THEN
  SELECT to_jsonb(p) INTO period_after FROM public.customer_supply_periods p WHERE p.company_id=p_company AND p.id=p_period FOR SHARE;
  IF period_after IS DISTINCT FROM period_before THEN RAISE EXCEPTION 'billing_supply_discovery_changed' USING ERRCODE='40001'; END IF;
 END IF;
END $$;

CREATE FUNCTION gridex_billing_source.basis_v1(p_company uuid,p_value uuid) RETURNS jsonb
LANGUAGE plpgsql SET search_path=pg_catalog,public,extensions AS $$
DECLARE n public.normalized_metering_values%rowtype;m public.metering_values%rowtype;s public.ediel_messages%rowtype;
 c jsonb;o jsonb;physical jsonb;basis jsonb;rule_basis jsonb;ordinal integer;source_ordinal integer;qualified boolean:=false;why text:='billing_source_binding_unavailable';
BEGIN
 PERFORM gridex_billing_source.lock_values_v1(p_company,ARRAY[p_value]);
 SELECT * INTO n FROM public.normalized_metering_values WHERE company_id=p_company AND id=p_value;
 IF n.id IS NULL THEN RAISE EXCEPTION 'billing_source_value_missing' USING ERRCODE='P0002'; END IF;
 basis:=jsonb_build_object('version',1,'qualified',false,'reason',why,'normalizedValueId',n.id,'sourceMessageId',n.source_message_id,
 'quantityKwh',gridex_utilts_binding.canonical_decimal_v2(n.quantity_kwh::text),'quantityType',null,'quality',null,'qualityEstablished',false,'productCode',n.product_code,'contractHash',null,'sourcePayloadHash',null,'observationOrdinal',null);
 SELECT * INTO m FROM public.metering_values WHERE id=n.source_metering_value_id AND company_id=p_company FOR SHARE;
 SELECT * INTO s FROM public.ediel_messages WHERE id=n.source_message_id AND company_id=p_company FOR SHARE;
 IF m.id IS NULL OR s.id IS NULL OR s.direction IS DISTINCT FROM 'inbound' OR s.message_family IS DISTINCT FROM 'UTILTS' OR NOT coalesce(s.message_code IN ('E30','E66'),false)
  OR n.source_transaction_reference IS NULL OR n.revision_status IS DISTINCT FROM 'current' OR m.is_current IS DISTINCT FROM true OR m.revision_status IS DISTINCT FROM 'current'
  OR n.quantity_kwh IS DISTINCT FROM m.value_kwh OR n.period_start IS DISTINCT FROM m.period_start OR n.period_end IS DISTINCT FROM m.period_end
  OR n.unit IS DISTINCT FROM 'kWh' OR n.direction IS DISTINCT FROM m.direction OR n.quality_status IS DISTINCT FROM m.quality_code
  OR n.source_message_id IS DISTINCT FROM m.source_ediel_message_id OR n.source_transaction_reference IS DISTINCT FROM m.source_transaction_reference
  OR n.metering_point_id IS DISTINCT FROM m.metering_point_id OR n.customer_id IS DISTINCT FROM m.customer_id
  OR n.raw_payload IS DISTINCT FROM m.raw_payload THEN RETURN basis; END IF;
 c:=gridex_utilts_binding.stored_contract_v1(p_company,s.id,n.source_transaction_reference);
 BEGIN rule_basis:=gridex_ediel_source_rules.require_v1(p_company,s.id);
 EXCEPTION WHEN raise_exception THEN
  IF SQLERRM IN ('ediel_historical_rule_pack_basis_unavailable','ediel_source_rule_pack_basis_required') THEN RETURN basis||jsonb_build_object('reason',SQLERRM); END IF;
  RAISE;
 END;
 IF n.raw_payload->'consumptionContract' IS DISTINCT FROM c OR n.raw_payload->>'edielMessageId' IS DISTINCT FROM s.id::text
  OR c#>>'{metering,capability}' IS DISTINCT FROM 'write' OR c#>>'{metering,meteringPointId}' IS DISTINCT FROM n.metering_point_id::text
  OR c#>>'{metering,customerId}' IS DISTINCT FROM n.customer_id::text THEN RETURN basis; END IF;
 source_ordinal:=(n.raw_payload->>'sourceOrdinal')::integer;
 SELECT value,(value->>'ordinal')::integer INTO STRICT o,ordinal FROM jsonb_array_elements(c->'observations') WHERE (value->>'sourceOrdinal')::integer=source_ordinal;
 physical:=gridex_billing_source.observation_v1(gridex_utilts_binding.wire_tokens_v1(s.raw_payload),n.source_transaction_reference,source_ordinal,CASE WHEN left(s.raw_payload,3)='UNA' THEN substring(s.raw_payload,6,1) ELSE '.' END);
 IF physical IS NULL THEN RETURN basis; END IF;
 -- This is a new billing projection, not a rewrite of the immutable consumer
 -- contract or its historical ACK. The authentic raw/hash/own ordinal and
 -- original rule basis independently establish previously lossy diagnostics.
 basis:=basis||jsonb_build_object('projectionVersion','ediel-billing-source-v1','quantityType',physical->'quantityType','quality',physical->'quality','qualityEstablished',true,'productCode',physical->'productCode','registerCode',physical->'registerCode','sourceRulePackBasis',rule_basis,
  'retainedProjection',jsonb_build_object('quality',n.quality_status,'productCode',n.product_code,'registerCode',n.register_code),
  'contractHash',encode(digest(convert_to(c::text,'UTF8'),'sha256'),'hex'),'sourcePayloadHash',encode(digest(convert_to(s.raw_payload,'UTF8'),'sha256'),'hex'),'observationOrdinal',ordinal);
 IF o->>'unit' IS DISTINCT FROM 'kWh' OR (o->>'quantity')::numeric IS DISTINCT FROM n.quantity_kwh
  OR (o->>'periodStart')::timestamptz IS DISTINCT FROM n.period_start OR (o->>'periodEnd')::timestamptz IS DISTINCT FROM n.period_end
  OR o->>'direction' IS DISTINCT FROM n.direction OR o->>'quality' IS DISTINCT FROM n.quality_status
  OR o->>'productCode' IS DISTINCT FROM n.product_code OR o->>'registerCode' IS DISTINCT FROM n.register_code
  OR (physical->>'quantityKwh')::numeric IS DISTINCT FROM n.quantity_kwh OR (physical->>'periodStart')::timestamptz IS DISTINCT FROM n.period_start OR (physical->>'periodEnd')::timestamptz IS DISTINCT FROM n.period_end
  OR physical->>'messageCode' IS DISTINCT FROM s.message_code OR physical->>'quantityType' IS DISTINCT FROM '136'
  OR NOT coalesce(physical->>'applicationReference' IN ('23-DDQ-E66-S','23-DDQ-E66-T'),false) THEN why:='billing_source_semantics_mismatch';
 ELSIF s.message_code='E66' AND physical->>'productCode' IS DISTINCT FROM '8716867000030' THEN why:='billing_product_not_individual_active_energy';
 ELSE qualified:=true;why:=NULL; END IF;
 RETURN basis||jsonb_build_object('qualified',qualified,'reason',why);
EXCEPTION WHEN SQLSTATE 'P0U01' OR no_data_found OR too_many_rows OR invalid_text_representation OR numeric_value_out_of_range THEN RETURN basis;
END $$;

CREATE FUNCTION public.gridex_read_billing_source_values_v1(p_company_id uuid,p_value_ids uuid[]) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE n public.normalized_metering_values%rowtype;s public.ediel_messages%rowtype;b jsonb;result jsonb:='[]';
BEGIN
 IF coalesce(current_setting('role',true),'')<>'service_role' AND current_user<>'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF p_company_id IS NULL OR p_value_ids IS NULL OR cardinality(p_value_ids)>1000 OR array_position(p_value_ids,NULL) IS NOT NULL THEN RAISE EXCEPTION 'billing_source_scope_required' USING ERRCODE='22023'; END IF;
 PERFORM gridex_billing_source.lock_values_v1(p_company_id,p_value_ids);
 FOR n IN SELECT * FROM public.normalized_metering_values WHERE company_id=p_company_id AND id=ANY(p_value_ids) ORDER BY id LOOP
  b:=gridex_billing_source.basis_v1(p_company_id,n.id);
  SELECT * INTO s FROM public.ediel_messages WHERE id=n.source_message_id AND company_id=p_company_id;
  result:=result||jsonb_build_array(to_jsonb(n)||jsonb_build_object('quantity_kwh',b->'quantityKwh','product_code',CASE WHEN b->'qualified'='true'::jsonb THEN b->'productCode' ELSE to_jsonb(n.product_code) END,'register_code',CASE WHEN b->'qualified'='true'::jsonb THEN b->'registerCode' ELSE to_jsonb(n.register_code) END,'quality_status',CASE WHEN b->'qualified'='true'::jsonb THEN b->'quality' ELSE to_jsonb(n.quality_status) END,
   'billing_source_basis',b,'billing_source_message',CASE WHEN s.id IS NULL THEN NULL ELSE jsonb_build_object('id',s.id,'company_id',s.company_id,'message_family',s.message_family,'message_code',s.message_code,'status',s.status) END));
 END LOOP;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.gridex_read_billing_source_values_v1(uuid,uuid[]) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.gridex_read_billing_source_values_v1(uuid,uuid[]) TO service_role;

ALTER FUNCTION public.gridex_set_metering_billing_gate(uuid,uuid,uuid,jsonb) RENAME TO gridex_set_metering_billing_gate_before_source_v2;
ALTER FUNCTION public.gridex_set_metering_billing_gate_before_source_v2(uuid,uuid,uuid,jsonb) SET SCHEMA gridex_billing_source;
CREATE FUNCTION public.gridex_set_metering_billing_gate(p_company_id uuid,p_metering_value_id uuid,p_normalized_value_id uuid,p_gate jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE b jsonb;legal_basis jsonb;n public.normalized_metering_values%rowtype;sp public.customer_supply_periods%rowtype;ct public.customer_contracts%rowtype;
BEGIN
 IF coalesce(current_setting('role',true),'')<>'service_role' AND current_user<>'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF p_company_id IS NULL OR p_metering_value_id IS NULL OR p_normalized_value_id IS NULL OR p_gate IS NULL THEN RAISE EXCEPTION 'billing_gate_scope_required' USING ERRCODE='22023'; END IF;
 PERFORM gridex_billing_source.lock_values_v1(p_company_id,ARRAY[p_normalized_value_id],nullif(p_gate->>'supply_period_id','')::uuid);
 SELECT * INTO n FROM public.normalized_metering_values WHERE company_id=p_company_id AND id=p_normalized_value_id AND source_metering_value_id=p_metering_value_id;
 IF n.id IS NULL THEN RAISE EXCEPTION 'billing_gate_value_scope_mismatch'; END IF;
 IF p_gate->>'billing_status'='billable' OR p_gate->>'billing_gate_status'='eligible' THEN
  b:=gridex_billing_source.basis_v1(p_company_id,n.id);
  IF b->'qualified' IS DISTINCT FROM 'true'::jsonb OR b->'qualityEstablished' IS DISTINCT FROM 'true'::jsonb OR b->'quality' IS DISTINCT FROM 'null'::jsonb
   OR p_gate->>'source_message_id' IS DISTINCT FROM n.source_message_id::text THEN RAISE EXCEPTION 'billing_gate_qualified_final_source_required' USING ERRCODE='23514'; END IF;
  SELECT * INTO sp FROM public.customer_supply_periods WHERE id=(p_gate->>'supply_period_id')::uuid AND company_id=p_company_id FOR SHARE;
  SELECT * INTO ct FROM public.customer_contracts WHERE id=sp.contract_id AND company_id=p_company_id FOR SHARE;
  IF sp.id IS NULL OR ct.id IS NULL OR NOT coalesce(sp.status IN ('active','confirmed_by_grid_owner'),false) OR NOT coalesce(ct.status IN ('signed','active'),false)
   OR sp.customer_id IS DISTINCT FROM n.customer_id OR sp.metering_point_id IS DISTINCT FROM n.metering_point_id OR ct.customer_id IS DISTINCT FROM n.customer_id OR ct.metering_point_id IS DISTINCT FROM n.metering_point_id
   OR sp.start_date IS NULL OR (sp.start_date::timestamp AT TIME ZONE 'Europe/Stockholm')>n.period_start
   OR (sp.end_date IS NOT NULL AND ((sp.end_date+1)::timestamp AT TIME ZONE 'Europe/Stockholm')<n.period_end)
   OR nullif(coalesce(to_jsonb(ct)->>'starts_at',to_jsonb(ct)->>'start_date'),'') IS NULL
   OR (left(coalesce(to_jsonb(ct)->>'starts_at',to_jsonb(ct)->>'start_date'),10)::date::timestamp AT TIME ZONE 'Europe/Stockholm')>n.period_start
   OR (nullif(coalesce(to_jsonb(ct)->>'ends_at',to_jsonb(ct)->>'end_date'),'') IS NOT NULL AND ((left(coalesce(to_jsonb(ct)->>'ends_at',to_jsonb(ct)->>'end_date'),10)::date+1)::timestamp AT TIME ZONE 'Europe/Stockholm')<n.period_end)
   THEN RAISE EXCEPTION 'billing_gate_supply_contract_scope_mismatch' USING ERRCODE='23514'; END IF;
  legal_basis:=gridex_received_sources.billing_supply_basis_v1(p_company_id,sp.id,n.period_start,n.period_end);
  IF legal_basis IS NULL OR legal_basis->'qualified' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'billing_gate_qualified_supply_source_required' USING ERRCODE='23514'; END IF;
  p_gate:=p_gate||jsonb_build_object('billing_gate_snapshot',coalesce(p_gate->'billing_gate_snapshot','{}')||jsonb_build_object('source_basis',b,'supply_source_basis',legal_basis));
 END IF;
 RETURN gridex_billing_source.gridex_set_metering_billing_gate_before_source_v2(p_company_id,p_metering_value_id,p_normalized_value_id,p_gate);
END $$;
REVOKE ALL ON FUNCTION public.gridex_set_metering_billing_gate(uuid,uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.gridex_set_metering_billing_gate(uuid,uuid,uuid,jsonb) TO service_role;

CREATE TABLE gridex_billing_source.underlay_bindings(
 underlay_id uuid PRIMARY KEY REFERENCES public.billing_underlays(id),company_id uuid NOT NULL,
 source_basis jsonb NOT NULL,source_basis_hash text NOT NULL,exact_total_kwh numeric NOT NULL,finalized_at timestamptz NOT NULL DEFAULT clock_timestamp(),actor_user_id uuid
);
CREATE TABLE gridex_billing_source.correction_journal(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,underlay_id uuid NOT NULL REFERENCES gridex_billing_source.underlay_bindings(underlay_id),
 previous_normalized_value_id uuid NOT NULL REFERENCES public.normalized_metering_values(id),new_normalized_value_id uuid NOT NULL REFERENCES public.normalized_metering_values(id),
 old_source_basis_hash text NOT NULL,new_source_message_id uuid,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(underlay_id,new_normalized_value_id)
);
ALTER TABLE gridex_billing_source.underlay_bindings ENABLE ROW LEVEL SECURITY;
ALTER TABLE gridex_billing_source.underlay_bindings FORCE ROW LEVEL SECURITY;
ALTER TABLE gridex_billing_source.correction_journal ENABLE ROW LEVEL SECURITY;
ALTER TABLE gridex_billing_source.correction_journal FORCE ROW LEVEL SECURITY;
