CREATE TRIGGER immutable_update_delete BEFORE UPDATE OR DELETE ON gridex_billing_source.underlay_bindings FOR EACH ROW EXECUTE FUNCTION gridex_received_sources.reject_mutation();
CREATE TRIGGER immutable_truncate BEFORE TRUNCATE ON gridex_billing_source.underlay_bindings FOR EACH STATEMENT EXECUTE FUNCTION gridex_received_sources.reject_mutation();
CREATE TRIGGER immutable_update_delete BEFORE UPDATE OR DELETE ON gridex_billing_source.correction_journal FOR EACH ROW EXECUTE FUNCTION gridex_received_sources.reject_mutation();
CREATE TRIGGER immutable_truncate BEFORE TRUNCATE ON gridex_billing_source.correction_journal FOR EACH STATEMENT EXECUTE FUNCTION gridex_received_sources.reject_mutation();
CREATE FUNCTION gridex_billing_source.capture_correction_v1() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
 INSERT INTO gridex_billing_source.correction_journal(company_id,underlay_id,previous_normalized_value_id,new_normalized_value_id,old_source_basis_hash,new_source_message_id)
 SELECT new.company_id,b.underlay_id,previous.id,new.id,b.source_basis_hash,new.source_message_id FROM public.normalized_metering_values previous
 JOIN public.billing_underlay_items i ON i.source_normalized_metering_value_id=previous.id AND i.company_id=new.company_id
 JOIN gridex_billing_source.underlay_bindings b ON b.underlay_id=i.billing_underlay_id AND b.company_id=new.company_id
 WHERE previous.company_id=new.company_id AND (previous.id=new.previous_value_id OR previous.source_metering_value_id=new.previous_value_id) ON CONFLICT DO NOTHING;
 RETURN new;
END $$;
CREATE TRIGGER billing_source_correction_journal AFTER INSERT ON public.normalized_metering_values FOR EACH ROW EXECUTE FUNCTION gridex_billing_source.capture_correction_v1();

CREATE FUNCTION gridex_billing_source.protect_underlay_v1() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
 IF EXISTS(SELECT FROM gridex_billing_source.underlay_bindings WHERE underlay_id=old.id) AND (tg_op='DELETE' OR
  ROW(new.company_id,new.customer_id,new.metering_point_id,new.supply_period_id,new.contract_id,new.pricing_snapshot_id,new.contract_price_snapshot_id,new.total_kwh,new.billing_period_start,new.billing_period_end,new.payload,new.pricing_snapshot,new.energy_direction,new.settlement_type)
  IS DISTINCT FROM ROW(old.company_id,old.customer_id,old.metering_point_id,old.supply_period_id,old.contract_id,old.pricing_snapshot_id,old.contract_price_snapshot_id,old.total_kwh,old.billing_period_start,old.billing_period_end,old.payload,old.pricing_snapshot,old.energy_direction,old.settlement_type)) THEN RAISE EXCEPTION 'billing_source_finalized_underlay_immutable' USING ERRCODE='55000'; END IF;
 RETURN CASE WHEN tg_op='DELETE' THEN old ELSE new END;
END $$;
CREATE TRIGGER billing_source_finalized_immutable BEFORE UPDATE OR DELETE ON public.billing_underlays FOR EACH ROW EXECUTE FUNCTION gridex_billing_source.protect_underlay_v1();
CREATE FUNCTION gridex_billing_source.protect_items_v1() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
 IF EXISTS(SELECT FROM gridex_billing_source.underlay_bindings WHERE underlay_id=CASE WHEN tg_op='INSERT' THEN new.billing_underlay_id ELSE old.billing_underlay_id END)
  OR (tg_op='UPDATE' AND EXISTS(SELECT FROM gridex_billing_source.underlay_bindings WHERE underlay_id=new.billing_underlay_id)) THEN RAISE EXCEPTION 'billing_source_finalized_items_immutable' USING ERRCODE='55000'; END IF;
 RETURN CASE WHEN tg_op='DELETE' THEN old ELSE new END;
END $$;
CREATE TRIGGER billing_source_finalized_immutable BEFORE INSERT OR UPDATE OR DELETE ON public.billing_underlay_items FOR EACH ROW EXECUTE FUNCTION gridex_billing_source.protect_items_v1();

ALTER FUNCTION public.gridex_store_billing_underlay(uuid,jsonb,jsonb,uuid) RENAME TO gridex_store_billing_underlay_before_source_v2;
ALTER FUNCTION public.gridex_store_billing_underlay_before_source_v2(uuid,jsonb,jsonb,uuid) SET SCHEMA gridex_billing_source;
CREATE FUNCTION public.gridex_store_billing_underlay(p_company_id uuid,p_underlay jsonb,p_items jsonb,p_actor_user_id uuid DEFAULT NULL) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,extensions AS $$
DECLARE item jsonb;basis jsonb;legal_basis jsonb;rows_basis jsonb:='[]';source_basis jsonb;basis_hash text;total numeric:=0;u public.billing_underlays%rowtype;
 n public.normalized_metering_values%rowtype;sp public.customer_supply_periods%rowtype;ct public.customer_contracts%rowtype;price public.contract_price_snapshots%rowtype;pv public.price_plan_versions%rowtype;
 prior gridex_billing_source.underlay_bindings%rowtype;stored_id uuid;start_at timestamptz;end_at timestamptz;ready boolean;
BEGIN
 IF coalesce(current_setting('role',true),'')<>'service_role' AND current_user<>'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF p_company_id IS NULL OR p_underlay IS NULL OR jsonb_typeof(p_items) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'billing_underlay_scope_required' USING ERRCODE='22023'; END IF;
 start_at:=(p_underlay->>'billing_period_start')::timestamptz;end_at:=(p_underlay->>'billing_period_end')::timestamptz;
 IF start_at IS NULL OR end_at IS NULL OR end_at<=start_at THEN RAISE EXCEPTION 'billing_underlay_exact_period_required' USING ERRCODE='22023'; END IF;
 ready:=p_underlay->>'status'='validated' OR p_underlay->>'readiness_status'='ready';
 PERFORM pg_advisory_xact_lock(hashtextextended(p_company_id::text||':billing-underlay-batch',0));
 SELECT * INTO u FROM public.billing_underlays WHERE company_id=p_company_id AND customer_id=(p_underlay->>'customer_id')::uuid AND metering_point_id=(p_underlay->>'metering_point_id')::uuid
  AND underlay_year=(p_underlay->>'underlay_year')::integer AND underlay_month=(p_underlay->>'underlay_month')::integer
  AND billing_period_start=(start_at AT TIME ZONE 'Europe/Stockholm')::date AND billing_period_end=(end_at AT TIME ZONE 'Europe/Stockholm')::date AND energy_direction=p_underlay->>'energy_direction';
 SELECT * INTO prior FROM gridex_billing_source.underlay_bindings WHERE underlay_id=u.id;
 IF NOT ready THEN
  PERFORM 1 FROM public.billing_underlays WHERE id=u.id FOR UPDATE;
  IF prior.underlay_id IS NOT NULL THEN RAISE EXCEPTION 'billing_source_finalized_underlay_requires_correction' USING ERRCODE='55000'; END IF;
  RETURN gridex_billing_source.gridex_store_billing_underlay_before_source_v2(p_company_id,p_underlay,p_items,p_actor_user_id);
 END IF;
 IF jsonb_array_length(p_items)=0 OR (SELECT count(DISTINCT value->>'source_normalized_metering_value_id') FROM jsonb_array_elements(p_items))<>jsonb_array_length(p_items) THEN RAISE EXCEPTION 'billing_underlay_unique_sources_required'; END IF;
 PERFORM gridex_billing_source.lock_values_v1(p_company_id,ARRAY(SELECT (value->>'source_normalized_metering_value_id')::uuid FROM jsonb_array_elements(p_items)),(p_underlay->>'supply_period_id')::uuid);
 SELECT * INTO sp FROM public.customer_supply_periods WHERE id=(p_underlay->>'supply_period_id')::uuid AND company_id=p_company_id FOR SHARE;
 SELECT * INTO ct FROM public.customer_contracts WHERE id=(p_underlay->>'contract_id')::uuid AND company_id=p_company_id FOR SHARE;
 SELECT * INTO price FROM public.contract_price_snapshots WHERE id=(p_underlay->>'contract_price_snapshot_id')::uuid AND company_id=p_company_id FOR SHARE;
 SELECT * INTO pv FROM public.price_plan_versions WHERE id=price.price_plan_version_id AND company_id=p_company_id FOR SHARE;
 IF sp.id IS NULL OR ct.id IS NULL OR price.id IS NULL OR pv.id IS NULL OR pv.locked_at IS NULL OR NOT coalesce(pv.content_sha256 ~ '^[a-f0-9]{64}$',false) OR NOT coalesce(pv.status IN ('active','approved','published'),false)
  OR sp.contract_id IS DISTINCT FROM ct.id OR sp.customer_id IS DISTINCT FROM ct.customer_id OR sp.metering_point_id IS DISTINCT FROM ct.metering_point_id
  OR NOT coalesce(sp.status IN ('active','confirmed_by_grid_owner'),false) OR NOT coalesce(ct.status IN ('signed','active'),false) OR price.contract_id IS DISTINCT FROM ct.id
  OR sp.customer_id::text IS DISTINCT FROM p_underlay->>'customer_id' OR sp.metering_point_id::text IS DISTINCT FROM p_underlay->>'metering_point_id'
  OR price.id::text IS DISTINCT FROM p_underlay->>'pricing_snapshot_id' OR price.price_plan_version_id::text IS DISTINCT FROM p_underlay->>'price_plan_version_id'
  OR price.snapshot_json IS DISTINCT FROM p_underlay->'pricing_snapshot' OR price.valid_from IS NULL OR (price.valid_from::timestamp AT TIME ZONE 'Europe/Stockholm')>start_at
  OR (price.valid_to IS NOT NULL AND ((price.valid_to+1)::timestamp AT TIME ZONE 'Europe/Stockholm')<end_at)
  OR sp.start_date IS NULL OR (sp.start_date::timestamp AT TIME ZONE 'Europe/Stockholm')>start_at OR (sp.end_date IS NOT NULL AND ((sp.end_date+1)::timestamp AT TIME ZONE 'Europe/Stockholm')<end_at)
  OR nullif(coalesce(to_jsonb(ct)->>'starts_at',to_jsonb(ct)->>'start_date'),'') IS NULL
  OR (left(coalesce(to_jsonb(ct)->>'starts_at',to_jsonb(ct)->>'start_date'),10)::date::timestamp AT TIME ZONE 'Europe/Stockholm')>start_at
  OR (nullif(coalesce(to_jsonb(ct)->>'ends_at',to_jsonb(ct)->>'end_date'),'') IS NOT NULL AND ((left(coalesce(to_jsonb(ct)->>'ends_at',to_jsonb(ct)->>'end_date'),10)::date+1)::timestamp AT TIME ZONE 'Europe/Stockholm')<end_at)
 THEN RAISE EXCEPTION 'billing_underlay_supply_contract_price_basis_required' USING ERRCODE='23514'; END IF;
 legal_basis:=gridex_received_sources.billing_supply_basis_v1(p_company_id,sp.id,start_at,end_at);
 IF legal_basis IS NULL OR legal_basis->'qualified' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'billing_underlay_qualified_supply_source_required' USING ERRCODE='23514'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_items) ORDER BY value->>'source_normalized_metering_value_id' LOOP
  SELECT * INTO n FROM public.normalized_metering_values WHERE company_id=p_company_id AND id=(item->>'source_normalized_metering_value_id')::uuid FOR SHARE;
  basis:=gridex_billing_source.basis_v1(p_company_id,n.id);
  IF basis->'qualified' IS DISTINCT FROM 'true'::jsonb OR basis->'quality' IS DISTINCT FROM 'null'::jsonb OR basis->'qualityEstablished' IS DISTINCT FROM 'true'::jsonb
   OR n.billing_gate_status IS DISTINCT FROM 'eligible' OR n.billing_status IS DISTINCT FROM 'billable' OR n.supply_period_id IS DISTINCT FROM sp.id
   OR n.customer_id IS DISTINCT FROM sp.customer_id OR n.metering_point_id IS DISTINCT FROM sp.metering_point_id OR n.period_start<start_at OR n.period_end>end_at
   OR (item->>'quantity_kwh')::numeric IS DISTINCT FROM abs(n.quantity_kwh) OR (item->>'quantity')::numeric IS DISTINCT FROM abs(n.quantity_kwh)
   OR item->>'unit' IS DISTINCT FROM 'kWh' OR item->>'product_code' IS DISTINCT FROM basis->>'productCode' OR item->>'register_code' IS DISTINCT FROM basis->>'registerCode'
   OR p_underlay->>'energy_direction' IS DISTINCT FROM (CASE WHEN n.direction='production' THEN 'production' WHEN n.quantity_kwh<0 THEN 'consumption_correction' ELSE 'consumption' END)
   OR (item->>'period_start')::timestamptz IS DISTINCT FROM n.period_start OR (item->>'period_end')::timestamptz IS DISTINCT FROM n.period_end
  THEN RAISE EXCEPTION 'billing_underlay_qualified_source_mismatch' USING ERRCODE='23514'; END IF;
  total:=total+abs(n.quantity_kwh);rows_basis:=rows_basis||jsonb_build_array(basis||jsonb_build_object('revisionNumber',n.revision_number,'supplyPeriodId',sp.id));
 END LOOP;
 IF total IS DISTINCT FROM (p_underlay->>'total_kwh')::numeric THEN RAISE EXCEPTION 'billing_underlay_exact_total_mismatch'; END IF;
 source_basis:=jsonb_build_object('values',rows_basis,'supply',legal_basis,'contractId',ct.id,'contractStatus',ct.status,'price',to_jsonb(price),'priceVersionHash',pv.content_sha256,'energyDirection',p_underlay->>'energy_direction','start',start_at,'end',end_at);
 basis_hash:=encode(digest(convert_to(source_basis::text,'UTF8'),'sha256'),'hex');
 PERFORM 1 FROM public.billing_underlays WHERE id=u.id FOR UPDATE;
 IF prior.underlay_id IS NOT NULL THEN
  IF prior.source_basis_hash IS DISTINCT FROM basis_hash OR prior.exact_total_kwh IS DISTINCT FROM total THEN RAISE EXCEPTION 'billing_source_finalized_underlay_requires_correction' USING ERRCODE='55000'; END IF;
  RETURN prior.underlay_id;
 END IF;
 stored_id:=gridex_billing_source.gridex_store_billing_underlay_before_source_v2(p_company_id,p_underlay,p_items,p_actor_user_id);
 INSERT INTO gridex_billing_source.underlay_bindings(underlay_id,company_id,source_basis,source_basis_hash,exact_total_kwh,actor_user_id) VALUES(stored_id,p_company_id,source_basis,basis_hash,total,p_actor_user_id);
 RETURN stored_id;
END $$;
REVOKE ALL ON FUNCTION public.gridex_store_billing_underlay(uuid,jsonb,jsonb,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.gridex_store_billing_underlay(uuid,jsonb,jsonb,uuid) TO service_role;

CREATE FUNCTION public.gridex_read_billing_underlay_source_basis_v1(p_company_id uuid,p_underlay_ids uuid[]) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE result jsonb:='[]';u public.billing_underlays%rowtype;b gridex_billing_source.underlay_bindings%rowtype;qualified boolean;
BEGIN
 IF coalesce(current_setting('role',true),'')<>'service_role' AND current_user<>'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF p_company_id IS NULL OR p_underlay_ids IS NULL OR cardinality(p_underlay_ids)>1000 OR array_position(p_underlay_ids,NULL) IS NOT NULL THEN RAISE EXCEPTION 'billing_underlay_read_scope_required'; END IF;
 FOR u IN SELECT * FROM public.billing_underlays WHERE company_id=p_company_id AND id=ANY(p_underlay_ids) ORDER BY id LOOP
  SELECT * INTO b FROM gridex_billing_source.underlay_bindings WHERE underlay_id=u.id AND company_id=p_company_id;
  qualified:=true;
  BEGIN PERFORM gridex_billing_source.require_underlay_v1(p_company_id,u.id);
  EXCEPTION WHEN check_violation THEN qualified:=false; END;
  result:=result||jsonb_build_array(jsonb_build_object('id',u.id,'qualified',qualified,'totalKwh',gridex_utilts_binding.canonical_decimal_v2(u.total_kwh::text),'sourceBasisHash',b.source_basis_hash,'correctionRequired',EXISTS(SELECT FROM gridex_billing_source.correction_journal j WHERE j.underlay_id=u.id)));
 END LOOP;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.gridex_read_billing_underlay_source_basis_v1(uuid,uuid[]) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.gridex_read_billing_underlay_source_basis_v1(uuid,uuid[]) TO service_role;
CREATE FUNCTION gridex_billing_source.require_underlay_v1(p_company uuid,p_underlay uuid) RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE u public.billing_underlays%rowtype;b gridex_billing_source.underlay_bindings%rowtype;legal_basis jsonb;
BEGIN
 SELECT * INTO u FROM public.billing_underlays WHERE id=p_underlay AND company_id=p_company;
 SELECT * INTO b FROM gridex_billing_source.underlay_bindings WHERE underlay_id=p_underlay AND company_id=p_company;
 IF u.id IS NULL OR b.underlay_id IS NULL OR b.exact_total_kwh IS DISTINCT FROM u.total_kwh OR b.source_basis_hash IS DISTINCT FROM encode(sha256(convert_to(b.source_basis::text,'UTF8')),'hex')
  OR EXISTS(SELECT FROM gridex_billing_source.correction_journal WHERE underlay_id=u.id) THEN RAISE EXCEPTION 'billing_finalized_source_basis_required' USING ERRCODE='23514'; END IF;
 legal_basis:=gridex_received_sources.billing_supply_basis_v1(p_company,u.supply_period_id,(b.source_basis->>'start')::timestamptz,(b.source_basis->>'end')::timestamptz);
 IF legal_basis IS DISTINCT FROM b.source_basis->'supply' THEN RAISE EXCEPTION 'billing_finalized_supply_basis_changed' USING ERRCODE='23514'; END IF;
END $$;
ALTER FUNCTION public.gridex_create_billing_export_run(jsonb,jsonb) RENAME TO gridex_create_billing_export_run_before_source_v2;
ALTER FUNCTION public.gridex_create_billing_export_run_before_source_v2(jsonb,jsonb) SET SCHEMA gridex_billing_source;
CREATE FUNCTION public.gridex_create_billing_export_run(p_run jsonb,p_items jsonb DEFAULT '[]') RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE item jsonb;company uuid;
BEGIN
 IF coalesce(current_setting('role',true),'')<>'service_role' AND current_user<>'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 company:=(p_run->>'company_id')::uuid;
 IF company IS NULL OR jsonb_typeof(p_items) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'billing_export_source_scope_required'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
  IF item->>'status'='ready' THEN PERFORM gridex_billing_source.require_underlay_v1(company,(item->>'billing_underlay_id')::uuid); END IF;
 END LOOP;
 RETURN gridex_billing_source.gridex_create_billing_export_run_before_source_v2(p_run,p_items);
END $$;
REVOKE ALL ON FUNCTION public.gridex_create_billing_export_run(jsonb,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.gridex_create_billing_export_run(jsonb,jsonb) TO service_role;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA gridex_billing_source FROM PUBLIC,anon,authenticated,service_role;
COMMIT;

20260930201111_ediel_normal_switch_sourc.body:
-- P11/CALL03 normal Z04 L/LK business effects derive from the whole accepted
-- physical source and sealed sent Z03. ACKs and operational DATE projections
-- cannot approve a market relationship or advance a future start.
BEGIN;
CREATE TABLE gridex_received_sources.normal_switch_confirmations(
 source_message_id uuid NOT NULL REFERENCES public.ediel_messages(id),period_id uuid PRIMARY KEY REFERENCES public.customer_supply_periods(id),
 company_id uuid NOT NULL REFERENCES public.companies(id),switch_id uuid NOT NULL UNIQUE REFERENCES public.supplier_switch_requests(id),
 original_message_id uuid NOT NULL REFERENCES public.ediel_messages(id),original_payload_hash text NOT NULL,
 contract_id uuid NOT NULL REFERENCES public.customer_contracts(id),protected_contract_hash text NOT NULL,
 source_object jsonb NOT NULL,legal_context jsonb NOT NULL,market_start_at timestamptz NOT NULL,
 confirmed_period jsonb NOT NULL,confirmed_switch jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE gridex_received_sources.normal_supply_activations(
 period_id uuid PRIMARY KEY REFERENCES gridex_received_sources.normal_switch_confirmations(period_id),
 company_id uuid NOT NULL REFERENCES public.companies(id),source_message_id uuid NOT NULL,
 actor_user_id uuid NOT NULL,previous_period jsonb NOT NULL,resulting_period jsonb NOT NULL,result jsonb NOT NULL,activated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE gridex_received_sources.normal_switch_confirmations ENABLE ROW LEVEL SECURITY;
ALTER TABLE gridex_received_sources.normal_supply_activations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON gridex_received_sources.normal_switch_confirmations,gridex_received_sources.normal_supply_activations FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER normal_confirmation_immutable BEFORE UPDATE OR DELETE ON gridex_received_sources.normal_switch_confirmations FOR EACH ROW EXECUTE FUNCTION gridex_received_sources.permission_transition_immutable_v1();
CREATE TRIGGER normal_confirmation_no_truncate BEFORE TRUNCATE ON gridex_received_sources.normal_switch_confirmations FOR EACH STATEMENT EXECUTE FUNCTION gridex_received_sources.permission_transition_immutable_v1();
CREATE TRIGGER normal_activation_immutable BEFORE UPDATE OR DELETE ON gridex_received_sources.normal_supply_activations FOR EACH ROW EXECUTE FUNCTION gridex_received_sources.permission_transition_immutable_v1();
CREATE TRIGGER normal_activation_no_truncate BEFORE TRUNCATE ON gridex_received_sources.normal_supply_activations FOR EACH STATEMENT EXECUTE FUNCTION gridex_received_sources.permission_transition_immutable_v1();

-- Operational scan cursor only. It grants no relationship or activation and
-- advances across held candidates so old held starts cannot starve new ones.
CREATE TABLE gridex_received_sources.normal_activation_sweep_cursors(scope_key text PRIMARY KEY,last_start timestamptz,last_period uuid);
ALTER TABLE gridex_received_sources.normal_activation_sweep_cursors ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON gridex_received_sources.normal_activation_sweep_cursors FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION gridex_received_sources.sent_source_is_current_v1(m public.ediel_messages) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
 IF m.direction IS DISTINCT FROM 'outbound' OR (m.status IN('sent','acknowledged')) IS NOT TRUE OR m.message_sent_at IS NULL OR m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RETURN false;END IF;
 -- The shared private provider journal supplies actual acceptance. A positive
 -- ACK projection does not approve a supply or manufacture a sent original.
 RETURN gridex_ediel_transport.accepted_source_basis_v1(m) IS NOT NULL;
END $$;
REVOKE ALL ON FUNCTION gridex_received_sources.sent_source_is_current_v1(public.ediel_messages) FROM PUBLIC,anon,authenticated,service_role;

-- Physical projection, not a rule selector. The canonical register owner
-- supplies acceptance and grouping; only its first register owns common fields.
CREATE FUNCTION gridex_received_sources.normal_switch_wire_v1(p_raw text) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE w jsonb:=gridex_received_sources.supply_wire_v1(p_raw);tokens jsonb:=gridex_received_sources.closure_wire_tokens_v2(p_raw);
 own jsonb;lin jsonb;objects jsonb:='[]';seen text[]:=ARRAY[]::text[];key text;
BEGIN
 IF w IS NULL OR tokens IS NULL THEN RETURN NULL;END IF;
 FOR own IN SELECT o FROM jsonb_array_elements(w->'objects') o LOOP
  SELECT t INTO lin FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN' AND t#>>'{elements,1,0}'=own->>'line';
  IF lin IS NULL OR lin#>>'{elements,3,0}' IS DISTINCT FROM own->>'point' THEN RETURN NULL;END IF;
  key:=jsonb_build_array(own->>'point',lin#>>'{elements,3,3}')::text;
  IF key=ANY(seen) THEN CONTINUE;END IF;
  seen:=array_append(seen,key);
  objects:=objects||jsonb_build_array(own||jsonb_build_object('identityAgency',lin#>>'{elements,3,3}',
   'registerCount',(SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN' AND t#>>'{elements,3,0}'=own->>'point' AND t#>>'{elements,3,3}'=lin#>>'{elements,3,3}')));
 END LOOP;
 RETURN w||jsonb_build_object('objects',objects);
END $$;
REVOKE ALL ON FUNCTION gridex_received_sources.normal_switch_wire_v1(text) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION gridex_received_sources.normal_switch_confirm_v1(p_company_id uuid,p_source_message_id uuid,p_actor_user_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE m public.ediel_messages%rowtype;original public.ediel_messages%rowtype;sw public.supplier_switch_requests%rowtype;
 point public.metering_points%rowtype;site public.customer_sites%rowtype;contract public.customer_contracts%rowtype;
 prior gridex_received_sources.supply_source_transitions%rowtype;canonical gridex_received_sources.validation_assessments%rowtype;
 wire jsonb;oldwire jsonb;own jsonb;basis jsonb;plans jsonb:='[]';plan jsonb;after_states jsonb;before_switches jsonb:='[]';period public.customer_supply_periods%rowtype;
 ids uuid[];original_ids uuid[];switch_ids uuid[]:=ARRAY[]::uuid[];pid uuid;event_at timestamptz;customer_identity text;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'inbound' OR m.message_standard IS DISTINCT FROM 'edifact' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z04' THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_source_required');END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
  OR public.gridex_actor_has_company_permission(p_actor_user_id,m.company_id,'metering.write') IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_execution_actor_required');END IF;
 SELECT * INTO prior FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=m.id;
 IF FOUND THEN
  IF prior.company_id IS DISTINCT FROM m.company_id OR prior.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'normal_z04_replay_conflict';END IF;
  RETURN jsonb_build_object('applied',true,'idempotent',true,'periods',prior.resulting_states,'switchIds',prior.qualified_switch_ids);
 END IF;
 basis:=gridex_ediel_inbound_context.require_v1(m.company_id,m.id);
 PERFORM gridex_ediel_source_rules.require_v1(m.company_id,m.id);
 IF basis->>'actorRole' IS DISTINCT FROM 'electricity_supplier' OR basis->>'code' IS DISTINCT FROM 'Z04' OR basis->>'family' IS DISTINCT FROM 'PRODAT' THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_frozen_legal_context_required');END IF;
 IF (SELECT count(*) FROM gridex_received_sources.validation_assessments a WHERE a.source_message_id=m.id AND a.company_id=m.company_id AND a.environment=m.environment AND a.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id))<>1 THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_canonical_leaf_ambiguous');END IF;
 SELECT * INTO canonical FROM gridex_received_sources.validation_assessments a WHERE a.source_message_id=m.id AND a.company_id=m.company_id AND a.environment=m.environment AND a.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id) FOR SHARE;
 IF canonical.facts_text::jsonb->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR canonical.facts_text::jsonb->>'applicationDecision' IS DISTINCT FROM 'accepted' OR canonical.facts_text::jsonb->>'functionalDecision' IS DISTINCT FROM 'accepted'
  OR canonical.facts_text::jsonb#>>'{registerValidation,owner}' IS DISTINCT FROM 'validateProdatRegisterPolicy' OR canonical.facts_text::jsonb#>>'{registerValidation,coverage}' IS DISTINCT FROM 'canonical_register_only'
  OR jsonb_typeof(canonical.facts_text::jsonb#>'{registerValidation,objects}') IS DISTINCT FROM 'array' THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_canonical_source_not_accepted');END IF;
 wire:=gridex_received_sources.normal_switch_wire_v1(m.raw_payload);
 IF wire IS NULL OR wire->>'receiver' IS DISTINCT FROM basis->>'legalEdielId' OR EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE (o->>'reason' IN('Z22','Z23')) IS NOT TRUE OR (o->>'identityAgency' IN('9','89')) IS NOT TRUE OR nullif(o->>'li','') IS NULL OR nullif(o->>'customerIdentity','') IS NULL OR gridex_received_sources.permission_time_v1(o->>'start') IS NULL)
  OR (SELECT count(DISTINCT o->>'point') FROM jsonb_array_elements(wire->'objects') o)<>jsonb_array_length(wire->'objects')
  OR jsonb_array_length(canonical.facts_text::jsonb#>'{registerValidation,objects}')<>jsonb_array_length(wire->'objects') THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_whole_physical_scope_required');END IF;
 -- Discover all original rows first. No switch/period is locked before its
 -- original, so confirmation, cancellation and future activation share order.
 SELECT array_agg(DISTINCT s.outbound_z03_message_id ORDER BY s.outbound_z03_message_id) INTO original_ids FROM public.supplier_switch_requests s
 WHERE s.company_id=m.company_id AND EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE s.rff_li_reference=o->>'li');
 PERFORM z.id FROM public.ediel_messages z WHERE z.company_id=m.company_id AND z.id=ANY(original_ids) ORDER BY z.id FOR SHARE;
 FOR own IN SELECT o FROM jsonb_array_elements(wire->'objects') o ORDER BY o->>'point' LOOP
  IF NOT EXISTS(SELECT FROM jsonb_array_elements(canonical.facts_text::jsonb#>'{registerValidation,objects}') o WHERE o->>'disposition'='accepted' AND o->>'messageIndex'='0' AND o->>'objectId'=own->>'point' AND o->>'identityAgency'=own->>'identityAgency' AND jsonb_array_length(o->'registers')=(own->>'registerCount')::integer) THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_register_owner_scope_required');END IF;
  SELECT array_agg(s.id ORDER BY s.id) INTO ids FROM public.supplier_switch_requests s JOIN public.ediel_messages z ON z.id=s.outbound_z03_message_id AND z.company_id=s.company_id AND z.environment=m.environment
   WHERE s.company_id=m.company_id AND s.rff_li_reference=own->>'li' AND z.direction='outbound' AND z.message_family='PRODAT' AND z.message_code='Z03' AND gridex_received_sources.sent_source_is_current_v1(z)
    AND gridex_received_sources.normal_switch_wire_v1(z.raw_payload)->>'sender'=wire->>'receiver' AND gridex_received_sources.normal_switch_wire_v1(z.raw_payload)->>'receiver'=wire->>'sender'
    AND EXISTS(SELECT FROM jsonb_array_elements(gridex_received_sources.normal_switch_wire_v1(z.raw_payload)->'objects') o WHERE o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason'=own->>'reason' AND (o->>'point' IS NULL OR o->>'point'=own->>'point'));
  IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_exact_sent_original_required');END IF;
  SELECT * INTO sw FROM public.supplier_switch_requests WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
  SELECT * INTO original FROM public.ediel_messages WHERE id=sw.outbound_z03_message_id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
  oldwire:=gridex_received_sources.normal_switch_wire_v1(original.raw_payload);
  IF original.direction IS DISTINCT FROM 'outbound' OR original.message_family IS DISTINCT FROM 'PRODAT' OR original.message_code IS DISTINCT FROM 'Z03' OR gridex_received_sources.sent_source_is_current_v1(original) IS NOT TRUE
   OR original.customer_id IS DISTINCT FROM sw.customer_id OR original.metering_point_id IS DISTINCT FROM sw.metering_point_id OR oldwire->>'sender' IS DISTINCT FROM wire->>'receiver' OR oldwire->>'receiver' IS DISTINCT FROM wire->>'sender'
   OR NOT EXISTS(SELECT FROM jsonb_array_elements(oldwire->'objects') o WHERE o->>'li'=own->>'li' AND o->>'customerIdentity'=own->>'customerIdentity' AND o->>'start'=own->>'start' AND o->>'reason'=own->>'reason' AND (o->>'point' IS NULL OR o->>'point'=own->>'point'))
   OR (sw.status IN('prepared','queued','submitted','sent','waiting','waiting_response','waiting_for_z04','awaiting_confirmation')) IS NOT TRUE OR sw.lifecycle_blocked
   OR sw.id=ANY(switch_ids) OR (m.customer_id IS NOT NULL AND m.customer_id IS DISTINCT FROM sw.customer_id) OR (m.metering_point_id IS NOT NULL AND m.metering_point_id IS DISTINCT FROM sw.metering_point_id) THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_locked_original_scope_required');END IF;
  SELECT * INTO point FROM public.metering_points WHERE id=sw.metering_point_id AND company_id=m.company_id FOR UPDATE;
  SELECT * INTO site FROM public.customer_sites WHERE id=coalesce(sw.site_id,sw.customer_site_id) AND company_id=m.company_id FOR SHARE;
  SELECT * INTO contract FROM public.customer_contracts WHERE id=coalesce(sw.contract_id,sw.customer_contract_id) AND company_id=m.company_id FOR SHARE;
  PERFORM c.id FROM public.customers c WHERE c.id=sw.customer_id AND c.company_id=m.company_id FOR SHARE;
  SELECT coalesce(nullif(btrim(c.org_number),''),nullif(btrim(c.personal_number),'')) INTO customer_identity FROM public.customers c WHERE c.id=sw.customer_id AND c.company_id=m.company_id;
  IF point.id IS NULL OR site.id IS NULL OR contract.id IS NULL OR point.ediel_metering_point_id IS DISTINCT FROM own->>'point' OR point.customer_id IS DISTINCT FROM sw.customer_id OR point.site_id IS DISTINCT FROM site.id OR site.customer_id IS DISTINCT FROM sw.customer_id OR own->>'customerIdentity' IS DISTINCT FROM customer_identity
   OR (sw.site_id IS NOT NULL AND sw.site_id IS DISTINCT FROM site.id) OR (sw.customer_site_id IS NOT NULL AND sw.customer_site_id IS DISTINCT FROM site.id) OR (sw.contract_id IS NOT NULL AND sw.contract_id IS DISTINCT FROM contract.id) OR (sw.customer_contract_id IS NOT NULL AND sw.customer_contract_id IS DISTINCT FROM contract.id)
   OR point.grid_owner_ediel_id IS DISTINCT FROM wire->>'sender' OR point.grid_area_code IS DISTINCT FROM own->>'gridArea' OR contract.customer_id IS DISTINCT FROM sw.customer_id OR contract.metering_point_id IS DISTINCT FROM point.id
   OR (contract.status IN('signed','active')) IS NOT TRUE OR contract.signed_at IS NULL OR nullif(contract.signed_version,'') IS NULL OR nullif(contract.contract_version,'') IS NULL THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_owned_signed_contract_scope_required');END IF;
  event_at:=gridex_received_sources.permission_time_v1(own->>'start');
  IF EXISTS(SELECT FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.metering_point_id=point.id AND p.status NOT IN('cancelled','ended') AND (p.market_end_at IS NULL OR p.market_end_at>event_at)) THEN RETURN jsonb_build_object('applied',false,'reason','normal_z04_conflicting_supply_period');END IF;
  pid:=gen_random_uuid();switch_ids:=array_append(switch_ids,sw.id);before_switches:=before_switches||jsonb_build_array(to_jsonb(sw));
  plans:=plans||jsonb_build_array(jsonb_build_object('periodId',pid,'switchId',sw.id,'pointId',point.id,'siteId',site.id,'customerId',sw.customer_id,'contractId',contract.id,'contractHash',gridex_received_sources.production_contract_hash_v1(contract),'originalId',original.id,'originalHash',original.immutable_payload_hash,'eventAt',event_at,'object',own));
 END LOOP;
 -- Every required source, original and owned relationship is qualified before
 -- the first market write; any downstream effect failure rolls back all scopes.
 FOR plan IN SELECT p FROM jsonb_array_elements(plans) p LOOP
  UPDATE public.supplier_switch_requests SET status='accepted',site_id=(plan->>'siteId')::uuid,inbound_z04_message_id=m.id,confirmed_start_date=gridex_received_sources.permission_date_v1(plan#>>'{object,start}'),updated_at=now(),updated_by=p_actor_user_id WHERE id=(plan->>'switchId')::uuid AND company_id=m.company_id;
  INSERT INTO public.customer_supply_periods(id,company_id,customer_id,metering_point_id,contract_id,customer_contract_id,start_date,market_start_at,source,source_process,source_message_id,source_switch_request_id,status,market_state_version,metadata)
   VALUES((plan->>'periodId')::uuid,m.company_id,(plan->>'customerId')::uuid,(plan->>'pointId')::uuid,(plan->>'contractId')::uuid,(plan->>'contractId')::uuid,gridex_received_sources.permission_date_v1(plan#>>'{object,start}'),(plan->>'eventAt')::timestamptz,'ediel_qualified_source','supplier_switch_confirmation',m.id,(plan->>'switchId')::uuid,'confirmed_by_grid_owner',1,jsonb_build_object('normalSourceBasis',jsonb_build_object('sourceMessageId',m.id,'originalMessageId',plan->>'originalId','siteId',plan->>'siteId','contractHash',plan->>'contractHash','object',plan->'object','legalActorId',basis->>'legalActorId')));
  SELECT * INTO period FROM public.customer_supply_periods WHERE id=(plan->>'periodId')::uuid;
  SELECT * INTO sw FROM public.supplier_switch_requests WHERE id=(plan->>'switchId')::uuid;
  INSERT INTO gridex_received_sources.normal_switch_confirmations(source_message_id,period_id,company_id,switch_id,original_message_id,original_payload_hash,contract_id,protected_contract_hash,source_object,legal_context,market_start_at,confirmed_period,confirmed_switch)
   VALUES(m.id,period.id,m.company_id,sw.id,(plan->>'originalId')::uuid,plan->>'originalHash',(plan->>'contractId')::uuid,plan->>'contractHash',plan->'object',basis,period.market_start_at,to_jsonb(period),to_jsonb(sw));
 END LOOP;
 SELECT jsonb_agg(to_jsonb(p) ORDER BY p.id) INTO after_states FROM public.customer_supply_periods p WHERE p.company_id=m.company_id AND p.id IN(SELECT (chosen->>'periodId')::uuid FROM jsonb_array_elements(plans) chosen);
 INSERT INTO gridex_received_sources.supply_source_transitions(source_message_id,company_id,payload_hash,source_code,source_objects,previous_states,resulting_states,qualified_switch_ids,actor_user_id) VALUES(m.id,m.company_id,encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),'Z04',wire->'objects','[]',after_states,switch_ids,p_actor_user_id);
 RETURN jsonb_build_object('applied',true,'idempotent',false,'periods',after_states,'switchIds',switch_ids,'commits',(SELECT jsonb_agg(jsonb_build_object('switchRequestId',switch_id,'supplyPeriodId',period_id,'customerId',confirmed_period->>'customer_id','meteringPointId',confirmed_period->>'metering_point_id','siteId',coalesce(confirmed_switch->>'site_id',confirmed_switch->>'customer_site_id'))) FROM gridex_received_sources.normal_switch_confirmations WHERE source_message_id=m.id AND company_id=m.company_id));
END $$;
REVOKE ALL ON FUNCTION gridex_received_sources.normal_switch_confirm_v1(uuid,uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;

-- Preserve existing A/D/C/Z05 authority; direct/native/manual callers share
-- this same physical-source dispatch and cannot opt into the legacy mutation.
ALTER FUNCTION public.ediel_apply_supply_source_v1(uuid,uuid,uuid) SET SCHEMA gridex_received_sources;
ALTER FUNCTION gridex_received_sources.ediel_apply_supply_source_v1(uuid,uuid,uuid) RENAME TO apply_supply_before_normal_switch_v1;
REVOKE ALL ON FUNCTION gridex_received_sources.apply_supply_before_normal_switch_v1(uuid,uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.ediel_apply_supply_source_v1(p_company_id uuid,p_source_message_id uuid,p_actor_user_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE m public.ediel_messages%rowtype;w jsonb;ids uuid[];
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE;
 w:=gridex_received_sources.normal_switch_wire_v1(m.raw_payload);
 IF m.direction='inbound' AND m.message_family='PRODAT' AND w->>'code'='Z04' THEN
  -- A normal replay returns its immutable receipt before original locks.
  -- Original-before-switch order protects the preserved cancellation path.
  IF EXISTS(SELECT FROM jsonb_array_elements(w->'objects') o WHERE o->>'reason' IN('Z22','Z23')) THEN RETURN gridex_received_sources.normal_switch_confirm_v1(p_company_id,p_source_message_id,p_actor_user_id);END IF;
  SELECT array_agg(DISTINCT s.outbound_z03_message_id ORDER BY s.outbound_z03_message_id) INTO ids FROM public.supplier_switch_requests s WHERE s.company_id=p_company_id AND EXISTS(SELECT FROM jsonb_array_elements(w->'objects') o WHERE o->>'li'=s.rff_li_reference);
  PERFORM z.id FROM public.ediel_messages z WHERE z.company_id=p_company_id AND z.id=ANY(ids) ORDER BY z.id FOR SHARE;
 END IF;
 RETURN gridex_received_sources.apply_supply_before_normal_switch_v1(p_company_id,p_source_message_id,p_actor_user_id);
END $$;
REVOKE ALL ON FUNCTION public.ediel_apply_supply_source_v1(uuid,uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ediel_apply_supply_source_v1(uuid,uuid,uuid) TO service_role;

-- Existing activation effects (workflow, notification job and billing) remain
-- one transaction, but only a due immutable exact confirmation may call them.
ALTER FUNCTION public.activate_customer_supply_v1(uuid,uuid,uuid,date,uuid,text) SET SCHEMA gridex_received_sources;
ALTER FUNCTION gridex_received_sources.activate_customer_supply_v1(uuid,uuid,uuid,date,uuid,text) RENAME TO activate_supply_before_source_guard_v1;
REVOKE ALL ON FUNCTION gridex_received_sources.activate_supply_before_source_guard_v1(uuid,uuid,uuid,date,uuid,text) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.activate_customer_supply_v1(p_company_id uuid,p_supplier_switch_request_id uuid,p_source_message_id uuid,p_actual_start_date date DEFAULT NULL,p_actor_user_id uuid DEFAULT NULL,p_idempotency_key text DEFAULT NULL)
RETURNS TABLE(supplier_switch_request_id uuid,supply_period_id uuid,contract_id uuid,customer_application_id uuid,workflow_id uuid,domain_event_id uuid,notification_job_id uuid)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE proof gridex_received_sources.normal_switch_confirmations%rowtype;prior gridex_received_sources.normal_supply_activations%rowtype;
 p public.customer_supply_periods%rowtype;s public.supplier_switch_requests%rowtype;m public.ediel_messages%rowtype;origin public.ediel_messages%rowtype;c public.customer_contracts%rowtype;result jsonb;
BEGIN
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active') OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL) OR public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'metering.write') IS NOT TRUE THEN RAISE EXCEPTION 'normal_supply_activation_actor_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO proof FROM gridex_received_sources.normal_switch_confirmations WHERE company_id=p_company_id AND switch_id=p_supplier_switch_request_id AND source_message_id=p_source_message_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'normal_supply_activation_immutable_confirmation_required';END IF;
 PERFORM z.id FROM public.ediel_messages z WHERE z.company_id=p_company_id AND z.id=ANY(ARRAY[proof.source_message_id,proof.original_message_id]) ORDER BY z.id FOR UPDATE;
 SELECT * INTO m FROM public.ediel_messages WHERE id=proof.source_message_id AND company_id=p_company_id;
 IF NOT EXISTS(SELECT FROM gridex_received_sources.supply_source_transitions tr WHERE tr.source_message_id=m.id AND tr.company_id=p_company_id AND tr.payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND proof.switch_id=ANY(tr.qualified_switch_ids)) THEN RAISE EXCEPTION 'normal_supply_activation_source_changed';END IF;
 SELECT * INTO prior FROM gridex_received_sources.normal_supply_activations WHERE period_id=proof.period_id;
 IF FOUND THEN
  -- Established own activation is returned before today's profile, contract,
  -- deadline or rule decisions. It cannot authorize a second market effect.
  RETURN QUERY SELECT (prior.result->>'supplier_switch_request_id')::uuid,(prior.result->>'supply_period_id')::uuid,(prior.result->>'contract_id')::uuid,(prior.result->>'customer_application_id')::uuid,(prior.result->>'workflow_id')::uuid,(prior.result->>'domain_event_id')::uuid,(prior.result->>'notification_job_id')::uuid;RETURN;
 END IF;
 PERFORM gridex_ediel_inbound_context.require_v1(p_company_id,m.id);
 PERFORM gridex_ediel_source_rules.require_v1(p_company_id,m.id);
 IF proof.market_start_at>now() THEN RAISE EXCEPTION 'normal_supply_activation_not_due';END IF;
 SELECT * INTO origin FROM public.ediel_messages WHERE id=proof.original_message_id AND company_id=p_company_id AND environment=m.environment;
 SELECT * INTO s FROM public.supplier_switch_requests WHERE id=proof.switch_id AND company_id=p_company_id FOR UPDATE;
 SELECT * INTO p FROM public.customer_supply_periods WHERE id=proof.period_id AND company_id=p_company_id FOR UPDATE;
 SELECT * INTO c FROM public.customer_contracts WHERE id=proof.contract_id AND company_id=p_company_id FOR SHARE;
 PERFORM profile.id FROM public.tenant_ediel_profiles profile WHERE profile.company_id=p_company_id AND profile.environment=m.environment ORDER BY profile.id FOR SHARE;
 PERFORM role.id FROM public.tenant_actor_roles role WHERE role.company_id=p_company_id AND role.environment=m.environment ORDER BY role.id FOR SHARE;
 PERFORM identifier.id FROM public.tenant_actor_identifiers identifier WHERE identifier.company_id=p_company_id AND identifier.environment=m.environment ORDER BY identifier.id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.tenant_ediel_profiles profile WHERE profile.company_id=p_company_id AND profile.environment=m.environment AND profile.market='electricity' AND profile.is_enabled AND profile.valid_from<=now() AND (profile.valid_to IS NULL OR now()<profile.valid_to))
  OR NOT EXISTS(SELECT FROM public.tenant_actor_roles role WHERE role.company_id=p_company_id AND role.environment=m.environment AND role.actor_id::text=proof.legal_context->>'legalActorId' AND role.role_code='electricity_supplier' AND role.valid_from<=now() AND (role.valid_to IS NULL OR now()<role.valid_to))
  OR (SELECT count(DISTINCT (identifier.actor_id,identifier.identifier_value)) FROM public.tenant_actor_identifiers identifier WHERE identifier.company_id=p_company_id AND identifier.environment=m.environment AND identifier.identifier_type='EdielId' AND identifier.valid_from<=now() AND (identifier.valid_to IS NULL OR now()<identifier.valid_to))<>1
  OR NOT EXISTS(SELECT FROM public.tenant_actor_identifiers identifier WHERE identifier.company_id=p_company_id AND identifier.environment=m.environment AND identifier.actor_id::text=proof.legal_context->>'legalActorId' AND identifier.identifier_type='EdielId' AND identifier.identifier_value=proof.legal_context->>'legalEdielId' AND identifier.valid_from<=now() AND (identifier.valid_to IS NULL OR now()<identifier.valid_to)) THEN RAISE EXCEPTION 'normal_supply_activation_current_legal_actor_required';END IF;
 IF origin.direction IS DISTINCT FROM 'outbound' OR gridex_received_sources.sent_source_is_current_v1(origin) IS NOT TRUE OR origin.immutable_rendered_at IS NULL OR origin.immutable_payload_hash IS DISTINCT FROM proof.original_payload_hash OR origin.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(origin.raw_payload,'UTF8')),'hex')
  OR p.status IS DISTINCT FROM 'confirmed_by_grid_owner' OR p.market_state_version IS DISTINCT FROM (proof.confirmed_period->>'market_state_version')::bigint OR p.market_start_at IS DISTINCT FROM proof.market_start_at
  OR p.source_message_id IS DISTINCT FROM proof.source_message_id OR p.source_switch_request_id IS DISTINCT FROM proof.switch_id OR p.customer_id IS DISTINCT FROM (proof.confirmed_period->>'customer_id')::uuid OR p.metering_point_id IS DISTINCT FROM (proof.confirmed_period->>'metering_point_id')::uuid OR p.market_end_at IS NOT NULL OR p.metadata IS DISTINCT FROM proof.confirmed_period->'metadata'
  OR s.status IS DISTINCT FROM 'accepted' OR s.inbound_z04_message_id IS DISTINCT FROM proof.source_message_id OR s.outbound_z03_message_id IS DISTINCT FROM proof.original_message_id OR s.lifecycle_blocked OR s.customer_id IS DISTINCT FROM p.customer_id OR s.metering_point_id IS DISTINCT FROM p.metering_point_id
  OR s.contract_id IS DISTINCT FROM (proof.confirmed_switch->>'contract_id')::uuid OR s.customer_contract_id IS DISTINCT FROM (proof.confirmed_switch->>'customer_contract_id')::uuid OR s.site_id IS DISTINCT FROM (proof.confirmed_switch->>'site_id')::uuid OR s.customer_site_id IS DISTINCT FROM (proof.confirmed_switch->>'customer_site_id')::uuid
  OR p.contract_id IS DISTINCT FROM (proof.confirmed_period->>'contract_id')::uuid OR p.customer_contract_id IS DISTINCT FROM (proof.confirmed_period->>'customer_contract_id')::uuid
  OR c.id IS NULL OR c.customer_id IS DISTINCT FROM p.customer_id OR c.metering_point_id IS DISTINCT FROM p.metering_point_id OR (c.status IN('signed','active')) IS NOT TRUE OR gridex_received_sources.production_contract_hash_v1(c) IS DISTINCT FROM proof.protected_contract_hash
  OR (p_actual_start_date IS NOT NULL AND p_actual_start_date IS DISTINCT FROM p.start_date) THEN RAISE EXCEPTION 'normal_supply_activation_current_confirmation_changed';END IF;
 SELECT to_jsonb(effect) INTO result FROM gridex_received_sources.activate_supply_before_source_guard_v1(p_company_id,proof.switch_id,proof.source_message_id,p.start_date,p_actor_user_id,'ediel-normal-activation:'||proof.period_id) effect;
 IF result->>'supply_period_id' IS DISTINCT FROM proof.period_id::text THEN RAISE EXCEPTION 'normal_supply_activation_period_replaced';END IF;
 INSERT INTO gridex_received_sources.normal_supply_activations(period_id,company_id,source_message_id,actor_user_id,previous_period,resulting_period,result)
 SELECT proof.period_id,p_company_id,proof.source_message_id,p_actor_user_id,to_jsonb(p),to_jsonb(current),result FROM public.customer_supply_periods current WHERE current.id=proof.period_id AND current.company_id=p_company_id;
 RETURN QUERY SELECT (result->>'supplier_switch_request_id')::uuid,(result->>'supply_period_id')::uuid,(result->>'contract_id')::uuid,(result->>'customer_application_id')::uuid,(result->>'workflow_id')::uuid,(result->>'domain_event_id')::uuid,(result->>'notification_job_id')::uuid;
END $$;
REVOKE ALL ON FUNCTION public.activate_customer_supply_v1(uuid,uuid,uuid,date,uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.activate_customer_supply_v1(uuid,uuid,uuid,date,uuid,text) TO service_role;

ALTER FUNCTION public.ediel_advance_supply_deadlines_v1(uuid,uuid,integer) SET SCHEMA gridex_received_sources;
ALTER FUNCTION gridex_received_sources.ediel_advance_supply_deadlines_v1(uuid,uuid,integer) RENAME TO advance_supply_before_normal_switch_v1;
REVOKE ALL ON FUNCTION gridex_received_sources.advance_supply_before_normal_switch_v1(uuid,uuid,integer) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.ediel_advance_supply_deadlines_v1(p_company_id uuid,p_actor_user_id uuid,p_limit integer DEFAULT 100) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE own record;result jsonb;activated integer:=0;cursor_row gridex_received_sources.normal_activation_sweep_cursors%rowtype;scope text:=coalesce(p_company_id::text,'all');
BEGIN
 result:=gridex_received_sources.advance_supply_before_normal_switch_v1(p_company_id,p_actor_user_id,p_limit);
 INSERT INTO gridex_received_sources.normal_activation_sweep_cursors(scope_key) VALUES(scope) ON CONFLICT DO NOTHING;
 SELECT * INTO cursor_row FROM gridex_received_sources.normal_activation_sweep_cursors WHERE scope_key=scope FOR UPDATE;
 IF NOT EXISTS(SELECT FROM gridex_received_sources.normal_switch_confirmations c JOIN public.customer_supply_periods p ON p.id=c.period_id AND p.company_id=c.company_id WHERE (p_company_id IS NULL OR c.company_id=p_company_id) AND p.status='confirmed_by_grid_owner' AND c.market_start_at<=now() AND NOT EXISTS(SELECT FROM gridex_received_sources.normal_supply_activations a WHERE a.period_id=c.period_id) AND (cursor_row.last_start IS NULL OR (c.market_start_at,c.period_id)>(cursor_row.last_start,cursor_row.last_period))) THEN cursor_row.last_start:=NULL;cursor_row.last_period:=NULL;END IF;
 FOR own IN SELECT c.* FROM gridex_received_sources.normal_switch_confirmations c JOIN public.customer_supply_periods p ON p.id=c.period_id AND p.company_id=c.company_id
  WHERE (p_company_id IS NULL OR c.company_id=p_company_id) AND p.status='confirmed_by_grid_owner' AND c.market_start_at<=now() AND NOT EXISTS(SELECT FROM gridex_received_sources.normal_supply_activations a WHERE a.period_id=c.period_id)
   AND (cursor_row.last_start IS NULL OR (c.market_start_at,c.period_id)>(cursor_row.last_start,cursor_row.last_period))
  ORDER BY c.market_start_at,c.period_id LIMIT least(greatest(coalesce(p_limit,100),1),200) LOOP
  BEGIN
   PERFORM public.activate_customer_supply_v1(own.company_id,own.switch_id,own.source_message_id,NULL,p_actor_user_id,NULL);activated:=activated+1;
  EXCEPTION WHEN SQLSTATE '42501' OR raise_exception THEN
   -- A revoked/cancelled/changed scope stays held; the sweep cannot fabricate
   -- a new source decision or stop unrelated own candidates.
   NULL;
  END;
  UPDATE gridex_received_sources.normal_activation_sweep_cursors SET last_start=own.market_start_at,last_period=own.period_id WHERE scope_key=scope;
 END LOOP;
 RETURN jsonb_build_object('updated',coalesce((result->>'updated')::integer,0)+activated,'normalActivated',activated);
END $$;
REVOKE ALL ON FUNCTION public.ediel_advance_supply_deadlines_v1(uuid,uuid,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ediel_advance_supply_deadlines_v1(uuid,uuid,integer) TO service_role;

-- Shared exact current relation proof for structural history and later BRP
-- events. It grants no wire capability or invoice permission by itself.
ALTER FUNCTION gridex_received_sources.billing_supply_basis_v1(uuid,uuid,timestamptz,timestamptz) RENAME TO billing_supply_before_normal_switch_v1;
CREATE FUNCTION gridex_received_sources.supply_period_source_basis_v1(p_company_id uuid,p_period_id uuid,p_start timestamptz,p_end timestamptz) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE p public.customer_supply_periods%rowtype;proof gridex_received_sources.normal_switch_confirmations%rowtype;
 tr gridex_received_sources.supply_source_transitions%rowtype;activation gridex_received_sources.normal_supply_activations%rowtype;
 m public.ediel_messages%rowtype;origin public.ediel_messages%rowtype;initial_message public.ediel_messages%rowtype;c public.customer_contracts%rowtype;s public.supplier_switch_requests%rowtype;
 expected jsonb;baseline jsonb;legal jsonb;initial_owned jsonb;source_objects jsonb;ids uuid[];version bigint;source_id uuid;
BEGIN
 IF p_company_id IS NULL OR p_period_id IS NULL OR p_start IS NULL OR p_end IS NULL OR NOT isfinite(p_start) OR NOT isfinite(p_end) OR p_end<=p_start THEN RETURN NULL;END IF;
 SELECT * INTO p FROM public.customer_supply_periods WHERE id=p_period_id AND company_id=p_company_id;
 IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT * INTO proof FROM gridex_received_sources.normal_switch_confirmations WHERE period_id=p.id AND company_id=p_company_id;
 IF NOT FOUND THEN
  baseline:=gridex_received_sources.billing_supply_before_normal_switch_v1(p_company_id,p_period_id,p_start,p_end);
  IF baseline IS NULL THEN RETURN NULL;END IF;
  SELECT * INTO p FROM public.customer_supply_periods WHERE id=p_period_id AND company_id=p_company_id;
  IF p.market_state_version IS DISTINCT FROM (baseline->>'marketStateVersion')::bigint THEN RETURN NULL;END IF;
  SELECT own#>'{metadata,sourceObject}' INTO initial_owned FROM gridex_received_sources.supply_source_transitions initial,jsonb_array_elements(initial.resulting_states) own WHERE initial.source_message_id=p.source_message_id AND initial.company_id=p_company_id AND own->>'id'=p.id::text;
  SELECT * INTO origin FROM public.ediel_messages WHERE id=p.source_message_id AND company_id=p_company_id;
  SELECT jsonb_agg(own) INTO source_objects FROM jsonb_array_elements(gridex_received_sources.normal_switch_wire_v1(origin.raw_payload)->'objects') own WHERE own->>'point'=initial_owned->>'point' AND own->>'li'=initial_owned->>'li' AND own->>'start'=initial_owned->>'start';
  IF jsonb_array_length(source_objects) IS DISTINCT FROM 1 OR (source_objects#>>'{0,identityAgency}' IN('9','89')) IS NOT TRUE THEN RETURN NULL;END IF;
  RETURN baseline||jsonb_build_object('initialSourceMessageId',p.source_message_id,'legalActorId',(SELECT g.legal_actor_id FROM gridex_received_sources.regulated_supply_ground_versions g WHERE g.id::text=baseline->>'groundId' AND g.company_id=p_company_id),'sourceObjects',source_objects,'dsoEdielId',gridex_received_sources.normal_switch_wire_v1(origin.raw_payload)->>'sender');
 END IF;
 version:=p.market_state_version;source_id:=p.source_message_id;
 SELECT array_agg(t.source_message_id) INTO ids FROM gridex_received_sources.supply_source_transitions t WHERE t.company_id=p_company_id AND EXISTS(SELECT FROM jsonb_array_elements(t.resulting_states) own WHERE own->>'id'=p.id::text AND (own->>'market_state_version')::bigint=version);
 IF coalesce(cardinality(ids),0)<>1 THEN RETURN NULL;END IF;
 PERFORM z.id FROM public.ediel_messages z WHERE z.company_id=p_company_id AND z.id=ANY(ARRAY[ids[1],source_id,proof.original_message_id]) ORDER BY z.id FOR UPDATE;
 legal:=gridex_ediel_inbound_context.require_v1(p_company_id,proof.source_message_id);
 SELECT * INTO initial_message FROM public.ediel_messages WHERE id=proof.source_message_id AND company_id=p_company_id;
 SELECT * INTO s FROM public.supplier_switch_requests WHERE id=proof.switch_id AND company_id=p_company_id FOR SHARE;
 SELECT * INTO p FROM public.customer_supply_periods WHERE id=p_period_id AND company_id=p_company_id FOR SHARE;
 IF p.market_state_version IS DISTINCT FROM version OR p.source_message_id IS DISTINCT FROM source_id OR p.source_message_id IS DISTINCT FROM proof.source_message_id OR p.source_switch_request_id IS DISTINCT FROM proof.switch_id
  OR p.customer_id IS DISTINCT FROM (proof.confirmed_period->>'customer_id')::uuid OR p.metering_point_id IS DISTINCT FROM (proof.confirmed_period->>'metering_point_id')::uuid
  OR p.market_start_at IS DISTINCT FROM proof.market_start_at OR p.market_start_at>p_start OR (p.market_end_at IS NOT NULL AND p_end>p.market_end_at)
  OR (p.status IN('confirmed_by_grid_owner','active','ending','ended')) IS NOT TRUE OR s.inbound_z04_message_id IS DISTINCT FROM proof.source_message_id OR s.outbound_z03_message_id IS DISTINCT FROM proof.original_message_id
  OR s.customer_id IS DISTINCT FROM p.customer_id OR s.metering_point_id IS DISTINCT FROM p.metering_point_id OR s.lifecycle_blocked THEN RETURN NULL;END IF;
 SELECT * INTO tr FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=ids[1] AND company_id=p_company_id;
 SELECT * INTO m FROM public.ediel_messages WHERE id=tr.source_message_id AND company_id=p_company_id;
 SELECT own INTO expected FROM jsonb_array_elements(tr.resulting_states) own WHERE own->>'id'=p.id::text;
 SELECT * INTO activation FROM gridex_received_sources.normal_supply_activations WHERE period_id=p.id AND company_id=p_company_id;
 baseline:=CASE WHEN activation.period_id IS NOT NULL AND tr.source_message_id=proof.source_message_id THEN activation.resulting_period ELSE expected END;
 IF expected IS NULL OR baseline IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR tr.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  OR (to_jsonb(p)-ARRAY['updated_at','status']) IS DISTINCT FROM (baseline-ARRAY['updated_at','status'])
  OR (p.status IS DISTINCT FROM baseline->>'status' AND NOT(p.status='ended' AND baseline->>'status'='ending' AND p.market_end_at<=now()))
  OR (s.status IS DISTINCT FROM proof.confirmed_switch->>'status' AND NOT(s.status='completed' AND activation.period_id IS NOT NULL)) THEN RETURN NULL;END IF;
 SELECT * INTO origin FROM public.ediel_messages WHERE id=proof.original_message_id AND company_id=p_company_id AND environment=m.environment;
 SELECT * INTO c FROM public.customer_contracts WHERE id=proof.contract_id AND company_id=p_company_id FOR SHARE;
 IF origin.direction IS DISTINCT FROM 'outbound' OR gridex_received_sources.sent_source_is_current_v1(origin) IS NOT TRUE OR origin.immutable_payload_hash IS DISTINCT FROM proof.original_payload_hash OR origin.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(origin.raw_payload,'UTF8')),'hex')
  OR c.id IS NULL OR c.customer_id IS DISTINCT FROM p.customer_id OR c.metering_point_id IS DISTINCT FROM p.metering_point_id OR (c.status IN('signed','active')) IS NOT TRUE OR gridex_received_sources.production_contract_hash_v1(c) IS DISTINCT FROM proof.protected_contract_hash
  OR legal->>'legalActorId' IS DISTINCT FROM proof.legal_context->>'legalActorId' OR legal->>'actorRole' IS DISTINCT FROM 'electricity_supplier'
  OR NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments v WHERE v.source_message_id=m.id AND v.company_id=p_company_id AND v.environment=m.environment AND v.source_payload_hash=tr.payload_hash AND v.facts_text::jsonb->>'syntaxDecision'='accepted' AND v.facts_text::jsonb->>'applicationDecision'='accepted' AND v.facts_text::jsonb->>'functionalDecision'='accepted' AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)) THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('qualified',true,'periodId',p.id,'companyId',p.company_id,'customerId',p.customer_id,'meteringPointId',p.metering_point_id,'siteId',coalesce(proof.confirmed_switch->>'site_id',proof.confirmed_switch->>'customer_site_id'),'switchId',proof.switch_id,
  'sourceMessageId',m.id,'initialSourceMessageId',proof.source_message_id,'currentSourceMessageId',m.id,'payloadHash',tr.payload_hash,'marketStateVersion',p.market_state_version,'marketStartAt',p.market_start_at,'marketEndAt',p.market_end_at,
  'legalActorId',proof.legal_context->>'legalActorId','sourceObjects',jsonb_build_array(proof.source_object),'activated',activation.period_id IS NOT NULL);
END $$;
REVOKE ALL ON FUNCTION gridex_received_sources.supply_period_source_basis_v1(uuid,uuid,timestamptz,timestamptz) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION gridex_received_sources.billing_supply_basis_v1(p_company_id uuid,p_period_id uuid,p_start timestamptz,p_end timestamptz) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE b jsonb;
BEGIN
 IF NOT EXISTS(SELECT FROM gridex_received_sources.normal_switch_confirmations WHERE period_id=p_period_id AND company_id=p_company_id) THEN RETURN gridex_received_sources.billing_supply_before_normal_switch_v1(p_company_id,p_period_id,p_start,p_end);END IF;
 b:=gridex_received_sources.supply_period_source_basis_v1(p_company_id,p_period_id,p_start,p_end);
 IF b->>'activated' IS DISTINCT FROM 'true' THEN RETURN NULL;END IF;
 RETURN b;
END $$;
REVOKE ALL ON FUNCTION gridex_received_sources.billing_supply_basis_v1(uuid,uuid,timestamptz,timestamptz) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION gridex_received_sources.normal_switch_coverage_is_current_v1(p_company_id uuid,p_period_id uuid,p_switch_id uuid,p_source_id uuid,p_start timestamptz,p_end timestamptz) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE b jsonb;finish timestamptz:=coalesce(p_end,p_start+interval '1 minute');
BEGIN
 b:=gridex_received_sources.supply_period_source_basis_v1(p_company_id,p_period_id,p_start,finish);
 RETURN (b->>'qualified'='true' AND b->>'switchId'=p_switch_id::text AND b->>'initialSourceMessageId'=p_source_id::text AND (b->>'marketStartAt')::timestamptz=p_start AND (b->>'marketEndAt')::timestamptz IS NOT DISTINCT FROM p_end) IS TRUE;
END $$;
REVOKE ALL ON FUNCTION gridex_received_sources.normal_switch_coverage_is_current_v1(uuid,uuid,uuid,uuid,timestamptz,timestamptz) FROM PUBLIC,anon,authenticated,service_role;

-- The primary received-source owner still owns the party/evidence contract.
-- Its older DATE precision flag is retained for old receipts; new exact minute
-- output additionally requires the immutable actual native confirmation.
ALTER FUNCTION gridex_received_sources.object_owner_proof_consistent(jsonb,jsonb,timestamptz) RENAME TO object_owner_before_normal_minute_v1;
CREATE FUNCTION gridex_received_sources.object_owner_proof_consistent(p_party jsonb,p_business jsonb,p_received timestamptz) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE proof gridex_received_sources.normal_switch_confirmations%rowtype;legacy_shape jsonb;
BEGIN
 IF p_business#>>'{effectiveFrom,committedDatePrecision}' IS DISTINCT FROM 'market_minute' THEN RETURN gridex_received_sources.object_owner_before_normal_minute_v1(p_party,p_business,p_received);END IF;
 SELECT * INTO proof FROM gridex_received_sources.normal_switch_confirmations WHERE period_id=(p_business->>'supplyPeriodId')::uuid AND company_id=(p_business->>'companyId')::uuid AND source_message_id=(p_business->>'sourceMessageId')::uuid AND switch_id=(p_business->>'switchRequestId')::uuid;
 IF NOT FOUND OR p_business->>'owner' IS DISTINCT FROM 'inbound-z04-switch-confirmation-v1' OR p_business->>'sourcePayloadHash' IS DISTINCT FROM (SELECT payload_hash FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=proof.source_message_id AND company_id=proof.company_id)
  OR p_business#>>'{object,objectId}' IS DISTINCT FROM proof.source_object->>'point' OR p_business#>>'{object,identityAgency}' IS DISTINCT FROM proof.source_object->>'identityAgency'
  OR p_business->>'customerId' IS DISTINCT FROM proof.confirmed_period->>'customer_id' OR p_business->>'meteringPointId' IS DISTINCT FROM proof.confirmed_period->>'metering_point_id' OR p_business->>'siteId' IS DISTINCT FROM coalesce(proof.confirmed_switch->>'site_id',proof.confirmed_switch->>'customer_site_id')
  OR p_business#>>'{effectiveFrom,marketMinute}' IS DISTINCT FROM proof.source_object->>'start' OR (p_business#>>'{effectiveFrom,utc}')::timestamptz IS DISTINCT FROM proof.market_start_at
  OR p_party#>>'{receiver,identity,legalActorId}' IS DISTINCT FROM proof.legal_context->>'legalActorId' OR p_party#>>'{parties,legalReceiver}' IS DISTINCT FROM proof.legal_context->>'legalEdielId' THEN RETURN false;END IF;
 -- Reuse every existing source-party snapshot, scope, UTC and DATE-projection
 -- check. This local copy is only the legacy checker input; stored output and
 -- authoritative market timestamp remain precise and unchanged.
 legacy_shape:=jsonb_set(p_business,'{effectiveFrom,committedDatePrecision}','"market_calendar_day"');
 RETURN gridex_received_sources.object_owner_before_normal_minute_v1(p_party,legacy_shape,p_received) IS TRUE;
EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow THEN RETURN false;
END $$;
REVOKE ALL ON FUNCTION gridex_received_sources.object_owner_before_normal_minute_v1(jsonb,jsonb,timestamptz),gridex_received_sources.object_owner_proof_consistent(jsonb,jsonb,timestamptz) FROM PUBLIC,anon,authenticated,service_role;
COMMIT;

20260930204937_ediel_shared_accepted_sou.body:
BEGIN;
-- The same private accepted receipt authority is available to source consumers
-- after their own permission checks. An old sender's account lifecycle cannot
-- change the already established provider observation. No new I/O authority.
CREATE FUNCTION gridex_ediel_transport.accepted_source_basis_v1(p_message public.ediel_messages) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$
DECLARE m public.ediel_messages%rowtype;candidates jsonb;candidate jsonb;binding jsonb;provider jsonb;plan jsonb;recipient text;original_hash text;
 p_company_id uuid:=p_message.company_id;p_environment text:=p_message.environment;p_message_id uuid:=p_message.id;
BEGIN
 IF p_company_id IS NULL OR p_message_id IS NULL OR (p_environment IN('test','production')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_accepted_projection_scope_required';END IF;
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE company_id=p_company_id AND environment=p_environment AND id=p_message_id AND direction='outbound' FOR SHARE;
 IF m.raw_payload IS DISTINCT FROM p_message.raw_payload OR m.immutable_payload_hash IS DISTINCT FROM p_message.immutable_payload_hash THEN RAISE EXCEPTION 'ediel_accepted_projection_original_changed';END IF;
 -- Both journals are private, append-only observations. A latest/default
 -- attempt, route, guide or market permission is never selected here.
 SELECT coalesce(jsonb_agg(v),'[]') INTO candidates FROM (
  SELECT jsonb_build_object('lane','generic_journal','attemptId',a.id,'binding',a.binding,'providerReceipt',a.provider_result,'observedAt',a.observed_at,'entered',a.entered_at IS NOT NULL,'originalHash',a.binding->>'originalHash') v
   FROM gridex_ediel_transport.attempts a WHERE a.company_id=p_company_id AND a.environment=p_environment AND a.message_id=p_message_id AND a.classification='accepted'
  UNION ALL
  SELECT jsonb_build_object('lane','sealed_z08','attemptId',a.id,'binding',a.binding,'providerReceipt',e.facts->'provider','observedAt',e.observed_at,
    'entered',EXISTS(SELECT FROM gridex_outbound_dispatch.events entry WHERE entry.attempt_id=a.id AND entry.company_id=p_company_id AND entry.environment=p_environment AND entry.message_id=p_message_id AND entry.kind='provider_call_entered'),
    'originalHash',o.payload_hash,'sealedHash',encode(sha256(convert_to(o.raw_payload,'UTF8')),'hex'))
   FROM gridex_outbound_dispatch.attempts a JOIN gridex_outbound_dispatch.originals o ON o.message_id=a.message_id AND o.company_id=a.company_id AND o.environment=a.environment
   JOIN gridex_outbound_dispatch.events e ON e.attempt_id=a.id AND e.company_id=a.company_id AND e.environment=a.environment AND e.message_id=a.message_id AND e.kind='provider_result' AND e.facts->>'classification'='accepted'
   WHERE a.company_id=p_company_id AND a.environment=p_environment AND a.message_id=p_message_id
  LIMIT 2
 ) receipts;
 IF jsonb_array_length(candidates)=0 THEN RETURN NULL;END IF;
 IF jsonb_array_length(candidates)<>1 THEN RAISE EXCEPTION 'ediel_accepted_projection_ambiguous';END IF;
 candidate:=candidates->0;binding:=candidate->'binding';provider:=candidate->'providerReceipt';plan:=binding->'businessExpectationPlan';recipient:=nullif(binding->>'to','');
 original_hash:=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex');
 IF m.raw_payload IS NULL OR m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS DISTINCT FROM original_hash OR candidate->>'originalHash' IS DISTINCT FROM original_hash OR binding->>'originalHash' IS DISTINCT FROM original_hash OR (candidate->>'lane'='sealed_z08' AND candidate->>'sealedHash' IS DISTINCT FROM original_hash) THEN RAISE EXCEPTION 'ediel_accepted_projection_original_changed';END IF;
 IF candidate->>'entered' IS DISTINCT FROM 'true' OR nullif(candidate->>'observedAt','') IS NULL OR NOT isfinite((candidate->>'observedAt')::timestamptz) OR recipient IS NULL
  OR jsonb_typeof(provider) IS DISTINCT FROM 'object' OR jsonb_typeof(provider->'accepted') IS DISTINCT FROM 'array' OR jsonb_typeof(provider->'rejected') IS DISTINCT FROM 'array'
  THEN RAISE EXCEPTION 'ediel_accepted_projection_receipt_invalid';END IF;
 IF jsonb_array_length(provider->'accepted')<1 OR jsonb_array_length(provider->'rejected')<>0 OR EXISTS(SELECT FROM jsonb_array_elements(provider->'accepted') v WHERE jsonb_typeof(v) IS DISTINCT FROM 'string' OR lower(v#>>'{}') IS DISTINCT FROM lower(recipient)) OR (provider->>'messageId' IS NOT NULL AND jsonb_typeof(provider->'messageId') IS DISTINCT FROM 'string') OR (provider->>'response' IS NOT NULL AND jsonb_typeof(provider->'response') IS DISTINCT FROM 'string') THEN RAISE EXCEPTION 'ediel_accepted_projection_expected_recipient_required';END IF;
 IF plan IS NOT NULL AND plan<>'null'::jsonb AND (jsonb_typeof(plan) IS DISTINCT FROM 'object' OR plan->>'version' IS DISTINCT FROM '1' OR plan->>'sourceCode' IS DISTINCT FROM m.message_code OR plan->>'expectedFamily' IS DISTINCT FROM 'PRODAT' OR plan->>'anchor' IS DISTINCT FROM 'actual_accepted_smtp_observed_at') THEN RAISE EXCEPTION 'ediel_accepted_projection_frozen_plan_invalid';END IF;
 RETURN jsonb_build_object('status','accepted_projection','companyId',p_company_id,'environment',p_environment,'messageId',p_message_id,'attemptId',candidate->>'attemptId','lane',candidate->>'lane','originalHash',original_hash,'observedAt',candidate->>'observedAt','providerReceipt',jsonb_build_object('accepted',provider->'accepted','rejected',provider->'rejected','messageId',provider->'messageId','response',provider->'response'),'frozenRecipient',recipient,'businessExpectationPlan',plan,'authorizesProviderEntry',false,'deliveryProven',false);
END $$;
REVOKE ALL ON FUNCTION gridex_ediel_transport.accepted_source_basis_v1(public.ediel_messages) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.gridex_ediel_accepted_transport_projection_v1(p_company_id uuid,p_environment text,p_actor_user_id uuid,p_message_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' SET timezone='UTC' AS $$
DECLARE m public.ediel_messages%rowtype; candidates jsonb; candidate jsonb; binding jsonb; provider jsonb; plan jsonb; recipient text; original_hash text;
BEGIN
 IF p_company_id IS NULL OR p_actor_user_id IS NULL OR p_message_id IS NULL OR (p_environment IN ('test','production')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_accepted_projection_scope_required';END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.id FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active') OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL) OR public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.send') IS NOT TRUE THEN RAISE EXCEPTION 'ediel_accepted_projection_actor_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE company_id=p_company_id AND environment=p_environment AND id=p_message_id AND direction='outbound' FOR SHARE;
 RETURN gridex_ediel_transport.accepted_source_basis_v1(m);
END $$;
REVOKE ALL ON FUNCTION public.gridex_ediel_accepted_transport_projection_v1(uuid,text,uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.gridex_ediel_accepted_transport_projection_v1(uuid,text,uuid,uuid) TO service_role;
COMMIT;

20260930211830_ediel_supply_source_initi.body:
-- Exact initial approved scope remains locked and hash-bound even after later
-- accepted closure transitions. The provider observation supplies its own clock.
BEGIN;
CREATE OR REPLACE FUNCTION gridex_received_sources.supply_period_source_basis_v1(p_company_id uuid,p_period_id uuid,p_start timestamptz,p_end timestamptz) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE p public.customer_supply_periods%rowtype;proof gridex_received_sources.normal_switch_confirmations%rowtype;
 tr gridex_received_sources.supply_source_transitions%rowtype;activation gridex_received_sources.normal_supply_activations%rowtype;
 m public.ediel_messages%rowtype;origin public.ediel_messages%rowtype;initial_message public.ediel_messages%rowtype;c public.customer_contracts%rowtype;s public.supplier_switch_requests%rowtype;
 expected jsonb;baseline jsonb;legal jsonb;initial_owned jsonb;source_objects jsonb;initial_wire jsonb;accepted_original jsonb;initial_transition gridex_received_sources.supply_source_transitions%rowtype;ids uuid[];version bigint;source_id uuid;
BEGIN
 IF p_company_id IS NULL OR p_period_id IS NULL OR p_start IS NULL OR p_end IS NULL OR NOT isfinite(p_start) OR NOT isfinite(p_end) OR p_end<=p_start THEN RETURN NULL;END IF;
 SELECT * INTO p FROM public.customer_supply_periods WHERE id=p_period_id AND company_id=p_company_id;
 IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT * INTO proof FROM gridex_received_sources.normal_switch_confirmations WHERE period_id=p.id AND company_id=p_company_id;
 IF NOT FOUND THEN
  baseline:=gridex_received_sources.billing_supply_before_normal_switch_v1(p_company_id,p_period_id,p_start,p_end);
  IF baseline IS NULL THEN RETURN NULL;END IF;
  SELECT * INTO p FROM public.customer_supply_periods WHERE id=p_period_id AND company_id=p_company_id;
  IF p.market_state_version IS DISTINCT FROM (baseline->>'marketStateVersion')::bigint THEN RETURN NULL;END IF;
  SELECT own#>'{metadata,sourceObject}' INTO initial_owned FROM gridex_received_sources.supply_source_transitions initial,jsonb_array_elements(initial.resulting_states) own WHERE initial.source_message_id=p.source_message_id AND initial.company_id=p_company_id AND own->>'id'=p.id::text;
  SELECT * INTO origin FROM public.ediel_messages WHERE id=p.source_message_id AND company_id=p_company_id;
  SELECT jsonb_agg(own) INTO source_objects FROM jsonb_array_elements(gridex_received_sources.normal_switch_wire_v1(origin.raw_payload)->'objects') own WHERE own->>'point'=initial_owned->>'point' AND own->>'li'=initial_owned->>'li' AND own->>'start'=initial_owned->>'start';
  IF jsonb_array_length(source_objects) IS DISTINCT FROM 1 OR (source_objects#>>'{0,identityAgency}' IN('9','89')) IS NOT TRUE THEN RETURN NULL;END IF;
  RETURN baseline||jsonb_build_object('initialSourceMessageId',p.source_message_id,'legalActorId',(SELECT g.legal_actor_id FROM gridex_received_sources.regulated_supply_ground_versions g WHERE g.id::text=baseline->>'groundId' AND g.company_id=p_company_id),'sourceObjects',source_objects,'dsoEdielId',gridex_received_sources.normal_switch_wire_v1(origin.raw_payload)->>'sender');
 END IF;
 version:=p.market_state_version;source_id:=p.source_message_id;
 SELECT array_agg(t.source_message_id) INTO ids FROM gridex_received_sources.supply_source_transitions t WHERE t.company_id=p_company_id AND EXISTS(SELECT FROM jsonb_array_elements(t.resulting_states) own WHERE own->>'id'=p.id::text AND (own->>'market_state_version')::bigint=version);
 IF coalesce(cardinality(ids),0)<>1 THEN RETURN NULL;END IF;
 PERFORM z.id FROM public.ediel_messages z WHERE z.company_id=p_company_id AND z.id=ANY(ARRAY[ids[1],source_id,proof.source_message_id,proof.original_message_id]) ORDER BY z.id FOR UPDATE;
 legal:=gridex_ediel_inbound_context.require_v1(p_company_id,proof.source_message_id);
 SELECT * INTO initial_message FROM public.ediel_messages WHERE id=proof.source_message_id AND company_id=p_company_id;
 SELECT * INTO initial_transition FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=proof.source_message_id AND company_id=p_company_id;
 initial_wire:=gridex_received_sources.normal_switch_wire_v1(initial_message.raw_payload);
 IF initial_message.direction IS DISTINCT FROM 'inbound' OR initial_message.message_family IS DISTINCT FROM 'PRODAT' OR initial_message.message_code IS DISTINCT FROM 'Z04'
  OR initial_transition.payload_hash IS DISTINCT FROM encode(sha256(convert_to(initial_message.raw_payload,'UTF8')),'hex')
  OR initial_wire->>'receiver' IS DISTINCT FROM proof.legal_context->>'legalEdielId' OR nullif(initial_wire->>'sender','') IS NULL
  OR (SELECT count(*) FROM jsonb_array_elements(initial_wire->'objects') own WHERE own=proof.source_object)<>1
  OR NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments v WHERE v.source_message_id=initial_message.id AND v.company_id=p_company_id AND v.environment=initial_message.environment AND v.source_payload_hash=initial_transition.payload_hash AND v.facts_text::jsonb->>'syntaxDecision'='accepted' AND v.facts_text::jsonb->>'applicationDecision'='accepted' AND v.facts_text::jsonb->>'functionalDecision'='accepted' AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)) THEN RETURN NULL;END IF;
 SELECT * INTO s FROM public.supplier_switch_requests WHERE id=proof.switch_id AND company_id=p_company_id FOR SHARE;
 SELECT * INTO p FROM public.customer_supply_periods WHERE id=p_period_id AND company_id=p_company_id FOR SHARE;
 IF p.market_state_version IS DISTINCT FROM version OR p.source_message_id IS DISTINCT FROM source_id OR p.source_message_id IS DISTINCT FROM proof.source_message_id OR p.source_switch_request_id IS DISTINCT FROM proof.switch_id
  OR p.customer_id IS DISTINCT FROM (proof.confirmed_period->>'customer_id')::uuid OR p.metering_point_id IS DISTINCT FROM (proof.confirmed_period->>'metering_point_id')::uuid
  OR p.market_start_at IS DISTINCT FROM proof.market_start_at OR p.market_start_at>p_start OR (p.market_end_at IS NOT NULL AND p_end>p.market_end_at)
  OR (p.status IN('confirmed_by_grid_owner','active','ending','ended')) IS NOT TRUE OR s.inbound_z04_message_id IS DISTINCT FROM proof.source_message_id OR s.outbound_z03_message_id IS DISTINCT FROM proof.original_message_id
  OR s.customer_id IS DISTINCT FROM p.customer_id OR s.metering_point_id IS DISTINCT FROM p.metering_point_id OR s.lifecycle_blocked THEN RETURN NULL;END IF;
 SELECT * INTO tr FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=ids[1] AND company_id=p_company_id;
 SELECT * INTO m FROM public.ediel_messages WHERE id=tr.source_message_id AND company_id=p_company_id;
 SELECT own INTO expected FROM jsonb_array_elements(tr.resulting_states) own WHERE own->>'id'=p.id::text;
 SELECT * INTO activation FROM gridex_received_sources.normal_supply_activations WHERE period_id=p.id AND company_id=p_company_id;
 baseline:=CASE WHEN activation.period_id IS NOT NULL AND tr.source_message_id=proof.source_message_id THEN activation.resulting_period ELSE expected END;
 IF expected IS NULL OR baseline IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR tr.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  OR (to_jsonb(p)-ARRAY['updated_at','status']) IS DISTINCT FROM (baseline-ARRAY['updated_at','status'])
  OR (p.status IS DISTINCT FROM baseline->>'status' AND NOT(p.status='ended' AND baseline->>'status'='ending' AND p.market_end_at<=now()))
  OR (s.status IS DISTINCT FROM proof.confirmed_switch->>'status' AND NOT(s.status='completed' AND activation.period_id IS NOT NULL)) THEN RETURN NULL;END IF;
 SELECT * INTO origin FROM public.ediel_messages WHERE id=proof.original_message_id AND company_id=p_company_id AND environment=m.environment;
 SELECT * INTO c FROM public.customer_contracts WHERE id=proof.contract_id AND company_id=p_company_id FOR SHARE;
 IF origin.direction IS DISTINCT FROM 'outbound' OR gridex_received_sources.sent_source_is_current_v1(origin) IS NOT TRUE OR origin.immutable_payload_hash IS DISTINCT FROM proof.original_payload_hash OR origin.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(origin.raw_payload,'UTF8')),'hex')
  OR c.id IS NULL OR c.customer_id IS DISTINCT FROM p.customer_id OR c.metering_point_id IS DISTINCT FROM p.metering_point_id OR (c.status IN('signed','active')) IS NOT TRUE OR gridex_received_sources.production_contract_hash_v1(c) IS DISTINCT FROM proof.protected_contract_hash
  OR legal->>'legalActorId' IS DISTINCT FROM proof.legal_context->>'legalActorId' OR legal->>'actorRole' IS DISTINCT FROM 'electricity_supplier'
  OR NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments v WHERE v.source_message_id=m.id AND v.company_id=p_company_id AND v.environment=m.environment AND v.source_payload_hash=tr.payload_hash AND v.facts_text::jsonb->>'syntaxDecision'='accepted' AND v.facts_text::jsonb->>'applicationDecision'='accepted' AND v.facts_text::jsonb->>'functionalDecision'='accepted' AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)) THEN RETURN NULL;END IF;
 accepted_original:=gridex_ediel_transport.accepted_source_basis_v1(origin);
 IF accepted_original IS NULL THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('qualified',true,'periodId',p.id,'companyId',p.company_id,'customerId',p.customer_id,'meteringPointId',p.metering_point_id,'siteId',coalesce(proof.confirmed_switch->>'site_id',proof.confirmed_switch->>'customer_site_id'),'switchId',proof.switch_id,
  'sourceMessageId',m.id,'initialSourceMessageId',proof.source_message_id,'currentSourceMessageId',m.id,'payloadHash',tr.payload_hash,'marketStateVersion',p.market_state_version,'marketStartAt',p.market_start_at,'marketEndAt',p.market_end_at,
  'legalActorId',proof.legal_context->>'legalActorId','sourceObjects',jsonb_build_array(proof.source_object),'dsoEdielId',initial_wire->>'sender','originalMessageId',origin.id,'originalPayloadHash',origin.immutable_payload_hash,'originalAcceptedAt',accepted_original->>'observedAt','activated',activation.period_id IS NOT NULL);
END $$;
REVOKE ALL ON FUNCTION gridex_received_sources.supply_period_source_basis_v1(uuid,uuid,timestamptz,timestamptz) FROM PUBLIC,anon,authenticated,service_role;
COMMIT;

20260930221158_ediel_source_qualified_sw.body:
-- TR05/CALL03: append an operation-qualified corrected switch original and
-- advance only its still-unapproved operative correlation. Old messages, ACKs,
-- provider attempts and immutable originals remain unchanged.
BEGIN;
ALTER TABLE gridex_received_sources.switch_originals ADD COLUMN recovery_operation_id uuid REFERENCES gridex_received_sources.prodat_recovery_operations(id);
CREATE UNIQUE INDEX switch_original_recovery_operation_unique ON gridex_received_sources.switch_originals(recovery_operation_id) WHERE recovery_operation_id IS NOT NULL;
CREATE FUNCTION public.ediel_bind_switch_correction_v1(p_company_id uuid,p_message_id uuid,p_actor_user_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE m public.ediel_messages%rowtype;s public.supplier_switch_requests%rowtype;c public.customer_contracts%rowtype;
 r public.outbound_requests%rowtype;mp public.metering_points%rowtype;prior gridex_received_sources.switch_originals%rowtype;
 op gridex_received_sources.prodat_recovery_operations%rowtype; old_origin gridex_received_sources.switch_originals%rowtype; original public.ediel_messages%rowtype;basis jsonb;w jsonb;own jsonb;before_state jsonb;identity text;identity_qualifier text;expected_reason text;i public.ediel_message_intents%rowtype;
BEGIN
 -- Discover the selector only. The immutable operation authority locks and
 -- requalifies the original/ACK before any operative switch mutation.
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id;
 SELECT operation.* INTO op FROM gridex_received_sources.prodat_recovery_messages link JOIN gridex_received_sources.prodat_recovery_operations operation ON operation.id=link.operation_id WHERE link.message_id=m.id AND operation.company_id=p_company_id;
 IF op.id IS NULL OR (op.kind IN('contrl_correction','aperak_correction')) IS NOT TRUE THEN RAISE EXCEPTION 'switch_correction_operation_required';END IF;
 SELECT * INTO prior FROM gridex_received_sources.switch_originals WHERE message_id=m.id;
 IF prior.message_id IS NOT NULL THEN
  PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
  PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id FOR SHARE;
  IF prior.company_id IS DISTINCT FROM p_company_id OR prior.recovery_operation_id IS DISTINCT FROM op.id OR prior.intent_id IS DISTINCT FROM m.intent_id OR prior.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'switch_correction_replay_conflict';END IF;
  IF p_actor_user_id IS NULL OR public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.write') IS NOT TRUE OR NOT EXISTS(SELECT FROM public.company_memberships cm JOIN public.user_profiles u ON u.id=cm.user_id WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL AND u.user_status='active') THEN RAISE EXCEPTION 'switch_original_execution_actor_required';END IF;
  RETURN jsonb_build_object('status','bound','messageId',m.id,'idempotent',true);
 END IF;
 basis:=public.ediel_prodat_recovery_operation_basis_v1(p_company_id,op.id,p_actor_user_id);
 IF basis IS NULL OR basis->>'operationId' IS DISTINCT FROM op.id::text OR basis->>'correctedPayloadHash' IS DISTINCT FROM op.corrected_payload_hash THEN RAISE EXCEPTION 'switch_correction_qualified_negative_source_required';END IF;
 SELECT * INTO STRICT original FROM public.ediel_messages WHERE id=op.original_message_id AND company_id=p_company_id FOR UPDATE;
 SELECT * INTO old_origin FROM gridex_received_sources.switch_originals WHERE message_id=original.id AND company_id=p_company_id;
 IF old_origin.message_id IS NULL OR old_origin.payload_hash IS DISTINCT FROM op.original_payload_hash OR original.immutable_payload_hash IS DISTINCT FROM op.original_payload_hash OR op.original_payload_hash IS DISTINCT FROM encode(sha256(convert_to(original.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'switch_correction_owned_original_required';END IF;
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR UPDATE;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
  OR public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.write') IS NOT TRUE THEN RAISE EXCEPTION 'switch_original_execution_actor_required';END IF;
 PERFORM gridex_ediel_transport.require_message_intent_v1(m);
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=m.intent_id FOR SHARE;
 SELECT * INTO s FROM public.supplier_switch_requests WHERE id=old_origin.switch_id AND company_id=p_company_id FOR UPDATE;
 SELECT * INTO c FROM public.customer_contracts WHERE id=coalesce(s.customer_contract_id,s.contract_id) AND company_id=p_company_id FOR SHARE;
 SELECT * INTO mp FROM public.metering_points WHERE id=s.metering_point_id AND company_id=p_company_id FOR SHARE;
 SELECT * INTO r FROM public.outbound_requests WHERE id=m.outbound_request_id AND company_id=p_company_id FOR SHARE;
 PERFORM customer.id FROM public.customers customer WHERE customer.id=s.customer_id AND customer.company_id=p_company_id FOR SHARE;
 SELECT coalesce(nullif(btrim(customer.org_number),''),nullif(btrim(customer.personal_number),'')),CASE WHEN nullif(btrim(customer.org_number),'') IS NOT NULL THEN 'SE1' ELSE 'SE2' END INTO identity,identity_qualifier FROM public.customers customer WHERE customer.id=s.customer_id AND customer.company_id=p_company_id;
 w:=gridex_received_sources.switch_origin_wire_v1(m.raw_payload);own:=w#>'{objects,0}';
 expected_reason:=CASE WHEN s.request_type='move_in' OR s.prodat_variant='LK' OR s.prodat_reason='Z23' THEN 'Z23' ELSE 'Z22' END;
 IF i.id IS NULL OR i.operation_id IS DISTINCT FROM op.id OR i.supplier_switch_request_id IS DISTINCT FROM s.id OR s.id IS NULL OR c.id IS NULL OR mp.id IS NULL OR r.id IS NULL OR w IS NULL OR m.direction IS DISTINCT FROM 'outbound' OR m.message_standard IS DISTINCT FROM 'edifact' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z03' OR m.status IS DISTINCT FROM 'draft'
  OR m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  OR m.switch_request_id IS DISTINCT FROM s.id OR m.source_operation_id IS DISTINCT FROM op.id::text OR m.original_message_id IS DISTINCT FROM original.id OR m.environment IS DISTINCT FROM op.environment OR m.raw_payload IS DISTINCT FROM op.corrected_raw_payload OR m.immutable_payload_hash IS DISTINCT FROM op.corrected_payload_hash OR m.customer_id IS DISTINCT FROM s.customer_id OR m.site_id IS DISTINCT FROM coalesce(s.site_id,s.customer_site_id) OR m.metering_point_id IS DISTINCT FROM s.metering_point_id
  OR (s.site_id IS NOT NULL AND s.site_id IS DISTINCT FROM m.site_id) OR (s.customer_site_id IS NOT NULL AND s.customer_site_id IS DISTINCT FROM m.site_id) OR (s.contract_id IS NOT NULL AND s.contract_id IS DISTINCT FROM c.id) OR (s.customer_contract_id IS NOT NULL AND s.customer_contract_id IS DISTINCT FROM c.id)
  OR s.outbound_z03_message_id IS DISTINCT FROM original.id OR s.inbound_z04_message_id IS NOT NULL OR s.lifecycle_blocked IS DISTINCT FROM false OR (s.status IN('prepared','queued','submitted','failed','rejected')) IS NOT TRUE
  OR (r.payload->>'environment') IS DISTINCT FROM m.environment OR r.source_type IS DISTINCT FROM 'manual' OR r.source_id IS DISTINCT FROM i.id OR r.operation_id IS DISTINCT FROM op.id OR r.request_type IS DISTINCT FROM 'supplier_switch' OR r.customer_id IS DISTINCT FROM s.customer_id OR r.site_id IS DISTINCT FROM m.site_id OR r.metering_point_id IS DISTINCT FROM mp.id
  OR c.id IS DISTINCT FROM old_origin.contract_id OR gridex_received_sources.production_contract_hash_v1(c) IS DISTINCT FROM old_origin.contract_hash OR c.customer_id IS DISTINCT FROM s.customer_id OR c.metering_point_id IS DISTINCT FROM mp.id OR (c.status IN('signed','active')) IS NOT TRUE OR c.signed_at IS NULL OR nullif(c.signed_version,'') IS NULL
  OR mp.customer_id IS DISTINCT FROM s.customer_id OR mp.site_id IS DISTINCT FROM m.site_id OR own->>'installationPoint' IS DISTINCT FROM coalesce(nullif(mp.ediel_metering_point_id,''),nullif(mp.meter_point_id,'')) OR own->>'installationAgency' IS DISTINCT FROM '9'
  OR own->>'customerQualifier' IS DISTINCT FROM identity_qualifier OR own->>'customerAgency' IS DISTINCT FROM '260' OR own->>'reason' IS DISTINCT FROM expected_reason OR own->>'customerIdentity' IS DISTINCT FROM identity OR nullif(own->>'li','') IS NULL
  OR (own-'li'-'line') IS DISTINCT FROM (old_origin.original_object-'li'-'line') OR gridex_received_sources.permission_date_v1(own->>'start') IS DISTINCT FROM s.requested_start_date THEN RAISE EXCEPTION 'switch_original_owned_source_required';END IF;
 PERFORM public.gridex_assert_supplier_switch_ready(p_company_id,c.id);
 before_state:=to_jsonb(s);
 UPDATE public.supplier_switch_requests SET outbound_z03_message_id=m.id,rff_li_reference=own->>'li',status='prepared',updated_by=p_actor_user_id,updated_at=now() WHERE id=s.id AND company_id=p_company_id RETURNING * INTO s;
 INSERT INTO gridex_received_sources.switch_originals(message_id,company_id,switch_id,intent_id,outbound_request_id,payload_hash,contract_id,contract_hash,original_object,previous_switch,resulting_switch,actor_user_id,recovery_operation_id)
 VALUES(m.id,p_company_id,s.id,m.intent_id,m.outbound_request_id,m.immutable_payload_hash,c.id,gridex_received_sources.production_contract_hash_v1(c),own,before_state,to_jsonb(s),p_actor_user_id,op.id);
 RETURN jsonb_build_object('status','bound','messageId',m.id,'idempotent',false);
END $$;
REVOKE ALL ON FUNCTION public.ediel_bind_switch_correction_v1(uuid,uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ediel_bind_switch_correction_v1(uuid,uuid,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.ediel_require_switch_original_current_v1(p_company_id uuid,p_message_id uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE m public.ediel_messages%rowtype;o gridex_received_sources.switch_originals%rowtype;s public.supplier_switch_requests%rowtype;
 c public.customer_contracts%rowtype;mp public.metering_points%rowtype;r public.outbound_requests%rowtype;i public.ediel_message_intents%rowtype;op gridex_received_sources.prodat_recovery_operations%rowtype; expected_operation uuid;expected_request_source uuid;expected_request_type text;q jsonb;w jsonb;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR SHARE;
 IF m.id IS NULL THEN RAISE EXCEPTION 'switch_original_message_required';END IF;
 IF m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z03' THEN RETURN;END IF;
 w:=gridex_received_sources.switch_origin_wire_v1(m.raw_payload);
 -- Z03C has its own cancellation owner, never a new normal-switch original.
 IF w IS NOT NULL AND w#>>'{objects,0,reason}'='Z24' THEN RETURN;END IF;
 SELECT * INTO o FROM gridex_received_sources.switch_originals WHERE message_id=m.id AND company_id=m.company_id;
 IF NOT FOUND THEN
  IF m.environment IS DISTINCT FROM 'test' THEN RAISE EXCEPTION 'switch_original_source_required';END IF;
  IF EXISTS(SELECT FROM gridex_negative_fixtures.positive_consumptions x WHERE x.company_id=m.company_id AND x.message_id=m.id)
   AND EXISTS(SELECT FROM gridex_negative_fixtures.negative_prepared_consumptions x WHERE x.company_id=m.company_id AND x.message_id=m.id) THEN RAISE EXCEPTION 'switch_fixture_source_ambiguous';END IF;
  IF EXISTS(SELECT FROM gridex_negative_fixtures.positive_consumptions x WHERE x.company_id=m.company_id AND x.message_id=m.id) THEN
   q:=gridex_negative_fixtures.require_positive_message_v1(m.company_id,m.id,'Z03');
   IF q->>'kind' IS DISTINCT FROM 'source_qualified_positive_fixture' OR q->>'expectedOutcome' IS DISTINCT FROM 'positive' OR q->'expectedDiagnosticCodes' IS DISTINCT FROM '[]'::jsonb THEN RAISE EXCEPTION 'switch_fixture_positive_scope_required';END IF;
  ELSIF EXISTS(SELECT FROM gridex_negative_fixtures.negative_prepared_consumptions x WHERE x.company_id=m.company_id AND x.message_id=m.id) THEN
   q:=gridex_negative_fixtures.require_negative_message_v1(m.company_id,m.id,'Z03');
   IF q->>'kind' IS DISTINCT FROM 'source_qualified_negative_fixture' OR q->>'expectedOutcome' IS DISTINCT FROM 'negative' OR jsonb_typeof(q->'expectedDiagnosticCodes') IS DISTINCT FROM 'array' OR jsonb_array_length(q->'expectedDiagnosticCodes') NOT BETWEEN 1 AND 256 THEN RAISE EXCEPTION 'switch_fixture_negative_scope_required';END IF;
  ELSE RAISE EXCEPTION 'switch_original_source_required';END IF;
  IF q->>'companyId' IS DISTINCT FROM m.company_id::text OR q->>'roleCode' IS DISTINCT FROM 'supplier' OR q->>'authorizesBusinessEffect' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'switch_fixture_supplier_scope_required';END IF;
  RETURN;
 END IF;
 expected_operation:=o.switch_id;expected_request_source:=o.switch_id;expected_request_type:='supplier_switch_request';
 IF o.recovery_operation_id IS NOT NULL THEN
  SELECT operation.* INTO op FROM gridex_received_sources.prodat_recovery_messages link JOIN gridex_received_sources.prodat_recovery_operations operation ON operation.id=link.operation_id WHERE link.message_id=m.id AND operation.company_id=p_company_id;
  IF op.id IS DISTINCT FROM o.recovery_operation_id OR (op.kind IN('contrl_correction','aperak_correction')) IS NOT TRUE OR m.original_message_id IS DISTINCT FROM op.original_message_id THEN RAISE EXCEPTION 'switch_correction_current_operation_required';END IF;
  PERFORM public.ediel_require_prodat_recovery_current_v1(p_company_id,m.id);
  expected_operation:=op.id;expected_request_source:=o.intent_id;expected_request_type:='manual';
 END IF;
 SELECT * INTO s FROM public.supplier_switch_requests WHERE id=o.switch_id AND company_id=o.company_id FOR SHARE;
 SELECT * INTO c FROM public.customer_contracts WHERE id=o.contract_id AND company_id=o.company_id FOR SHARE;
 SELECT * INTO mp FROM public.metering_points WHERE id=s.metering_point_id AND company_id=s.company_id FOR SHARE;
 SELECT * INTO r FROM public.outbound_requests WHERE id=o.outbound_request_id AND company_id=o.company_id FOR SHARE;
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=o.intent_id FOR SHARE;
 IF i.id IS NULL OR i.operation_id IS DISTINCT FROM expected_operation OR i.supplier_switch_request_id IS DISTINCT FROM s.id OR m.source_operation_id IS DISTINCT FROM expected_operation::text OR w IS NULL OR (w#>>'{objects,0,reason}' IN('Z22','Z23')) IS NOT TRUE
  OR m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS DISTINCT FROM o.payload_hash OR o.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  OR m.intent_id IS DISTINCT FROM o.intent_id OR m.outbound_request_id IS DISTINCT FROM o.outbound_request_id OR m.switch_request_id IS DISTINCT FROM s.id OR m.customer_id IS DISTINCT FROM s.customer_id OR m.site_id IS DISTINCT FROM coalesce(s.site_id,s.customer_site_id) OR m.metering_point_id IS DISTINCT FROM s.metering_point_id
  OR r.id IS NULL OR (r.payload->>'environment') IS DISTINCT FROM m.environment OR r.source_type IS DISTINCT FROM expected_request_type OR r.source_id IS DISTINCT FROM expected_request_source OR r.operation_id IS DISTINCT FROM expected_operation OR r.request_type IS DISTINCT FROM 'supplier_switch' OR r.customer_id IS DISTINCT FROM m.customer_id OR r.site_id IS DISTINCT FROM m.site_id OR r.metering_point_id IS DISTINCT FROM m.metering_point_id
  OR s.id IS NULL OR c.id IS NULL OR mp.id IS NULL OR s.outbound_z03_message_id IS DISTINCT FROM m.id OR s.inbound_z04_message_id IS NOT NULL OR s.lifecycle_blocked IS DISTINCT FROM false OR (s.status IN('prepared','queued','submitted')) IS NOT TRUE
  OR (s.contract_id IS NOT NULL AND s.contract_id IS DISTINCT FROM c.id) OR (s.customer_contract_id IS NOT NULL AND s.customer_contract_id IS DISTINCT FROM c.id)
  OR (s.site_id IS NOT NULL AND s.site_id IS DISTINCT FROM m.site_id) OR (s.customer_site_id IS NOT NULL AND s.customer_site_id IS DISTINCT FROM m.site_id)
  OR s.rff_li_reference IS DISTINCT FROM o.original_object->>'li' OR w#>'{objects,0}' IS DISTINCT FROM o.original_object
  OR gridex_received_sources.production_contract_hash_v1(c) IS DISTINCT FROM o.contract_hash OR (c.status IN('signed','active')) IS NOT TRUE
  OR c.customer_id IS DISTINCT FROM m.customer_id OR c.metering_point_id IS DISTINCT FROM mp.id OR mp.customer_id IS DISTINCT FROM m.customer_id OR mp.site_id IS DISTINCT FROM m.site_id
  OR o.original_object->>'installationPoint' IS DISTINCT FROM coalesce(nullif(mp.ediel_metering_point_id,''),nullif(mp.meter_point_id,''))
  THEN RAISE EXCEPTION 'switch_original_current_source_required';END IF;
 PERFORM public.gridex_assert_supplier_switch_ready(p_company_id,c.id);
END $$;
CREATE OR REPLACE FUNCTION gridex_received_sources.switch_original_message_immutable_v1() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
 IF EXISTS(SELECT FROM gridex_received_sources.switch_originals o WHERE o.message_id=OLD.id) AND
 ROW(NEW.id,NEW.company_id,NEW.environment,NEW.direction,NEW.message_standard,NEW.message_family,NEW.message_code,NEW.intent_id,NEW.outbound_request_id,NEW.source_operation_id,NEW.switch_request_id,NEW.customer_id,NEW.site_id,NEW.metering_point_id,NEW.raw_payload,NEW.immutable_payload_hash,NEW.immutable_rendered_at,NEW.original_message_id)
 IS DISTINCT FROM ROW(OLD.id,OLD.company_id,OLD.environment,OLD.direction,OLD.message_standard,OLD.message_family,OLD.message_code,OLD.intent_id,OLD.outbound_request_id,OLD.source_operation_id,OLD.switch_request_id,OLD.customer_id,OLD.site_id,OLD.metering_point_id,OLD.raw_payload,OLD.immutable_payload_hash,OLD.immutable_rendered_at,OLD.original_message_id)
 THEN RAISE EXCEPTION 'switch_original_bound_message_immutable';END IF;RETURN NEW;
END $$;

-- Locked operational request projections cannot introduce another environment
-- or operation than their immutable source/intent. No original migration edit.
CREATE OR REPLACE FUNCTION public.ediel_bind_switch_original_v1(p_company_id uuid,p_switch_id uuid,p_message_id uuid,p_actor_user_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE m public.ediel_messages%rowtype;s public.supplier_switch_requests%rowtype;c public.customer_contracts%rowtype;
 r public.outbound_requests%rowtype;mp public.metering_points%rowtype;prior gridex_received_sources.switch_originals%rowtype;
 w jsonb;own jsonb;before_state jsonb;identity text;identity_qualifier text;expected_reason text;i public.ediel_message_intents%rowtype;
BEGIN
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR UPDATE;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
  OR public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.write') IS NOT TRUE THEN RAISE EXCEPTION 'switch_original_execution_actor_required';END IF;
 SELECT * INTO prior FROM gridex_received_sources.switch_originals WHERE message_id=m.id;
 IF FOUND THEN IF prior.company_id IS DISTINCT FROM p_company_id OR prior.switch_id IS DISTINCT FROM p_switch_id OR prior.intent_id IS DISTINCT FROM m.intent_id OR prior.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'switch_original_replay_conflict';END IF;RETURN jsonb_build_object('status','bound','messageId',m.id,'idempotent',true);END IF;
 PERFORM gridex_ediel_transport.require_message_intent_v1(m);
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=m.intent_id FOR SHARE;
 SELECT * INTO s FROM public.supplier_switch_requests WHERE id=p_switch_id AND company_id=p_company_id FOR UPDATE;
 SELECT * INTO c FROM public.customer_contracts WHERE id=coalesce(s.customer_contract_id,s.contract_id) AND company_id=p_company_id FOR SHARE;
 SELECT * INTO mp FROM public.metering_points WHERE id=s.metering_point_id AND company_id=p_company_id FOR SHARE;
 SELECT * INTO r FROM public.outbound_requests WHERE id=m.outbound_request_id AND company_id=p_company_id FOR SHARE;
 PERFORM customer.id FROM public.customers customer WHERE customer.id=s.customer_id AND customer.company_id=p_company_id FOR SHARE;
 SELECT coalesce(nullif(btrim(customer.org_number),''),nullif(btrim(customer.personal_number),'')),CASE WHEN nullif(btrim(customer.org_number),'') IS NOT NULL THEN 'SE1' ELSE 'SE2' END INTO identity,identity_qualifier FROM public.customers customer WHERE customer.id=s.customer_id AND customer.company_id=p_company_id;
 w:=gridex_received_sources.switch_origin_wire_v1(m.raw_payload);own:=w#>'{objects,0}';
 expected_reason:=CASE WHEN s.request_type='move_in' OR s.prodat_variant='LK' OR s.prodat_reason='Z23' THEN 'Z23' ELSE 'Z22' END;
 IF i.id IS NULL OR i.operation_id IS DISTINCT FROM s.id OR s.id IS NULL OR c.id IS NULL OR mp.id IS NULL OR r.id IS NULL OR w IS NULL OR m.direction IS DISTINCT FROM 'outbound' OR m.message_standard IS DISTINCT FROM 'edifact' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z03' OR m.status IS DISTINCT FROM 'draft'
  OR m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  OR m.switch_request_id IS DISTINCT FROM s.id OR m.source_operation_id IS DISTINCT FROM s.id::text OR m.customer_id IS DISTINCT FROM s.customer_id OR m.site_id IS DISTINCT FROM coalesce(s.site_id,s.customer_site_id) OR m.metering_point_id IS DISTINCT FROM s.metering_point_id
  OR (s.site_id IS NOT NULL AND s.site_id IS DISTINCT FROM m.site_id) OR (s.customer_site_id IS NOT NULL AND s.customer_site_id IS DISTINCT FROM m.site_id) OR (s.contract_id IS NOT NULL AND s.contract_id IS DISTINCT FROM c.id) OR (s.customer_contract_id IS NOT NULL AND s.customer_contract_id IS DISTINCT FROM c.id)
  OR s.outbound_z03_message_id IS NOT NULL OR s.inbound_z04_message_id IS NOT NULL OR s.lifecycle_blocked IS DISTINCT FROM false OR (s.status IN('draft','ready','ready_for_switch','ready_for_z03','z03_ready','prepared','queued','waiting')) IS NOT TRUE
  OR (r.payload->>'environment') IS DISTINCT FROM m.environment OR r.source_type IS DISTINCT FROM 'supplier_switch_request' OR r.source_id IS DISTINCT FROM s.id OR r.operation_id IS DISTINCT FROM s.id OR r.request_type IS DISTINCT FROM 'supplier_switch' OR r.customer_id IS DISTINCT FROM s.customer_id OR r.site_id IS DISTINCT FROM m.site_id OR r.metering_point_id IS DISTINCT FROM mp.id
  OR c.customer_id IS DISTINCT FROM s.customer_id OR c.metering_point_id IS DISTINCT FROM mp.id OR (c.status IN('signed','active')) IS NOT TRUE OR c.signed_at IS NULL OR nullif(c.signed_version,'') IS NULL
  OR mp.customer_id IS DISTINCT FROM s.customer_id OR mp.site_id IS DISTINCT FROM m.site_id OR own->>'installationPoint' IS DISTINCT FROM coalesce(nullif(mp.ediel_metering_point_id,''),nullif(mp.meter_point_id,'')) OR own->>'installationAgency' IS DISTINCT FROM '9'
  OR own->>'customerQualifier' IS DISTINCT FROM identity_qualifier OR own->>'customerAgency' IS DISTINCT FROM '260' OR own->>'reason' IS DISTINCT FROM expected_reason OR own->>'customerIdentity' IS DISTINCT FROM identity OR nullif(own->>'li','') IS NULL
  OR gridex_received_sources.permission_date_v1(own->>'start') IS DISTINCT FROM s.requested_start_date THEN RAISE EXCEPTION 'switch_original_owned_source_required';END IF;
 PERFORM public.gridex_assert_supplier_switch_ready(p_company_id,c.id);
 before_state:=to_jsonb(s);
 UPDATE public.supplier_switch_requests SET outbound_z03_message_id=m.id,rff_li_reference=own->>'li',status='prepared',updated_by=p_actor_user_id,updated_at=now() WHERE id=s.id AND company_id=p_company_id RETURNING * INTO s;
 INSERT INTO gridex_received_sources.switch_originals(message_id,company_id,switch_id,intent_id,outbound_request_id,payload_hash,contract_id,contract_hash,original_object,previous_switch,resulting_switch,actor_user_id)
 VALUES(m.id,p_company_id,s.id,m.intent_id,m.outbound_request_id,m.immutable_payload_hash,c.id,gridex_received_sources.production_contract_hash_v1(c),own,before_state,to_jsonb(s),p_actor_user_id);
 RETURN jsonb_build_object('status','bound','messageId',m.id,'idempotent',false);
END $$;
CREATE OR REPLACE FUNCTION public.ediel_reserve_prodat_recovery_origin_v1(p_company_id uuid,p_operation_id uuid,p_actor_user_id uuid,p_intent_id uuid,p_outbound_request_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE op gridex_received_sources.prodat_recovery_operations%rowtype;o gridex_received_sources.prodat_recovery_origins%rowtype;i public.ediel_message_intents%rowtype;m public.ediel_messages%rowtype;r public.outbound_requests%rowtype;basis jsonb;w jsonb;request_type text;
BEGIN
 basis:=public.ediel_prodat_recovery_operation_basis_v1(p_company_id,p_operation_id,p_actor_user_id);
 IF basis IS NULL THEN RAISE EXCEPTION 'prodat_recovery_correction_basis_required';END IF;
 SELECT * INTO STRICT op FROM gridex_received_sources.prodat_recovery_operations WHERE id=p_operation_id AND company_id=p_company_id;
 -- The preceding source qualification already holds the sealed original lock.
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=op.original_message_id AND company_id=p_company_id;
 w:=gridex_received_sources.prodat_recovery_wire_v1(op.corrected_raw_payload);
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=p_intent_id AND company_id=p_company_id FOR SHARE;
 request_type:=CASE WHEN w->>'code' IN ('Z03','Z08') THEN 'supplier_switch' WHEN w->>'code' IN ('Z13','Z18') THEN 'metering_access' ELSE 'customer_masterdata' END;
 IF i.id IS NULL OR i.environment IS DISTINCT FROM op.environment OR i.message_family IS DISTINCT FROM 'PRODAT' OR i.message_code IS DISTINCT FROM w->>'code'
 OR i.direction IS DISTINCT FROM 'outbound' OR i.customer_id IS DISTINCT FROM m.customer_id OR i.operation_id IS DISTINCT FROM op.id
 OR i.validation_status IS DISTINCT FROM 'validated' OR i.interchange_reference IS DISTINCT FROM w->>'interchange' OR i.message_reference IS DISTINCT FROM w->>'messageReference'
 OR i.sender_ediel_id IS DISTINCT FROM w#>>'{transportSender,0}' OR i.receiver_ediel_id IS DISTINCT FROM w#>>'{transportReceiver,0}'
 OR i.communication_route_id IS NULL OR i.route_profile_id IS NULL THEN RAISE EXCEPTION 'prodat_recovery_intent_scope_required';END IF;
 SELECT * INTO o FROM gridex_received_sources.prodat_recovery_origins WHERE operation_id=op.id FOR UPDATE;
 SELECT * INTO r FROM public.outbound_requests WHERE id=coalesce(o.outbound_request_id,p_outbound_request_id) FOR SHARE;
 IF r.id IS NULL OR r.company_id IS DISTINCT FROM p_company_id OR r.customer_id IS DISTINCT FROM m.customer_id OR (r.payload->>'environment') IS DISTINCT FROM op.environment OR r.source_type IS DISTINCT FROM 'manual' OR r.source_id::text IS DISTINCT FROM i.id::text OR r.operation_id IS DISTINCT FROM op.id OR r.site_id IS DISTINCT FROM m.site_id OR r.metering_point_id IS DISTINCT FROM m.metering_point_id OR r.request_type IS DISTINCT FROM request_type THEN RAISE EXCEPTION 'prodat_recovery_owned_request_required';END IF;
 IF o.operation_id IS NOT NULL THEN
  IF o.company_id IS DISTINCT FROM p_company_id OR o.intent_id IS DISTINCT FROM i.id THEN RAISE EXCEPTION 'prodat_recovery_origin_conflict';END IF;
  RETURN jsonb_build_object('status','reserved','intentId',o.intent_id,'outboundRequestId',o.outbound_request_id,'messageId',(SELECT message_id FROM gridex_received_sources.prodat_recovery_messages WHERE operation_id=op.id));
 END IF;
 IF EXISTS(SELECT FROM gridex_received_sources.prodat_recovery_messages WHERE operation_id=op.id) THEN RAISE EXCEPTION 'prodat_recovery_legacy_bound_origin_held';END IF;
 INSERT INTO gridex_received_sources.prodat_recovery_origins(operation_id,company_id,intent_id,outbound_request_id,actor_user_id) VALUES(op.id,p_company_id,i.id,p_outbound_request_id,p_actor_user_id);
 RETURN jsonb_build_object('status','reserved','intentId',i.id,'outboundRequestId',p_outbound_request_id,'messageId',null);
END $$;
CREATE OR REPLACE FUNCTION public.ediel_reserve_production_contract_origin_v1(p_company_id uuid,p_event_id uuid,p_actor_user_id uuid,p_intent_id uuid,p_outbound_request_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE b jsonb;e gridex_received_sources.production_contract_events%rowtype;o gridex_received_sources.production_contract_origins%rowtype;i public.ediel_message_intents%rowtype;period gridex_received_sources.production_contract_periods%rowtype;r public.outbound_requests%rowtype;point public.metering_points%rowtype;
BEGIN
 SELECT * INTO e FROM gridex_received_sources.production_contract_events WHERE id=p_event_id AND company_id=p_company_id FOR UPDATE;
 PERFORM mp.id FROM public.metering_points mp WHERE mp.id=e.metering_point_id AND mp.company_id=e.company_id FOR UPDATE;
 b:=public.ediel_production_contract_source_v1(p_company_id,p_event_id,p_actor_user_id);IF b->>'status' IS DISTINCT FROM 'authorized' THEN RETURN b;END IF;
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=p_intent_id AND company_id=p_company_id FOR SHARE;
 IF i.id IS NULL OR i.environment IS DISTINCT FROM e.environment OR i.message_family IS DISTINCT FROM 'PRODAT' OR i.message_code IS DISTINCT FROM 'Z09' OR i.customer_id IS DISTINCT FROM e.customer_id OR i.metering_point_id IS DISTINCT FROM e.point_id OR i.operation_id IS DISTINCT FROM e.id
 THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_intent_scope_mismatch'));END IF;
 SELECT * INTO o FROM gridex_received_sources.production_contract_origins WHERE event_id=e.id FOR UPDATE;
 SELECT * INTO r FROM public.outbound_requests WHERE id=coalesce(o.outbound_request_id,p_outbound_request_id) AND company_id=e.company_id FOR SHARE;
 SELECT * INTO point FROM public.metering_points WHERE id=e.metering_point_id AND company_id=e.company_id FOR SHARE;
 IF r.id IS NULL OR point.id IS NULL OR r.customer_id IS DISTINCT FROM e.customer_id OR r.site_id IS DISTINCT FROM point.site_id OR r.metering_point_id IS DISTINCT FROM e.metering_point_id OR (r.payload->>'environment') IS DISTINCT FROM e.environment
 OR r.source_type IS DISTINCT FROM 'manual' OR r.source_id IS DISTINCT FROM i.id OR r.operation_id IS DISTINCT FROM e.id OR r.request_type IS DISTINCT FROM 'customer_masterdata' THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_owned_request_required'));END IF;
 IF o.event_id IS NOT NULL THEN IF o.intent_id IS DISTINCT FROM i.id THEN RAISE EXCEPTION 'production_contract_origin_conflict';END IF;RETURN jsonb_build_object('status','reserved','messageId',o.message_id,'outboundRequestId',o.outbound_request_id);END IF;
 IF e.event_kind='signed' THEN
 IF EXISTS(SELECT FROM gridex_received_sources.production_contract_periods p WHERE p.company_id=e.company_id AND p.environment=e.environment AND p.metering_point_id=e.metering_point_id AND (p.end_at IS NULL OR p.end_at>e.boundary_at)) THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_overlapping_owned_period'));END IF;
 INSERT INTO gridex_received_sources.production_contract_periods(start_event_id,company_id,environment,contract_id,customer_id,metering_point_id,start_at) VALUES(e.id,e.company_id,e.environment,e.contract_id,e.customer_id,e.metering_point_id,e.boundary_at);
 ELSE
 SELECT * INTO period FROM gridex_received_sources.production_contract_periods WHERE start_event_id=e.start_event_id AND company_id=e.company_id FOR UPDATE;
 IF NOT FOUND OR period.end_event_id IS NOT NULL THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_owned_open_period_required'));END IF;
 UPDATE gridex_received_sources.production_contract_periods SET end_at=e.boundary_at,end_event_id=e.id WHERE start_event_id=period.start_event_id;
 END IF;
 INSERT INTO gridex_received_sources.production_contract_origins(event_id,intent_id,company_id,actor_user_id,outbound_request_id) VALUES(e.id,i.id,e.company_id,p_actor_user_id,p_outbound_request_id);
 RETURN jsonb_build_object('status','reserved','messageId',null,'outboundRequestId',p_outbound_request_id);
END $$;


CREATE FUNCTION gridex_received_sources.production_contract_source_for_execution_v1(p_company_id uuid,p_event_id uuid,p_actor_user_id uuid,p_permission text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE e gridex_received_sources.production_contract_events%rowtype;c public.customer_contracts%rowtype;mp public.metering_points%rowtype;ids uuid[];start gridex_received_sources.production_contract_events%rowtype;
BEGIN
 IF (p_permission IN('communication.write','communication.send')) IS NOT TRUE THEN RAISE EXCEPTION 'production_contract_execution_phase_required';END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.id FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active')
 OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
 OR (CASE WHEN p_permission='communication.send' THEN coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.send'),false) OR coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'ediel.send'),false) ELSE coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.write'),false) END) IS NOT TRUE
 THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_execution_actor_unqualified'));END IF;
 SELECT * INTO e FROM gridex_received_sources.production_contract_events WHERE id=p_event_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND OR e.approved_at>now() OR EXISTS(SELECT FROM gridex_received_sources.production_contract_revocations r WHERE r.event_id=e.id)
 THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('authentic_production_contract_event_required'));END IF;
 PERFORM customer.id FROM public.customers customer WHERE customer.id=e.customer_id AND customer.company_id=e.company_id FOR SHARE;
 IF NOT FOUND THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_owned_customer_required'));END IF;
 SELECT * INTO c FROM public.customer_contracts WHERE id=e.contract_id AND company_id=e.company_id FOR SHARE;
 SELECT * INTO mp FROM public.metering_points WHERE id=e.metering_point_id AND company_id=e.company_id FOR SHARE;
 IF c.id IS NULL OR mp.id IS NULL OR c.customer_id IS DISTINCT FROM e.customer_id OR c.metering_point_id IS DISTINCT FROM e.metering_point_id
 OR mp.customer_id IS DISTINCT FROM e.customer_id OR mp.product_direction IS DISTINCT FROM 'production'
 OR mp.ediel_metering_point_id IS DISTINCT FROM e.point_id OR mp.grid_owner_ediel_id IS DISTINCT FROM e.legal_receiver_id OR mp.grid_area_code IS DISTINCT FROM e.grid_area_code
 OR c.signed_at IS NULL OR nullif(c.signed_version,'') IS NULL OR c.signed_version IS DISTINCT FROM e.contract_revision
 OR gridex_received_sources.production_contract_hash_v1(c) IS DISTINCT FROM e.protected_contract_hash
 THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_current_owner_scope_changed'));END IF;
 PERFORM p.id FROM public.tenant_ediel_profiles p WHERE p.company_id=e.company_id AND p.environment=e.environment ORDER BY p.id FOR SHARE;
 PERFORM i.id FROM public.tenant_actor_identifiers i WHERE i.company_id=e.company_id AND i.environment=e.environment ORDER BY i.id FOR SHARE;
 PERFORM r.id FROM public.tenant_actor_roles r WHERE r.company_id=e.company_id AND r.environment=e.environment ORDER BY r.id FOR SHARE;
 PERFORM i.id FROM public.platform_actor_identifiers i WHERE i.identifier_value=e.legal_receiver_id ORDER BY i.id FOR SHARE;
 PERFORM a.id FROM public.platform_market_actors a WHERE a.id=e.dso_actor_id FOR SHARE;
 PERFORM r.id FROM public.platform_actor_roles r WHERE r.actor_id=e.dso_actor_id ORDER BY r.id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.tenant_ediel_profiles p WHERE p.company_id=e.company_id AND p.environment=e.environment AND p.market='electricity' AND p.is_enabled AND p.valid_from<=now() AND (p.valid_to IS NULL OR now()<p.valid_to))
 OR NOT EXISTS(SELECT FROM public.tenant_actor_roles r WHERE r.company_id=e.company_id AND r.environment=e.environment AND r.actor_id=e.legal_actor_id AND r.role_code='electricity_supplier' AND r.valid_from<=now() AND (r.valid_to IS NULL OR now()<r.valid_to))
 OR (SELECT count(DISTINCT (i.actor_id,i.identifier_value)) FROM public.tenant_actor_identifiers i WHERE i.company_id=e.company_id AND i.environment=e.environment AND i.identifier_type='EdielId' AND i.valid_from<=now() AND (i.valid_to IS NULL OR now()<i.valid_to))<>1
 OR NOT EXISTS(SELECT FROM public.tenant_actor_identifiers i WHERE i.company_id=e.company_id AND i.environment=e.environment AND i.actor_id=e.legal_actor_id AND i.identifier_type='EdielId' AND i.identifier_value=e.legal_sender_id AND i.valid_from<=now() AND (i.valid_to IS NULL OR now()<i.valid_to))
 THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_current_legal_supplier_required'));END IF;
 SELECT array_agg(DISTINCT i.actor_id) INTO ids FROM public.platform_actor_identifiers i WHERE lower(i.identifier_type) IN ('edielid','ediel_id') AND i.identifier_value=e.legal_receiver_id AND i.is_verified AND (i.valid_from IS NULL OR i.valid_from<=current_date) AND (i.valid_to IS NULL OR current_date<=i.valid_to);
 IF coalesce(cardinality(ids),0)<>1 OR ids[1] IS DISTINCT FROM e.dso_actor_id
 OR NOT EXISTS(SELECT FROM public.platform_actor_identifiers i WHERE i.actor_id=e.dso_actor_id AND i.identifier_type='EdielId' AND i.identifier_value=e.legal_receiver_id AND i.is_verified AND (i.valid_from IS NULL OR i.valid_from<=current_date) AND (i.valid_to IS NULL OR current_date<=i.valid_to))
 OR NOT EXISTS(SELECT FROM public.platform_market_actors a WHERE a.id=e.dso_actor_id AND a.status='active' AND a.match_status='verified')
 OR NOT EXISTS(SELECT FROM public.platform_actor_roles r WHERE r.actor_id=e.dso_actor_id AND r.actor_role='grid_owner' AND r.is_active) THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_verified_dso_identity_required'));END IF;
 IF e.event_kind='ceased' THEN
 SELECT * INTO start FROM gridex_received_sources.production_contract_events WHERE id=e.start_event_id AND company_id=e.company_id FOR SHARE;
 IF start.id IS NULL OR start.event_kind IS DISTINCT FROM 'signed' OR start.environment IS DISTINCT FROM e.environment OR start.contract_id IS DISTINCT FROM e.contract_id OR start.metering_point_id IS DISTINCT FROM e.metering_point_id OR start.customer_id IS DISTINCT FROM e.customer_id OR start.boundary_at>=e.boundary_at OR EXISTS(SELECT FROM gridex_received_sources.production_contract_revocations r WHERE r.event_id=start.id)
 THEN RETURN jsonb_build_object('status','held','missing',jsonb_build_array('production_contract_original_start_required'));END IF;
 END IF;
 RETURN jsonb_build_object('status','authorized','companyId',e.company_id,'environment',e.environment,'eventId',e.id,'eventKind',e.event_kind,'sourceDigest',e.source_sha256,'sourceVersion',e.source_version,'sourceReference',e.source_reference,
 'legalActorId',e.legal_actor_id,'legalSenderId',e.legal_sender_id,'legalReceiverId',e.legal_receiver_id,'contractId',e.contract_id,'customerId',e.customer_id,'meteringPointId',e.metering_point_id,'pointId',e.point_id,'identityAgency',e.identity_agency,'gridArea',e.grid_area_code,
 'contractReference',e.contract_reference,'contractRevision',e.contract_revision,'boundaryAt',e.boundary_at);
END $$;
REVOKE ALL ON FUNCTION gridex_received_sources.production_contract_source_for_execution_v1(uuid,uuid,uuid,text) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.ediel_production_contract_source_v1(p_company_id uuid,p_event_id uuid,p_actor_user_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN RETURN gridex_received_sources.production_contract_source_for_execution_v1(p_company_id,p_event_id,p_actor_user_id,'communication.write');END $$;
CREATE OR REPLACE FUNCTION public.ediel_production_contract_message_basis_v1(p_company_id uuid,p_message_id uuid,p_actor_user_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE o gridex_received_sources.production_contract_origins%rowtype;m public.ediel_messages%rowtype;b jsonb;r public.outbound_requests%rowtype;e gridex_received_sources.production_contract_events%rowtype;
BEGIN
 SELECT * INTO o FROM gridex_received_sources.production_contract_origins WHERE company_id=p_company_id AND message_id=p_message_id;
 IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR SHARE;
 IF m.intent_id IS DISTINCT FROM o.intent_id OR m.source_operation_id IS DISTINCT FROM o.event_id::text OR o.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'production_contract_bound_payload_changed';END IF;
 b:=gridex_received_sources.production_contract_source_for_execution_v1(p_company_id,o.event_id,p_actor_user_id,CASE WHEN public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.send') IS TRUE OR public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'ediel.send') IS TRUE THEN 'communication.send' ELSE 'communication.write' END);
 IF b->>'status' IS DISTINCT FROM 'authorized' THEN RETURN b;END IF;
 SELECT * INTO e FROM gridex_received_sources.production_contract_events WHERE id=o.event_id AND company_id=o.company_id;
 SELECT * INTO r FROM public.outbound_requests WHERE id=o.outbound_request_id AND company_id=o.company_id FOR SHARE;
 IF e.id IS NULL OR r.id IS NULL OR m.outbound_request_id IS DISTINCT FROM o.outbound_request_id OR (r.payload->>'environment') IS DISTINCT FROM e.environment
 OR r.source_type IS DISTINCT FROM 'manual' OR r.source_id IS DISTINCT FROM o.intent_id OR r.operation_id IS DISTINCT FROM e.id OR r.request_type IS DISTINCT FROM 'customer_masterdata'
 OR r.customer_id IS DISTINCT FROM m.customer_id OR r.site_id IS DISTINCT FROM m.site_id OR r.metering_point_id IS DISTINCT FROM m.metering_point_id THEN RAISE EXCEPTION 'production_contract_current_request_required';END IF;
 RETURN jsonb_build_object('basis',b,'intentId',o.intent_id);
END $$;
CREATE FUNCTION gridex_received_sources.require_production_contract_source_current_v1(p_company_id uuid,p_message_id uuid,p_actor_user_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE m public.ediel_messages%rowtype;o gridex_received_sources.production_contract_origins%rowtype;e gridex_received_sources.production_contract_events%rowtype;i public.ediel_message_intents%rowtype;r public.outbound_requests%rowtype;point public.metering_points%rowtype;b jsonb;w jsonb;q jsonb;period gridex_received_sources.production_contract_periods%rowtype;op gridex_received_sources.prodat_recovery_operations%rowtype;original public.ediel_messages%rowtype;original_wire jsonb;actual_dates jsonb;original_dates jsonb;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR SHARE;
 IF m.id IS NULL THEN RAISE EXCEPTION 'production_contract_current_message_required';END IF;
 IF m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z09' THEN RETURN;END IF;
 SELECT * INTO o FROM gridex_received_sources.production_contract_origins WHERE company_id=p_company_id AND message_id=m.id;
 w:=gridex_received_sources.prodat_recovery_wire_v1(m.raw_payload);
 IF o.event_id IS NULL THEN
  IF NOT EXISTS(SELECT FROM jsonb_array_elements(coalesce(w->'objects','[]')) own WHERE own->>'reason'='Z70') THEN RETURN;END IF;
  SELECT operation.* INTO op FROM gridex_received_sources.prodat_recovery_messages link JOIN gridex_received_sources.prodat_recovery_operations operation ON operation.id=link.operation_id WHERE link.message_id=m.id AND operation.company_id=p_company_id;
  IF op.id IS NOT NULL THEN
   PERFORM public.ediel_require_prodat_recovery_current_v1(p_company_id,m.id);
   SELECT * INTO original FROM public.ediel_messages WHERE id=op.original_message_id AND company_id=p_company_id FOR SHARE;
   original_wire:=gridex_received_sources.prodat_recovery_wire_v1(original.raw_payload);
   IF original.id IS NULL OR m.original_message_id IS DISTINCT FROM original.id OR m.source_operation_id IS DISTINCT FROM op.id::text OR (op.kind IN('contrl_correction','aperak_correction')) IS NOT TRUE OR op.corrected_raw_payload IS DISTINCT FROM m.raw_payload OR op.corrected_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
    OR original_wire->>'legalSender' IS DISTINCT FROM w->>'legalSender' OR original_wire->>'legalReceiver' IS DISTINCT FROM w->>'legalReceiver' OR jsonb_array_length(w->'objects') IS DISTINCT FROM 1 OR (w#>'{objects,0}'-'li'-'line') IS DISTINCT FROM (original_wire#>'{objects,0}'-'li'-'line') THEN RAISE EXCEPTION 'production_contract_recovery_source_scope_required';END IF;
   SELECT jsonb_agg(token->'elements'->1 ORDER BY token->>'index') INTO actual_dates FROM jsonb_array_elements(gridex_received_sources.closure_wire_tokens_v2(m.raw_payload)) token WHERE token->>'tag'='DTM' AND token#>>'{elements,1,0}' IN('92','93','157');
   SELECT jsonb_agg(token->'elements'->1 ORDER BY token->>'index') INTO original_dates FROM jsonb_array_elements(gridex_received_sources.closure_wire_tokens_v2(original.raw_payload)) token WHERE token->>'tag'='DTM' AND token#>>'{elements,1,0}' IN('92','93','157');
   IF actual_dates IS DISTINCT FROM original_dates THEN RAISE EXCEPTION 'production_contract_recovery_boundary_scope_required';END IF;
   PERFORM gridex_received_sources.require_production_contract_source_current_v1(p_company_id,original.id,p_actor_user_id);
   PERFORM gridex_ediel_transport.require_message_intent_v1(m);
   RETURN;
  END IF;
  -- A test environment alone cannot originate a production-contract event.
  IF m.environment IS DISTINCT FROM 'test' THEN RAISE EXCEPTION 'production_contract_current_origin_required';END IF;
  IF EXISTS(SELECT FROM gridex_negative_fixtures.positive_consumptions c WHERE c.company_id=p_company_id AND c.message_id=m.id) AND EXISTS(SELECT FROM gridex_negative_fixtures.negative_prepared_consumptions c WHERE c.company_id=p_company_id AND c.message_id=m.id) THEN RAISE EXCEPTION 'production_contract_fixture_source_ambiguous';END IF;
  IF EXISTS(SELECT FROM gridex_negative_fixtures.positive_consumptions c WHERE c.company_id=p_company_id AND c.message_id=m.id) THEN
   q:=gridex_negative_fixtures.require_positive_message_v1(p_company_id,m.id,'Z09');
   IF q->>'kind' IS DISTINCT FROM 'source_qualified_positive_fixture' OR q->>'expectedOutcome' IS DISTINCT FROM 'positive' OR q->'expectedDiagnosticCodes' IS DISTINCT FROM '[]'::jsonb THEN RAISE EXCEPTION 'production_contract_fixture_scope_required';END IF;
  ELSIF EXISTS(SELECT FROM gridex_negative_fixtures.negative_prepared_consumptions c WHERE c.company_id=p_company_id AND c.message_id=m.id) THEN
   q:=gridex_negative_fixtures.require_negative_message_v1(p_company_id,m.id,'Z09');
   IF q->>'kind' IS DISTINCT FROM 'source_qualified_negative_fixture' OR q->>'expectedOutcome' IS DISTINCT FROM 'negative' OR jsonb_typeof(q->'expectedDiagnosticCodes') IS DISTINCT FROM 'array' OR jsonb_array_length(q->'expectedDiagnosticCodes') NOT BETWEEN 1 AND 256 THEN RAISE EXCEPTION 'production_contract_fixture_scope_required';END IF;
  ELSE RAISE EXCEPTION 'production_contract_current_origin_required';END IF;
  IF q->>'companyId' IS DISTINCT FROM p_company_id::text OR q->>'roleCode' IS DISTINCT FROM 'supplier' OR q->>'authorizesBusinessEffect' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'production_contract_fixture_supplier_required';END IF;
  RETURN;
 END IF;
 b:=gridex_received_sources.production_contract_source_for_execution_v1(p_company_id,o.event_id,p_actor_user_id,'communication.send');
 IF b->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION 'production_contract_current_source_required';END IF;
 SELECT * INTO STRICT e FROM gridex_received_sources.production_contract_events WHERE id=o.event_id AND company_id=p_company_id;
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=o.intent_id AND company_id=p_company_id FOR SHARE;
 SELECT * INTO r FROM public.outbound_requests WHERE id=o.outbound_request_id AND company_id=p_company_id FOR SHARE;
 SELECT * INTO point FROM public.metering_points WHERE id=e.metering_point_id AND company_id=p_company_id FOR SHARE;
 SELECT * INTO period FROM gridex_received_sources.production_contract_periods WHERE start_event_id=CASE WHEN e.event_kind='signed' THEN e.id ELSE e.start_event_id END AND company_id=p_company_id FOR SHARE;
 IF i.id IS NULL OR r.id IS NULL OR point.id IS NULL OR period.start_event_id IS NULL OR w IS NULL OR m.intent_id IS DISTINCT FROM o.intent_id OR m.outbound_request_id IS DISTINCT FROM o.outbound_request_id OR m.source_operation_id IS DISTINCT FROM e.id::text
 OR m.environment IS DISTINCT FROM e.environment OR m.customer_id IS DISTINCT FROM e.customer_id OR m.metering_point_id IS DISTINCT FROM e.metering_point_id OR m.site_id IS DISTINCT FROM point.site_id OR m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS DISTINCT FROM o.payload_hash OR o.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
 OR i.operation_id IS DISTINCT FROM e.id OR i.ediel_message_id IS DISTINCT FROM m.id OR i.outbound_request_id IS DISTINCT FROM r.id OR i.validation_status IS DISTINCT FROM 'validated'
 OR (r.payload->>'environment') IS DISTINCT FROM e.environment OR r.source_type IS DISTINCT FROM 'manual' OR r.source_id IS DISTINCT FROM i.id OR r.operation_id IS DISTINCT FROM e.id OR r.request_type IS DISTINCT FROM 'customer_masterdata' OR r.customer_id IS DISTINCT FROM e.customer_id OR r.site_id IS DISTINCT FROM m.site_id OR r.metering_point_id IS DISTINCT FROM e.metering_point_id
 OR period.environment IS DISTINCT FROM e.environment OR period.contract_id IS DISTINCT FROM e.contract_id OR period.customer_id IS DISTINCT FROM e.customer_id OR period.metering_point_id IS DISTINCT FROM e.metering_point_id OR (e.event_kind='signed' AND (period.start_at IS DISTINCT FROM e.boundary_at OR period.end_at IS NOT NULL)) OR (e.event_kind='ceased' AND (period.end_event_id IS DISTINCT FROM e.id OR period.end_at IS DISTINCT FROM e.boundary_at))
 OR w->>'code' IS DISTINCT FROM 'Z09' OR w->>'legalSender' IS DISTINCT FROM e.legal_sender_id OR w->>'legalReceiver' IS DISTINCT FROM e.legal_receiver_id OR jsonb_array_length(w->'objects') IS DISTINCT FROM 1 OR w#>>'{objects,0,reason}' IS DISTINCT FROM 'Z70' OR w#>>'{objects,0,point}' IS DISTINCT FROM e.point_id OR w#>>'{objects,0,identityAgency}' IS DISTINCT FROM e.identity_agency
 THEN RAISE EXCEPTION 'production_contract_current_origin_required';END IF;
 PERFORM gridex_ediel_transport.require_message_intent_v1(m);
END $$;
REVOKE ALL ON FUNCTION gridex_received_sources.require_production_contract_source_current_v1(uuid,uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;
ALTER FUNCTION gridex_ediel_transport.mutate_v1(jsonb) RENAME TO mutate_before_production_contract_source_v1;
CREATE FUNCTION gridex_ediel_transport.mutate_v1(input jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE result jsonb;
BEGIN
 result:=gridex_ediel_transport.mutate_before_production_contract_source_v1(input);
 IF (input->>'action' IN('prepare','enter')) IS NOT TRUE OR result->>'proceed' IS DISTINCT FROM 'true' THEN RETURN result;END IF;
 PERFORM gridex_received_sources.require_production_contract_source_current_v1((input->>'companyId')::uuid,(input->>'messageId')::uuid,(input->>'actorUserId')::uuid);
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION gridex_ediel_transport.mutate_v1(jsonb),gridex_ediel_transport.mutate_before_production_contract_source_v1(jsonb) FROM PUBLIC,anon,authenticated,service_role;
-- Point observations use the same owner, not a second status/date engine.
-- PostgreSQL timestamps are discrete microsecond values: at < end is exactly
-- equivalent to next_representable_timestamp(at) <= end. The successor is a
-- membership probe, not a market deadline, guessed minute or approved period.
CREATE FUNCTION gridex_received_sources.supply_period_source_at_v1(p_company_id uuid,p_period_id uuid,p_at timestamptz) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE basis jsonb;
BEGIN
 IF p_at IS NULL OR NOT isfinite(p_at) THEN RETURN NULL;END IF;
 basis:=gridex_received_sources.supply_period_source_basis_v1(p_company_id,p_period_id,p_at,p_at+interval '1 microsecond');
 IF basis IS NULL OR basis->>'qualified' IS DISTINCT FROM 'true' OR (basis->>'marketStartAt')::timestamptz IS NULL OR (basis->>'marketStartAt')::timestamptz>p_at OR ((basis->>'marketEndAt') IS NOT NULL AND p_at>=(basis->>'marketEndAt')::timestamptz) THEN RETURN NULL;END IF;
 RETURN basis||jsonb_build_object('basisKind','exact_source_point','at',p_at);
EXCEPTION WHEN datetime_field_overflow THEN RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION gridex_received_sources.supply_period_source_at_v1(uuid,uuid,timestamptz) FROM PUBLIC,anon,authenticated,service_role;
COMMIT;

20260930232100_ediel_requested_change_so.body:
-- Internal custody/review owner. No issuer/representation keys or permissions
-- are granted/seeded; archive bytes and reviewer decisions never mint an issuer.
BEGIN;
INSERT INTO public.permissions(key,name,category,description,is_active)
 SELECT 'ediel.source.review','Review own Ediel source artifacts','ediel','Separate, company-scoped review of actual archived source artifacts; does not establish issuer authority.',true
 WHERE NOT EXISTS(SELECT FROM public.permissions WHERE key='ediel.source.review');
CREATE TABLE gridex_requested_changes.artifacts(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),environment text NOT NULL,
 supply_period_id uuid NOT NULL REFERENCES public.customer_supply_periods(id),contract_id uuid NOT NULL REFERENCES public.customer_contracts(id),customer_id uuid NOT NULL,metering_point_id uuid NOT NULL,legal_actor_id uuid NOT NULL,legal_sender_id text NOT NULL,legal_receiver_id text NOT NULL,point_id text NOT NULL,identity_agency text NOT NULL,grid_area_code text NOT NULL,brp_ediel_id text NOT NULL,supply_source_message_id uuid NOT NULL,supply_state_version bigint NOT NULL,
 protected_contract_hash text NOT NULL,customer_snapshot_hash text NOT NULL,kind text NOT NULL CHECK(kind IN('death','quarter_contract','method_contract')),effective_at timestamptz NOT NULL CHECK(isfinite(effective_at) AND extract(second FROM effective_at)=0),
 source_bytes bytea NOT NULL CHECK(octet_length(source_bytes) BETWEEN 1 AND 8388608),source_hash text NOT NULL CHECK(source_hash~'^[a-f0-9]{64}$'),mime_type text NOT NULL CHECK(mime_type IN('application/pdf','text/plain','application/json')),source_reference text NOT NULL,source_version text NOT NULL,
 claims jsonb NOT NULL,claims_hash text NOT NULL,issuer_receipt jsonb,submitted_by uuid NOT NULL REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(company_id,environment,source_hash,claims_hash));
CREATE TABLE gridex_requested_changes.reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),artifact_id uuid NOT NULL REFERENCES gridex_requested_changes.artifacts(id),company_id uuid NOT NULL,reviewer_user_id uuid NOT NULL REFERENCES auth.users(id),decision text NOT NULL CHECK(decision IN('approved','held','rejected')),reason text NOT NULL,clause jsonb,missing jsonb NOT NULL DEFAULT '[]',reviewed_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE gridex_requested_changes.issuer_keys(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,environment text NOT NULL,issuer_code text NOT NULL,legal_issuer_reference text NOT NULL,legal_authority_source_hash text NOT NULL CHECK(legal_authority_source_hash~'^[a-f0-9]{64}$'),receipt_signing_key bytea NOT NULL CHECK(octet_length(receipt_signing_key)>=32),valid_from timestamptz NOT NULL,valid_to timestamptz NOT NULL CHECK(valid_to>valid_from),UNIQUE(company_id,environment,issuer_code,valid_from));
CREATE TABLE gridex_requested_changes.issuer_representations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,environment text NOT NULL,issuer_key_id uuid NOT NULL REFERENCES gridex_requested_changes.issuer_keys(id),legal_actor_id uuid NOT NULL,permitted_kind text NOT NULL CHECK(permitted_kind='death'),legal_representation_reference text NOT NULL,legal_authority_source_hash text NOT NULL CHECK(legal_authority_source_hash~'^[a-f0-9]{64}$'),valid_from timestamptz NOT NULL,valid_to timestamptz NOT NULL CHECK(valid_to>valid_from));
CREATE TABLE gridex_requested_changes.issuer_revocations(target_kind text NOT NULL CHECK(target_kind IN('key','representation')),target_id uuid NOT NULL,source_reference text NOT NULL,source_hash text NOT NULL CHECK(source_hash~'^[a-f0-9]{64}$'),revoked_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(target_kind,target_id));
CREATE TABLE gridex_requested_changes.review_origins(event_id uuid PRIMARY KEY REFERENCES gridex_requested_changes.events(id),artifact_id uuid NOT NULL UNIQUE REFERENCES gridex_requested_changes.artifacts(id),review_id uuid NOT NULL UNIQUE REFERENCES gridex_requested_changes.reviews(id),company_id uuid NOT NULL,contract_document_id uuid REFERENCES public.customer_contract_documents(id),contract_document_binding jsonb,signature_hash text,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
DO $$DECLARE t text;BEGIN FOR t IN SELECT unnest(ARRAY['artifacts','reviews','issuer_keys','issuer_representations','issuer_revocations','review_origins']) LOOP
 EXECUTE format('ALTER TABLE gridex_requested_changes.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE gridex_requested_changes.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON gridex_requested_changes.%I FROM PUBLIC,anon,authenticated,service_role',t);
 EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON gridex_requested_changes.%I FOR EACH ROW EXECUTE FUNCTION gridex_received_sources.permission_transition_immutable_v1()',t||'_immutable',t);EXECUTE format('CREATE TRIGGER %I BEFORE TRUNCATE ON gridex_requested_changes.%I FOR EACH STATEMENT EXECUTE FUNCTION gridex_received_sources.permission_transition_immutable_v1()',t||'_no_truncate',t);
 END LOOP;END$$;
CREATE FUNCTION gridex_requested_changes.scoped_permission_v1(c uuid,actor uuid,wanted text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN
 PERFORM p.id FROM public.permissions p WHERE p.key=wanted ORDER BY p.id FOR SHARE;
 PERFORM p.id FROM public.user_permissions p WHERE p.user_id=actor AND p.company_id=c ORDER BY p.id FOR SHARE;
 PERFORM p.id FROM public.user_roles p WHERE p.user_id=actor AND p.company_id=c ORDER BY p.id FOR SHARE;
 PERFORM p.id FROM public.roles p WHERE EXISTS(SELECT FROM public.user_roles u WHERE u.user_id=actor AND u.company_id=c AND u.role_id=p.id) ORDER BY p.id FOR SHARE;
 PERFORM p.id FROM public.role_permissions p WHERE EXISTS(SELECT FROM public.user_roles u WHERE u.user_id=actor AND u.company_id=c AND u.role_id=p.role_id) ORDER BY p.id FOR SHARE;
 RETURN EXISTS(SELECT FROM public.user_permissions u JOIN public.permissions p ON p.id=u.permission_id OR u.permission_id IS NULL AND p.key=u.permission_key WHERE u.user_id=actor AND u.company_id=c AND u.is_active AND u.status='active' AND u.effect='allow' AND p.is_active AND p.key=wanted)
 OR EXISTS(SELECT FROM public.user_roles u JOIN public.roles r ON r.id=u.role_id JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id OR rp.permission_id IS NULL AND p.key=rp.permission_key WHERE u.user_id=actor AND u.company_id=c AND u.is_active AND u.status='active' AND r.is_active AND rp.effect='allow' AND p.is_active AND p.key=wanted);
END$$;
CREATE FUNCTION gridex_requested_changes.actor_v1(c uuid,actor uuid,mode text,kind text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN
 PERFORM id FROM auth.users WHERE id=actor FOR SHARE;PERFORM id FROM public.user_profiles WHERE id=actor FOR SHARE;PERFORM user_id FROM public.company_memberships WHERE company_id=c AND user_id=actor FOR SHARE;
 RETURN actor IS NOT NULL AND mode IN('archive','read','review') AND EXISTS(SELECT FROM public.user_profiles WHERE id=actor AND user_status='active') AND EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status='active' AND is_active AND accepted_at IS NOT NULL)
 AND EXISTS(SELECT FROM auth.users WHERE id=actor AND deleted_at IS NULL AND (banned_until IS NULL OR banned_until<=now()))
 AND gridex_requested_changes.scoped_permission_v1(c,actor,CASE mode WHEN 'read' THEN 'communication.read' ELSE 'communication.write' END) IS TRUE
 AND gridex_requested_changes.scoped_permission_v1(c,actor,CASE mode WHEN 'read' THEN 'customers.read' ELSE 'customers.write' END) IS TRUE
 AND (kind='death' OR gridex_requested_changes.scoped_permission_v1(c,actor,CASE mode WHEN 'read' THEN 'contracts.read' ELSE 'contracts.write' END) IS TRUE)
 AND (mode<>'review' OR gridex_requested_changes.scoped_permission_v1(c,actor,'ediel.source.review') IS TRUE);
END$$;
CREATE FUNCTION gridex_requested_changes.issuer_revocation_lock_v1() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN
 IF NEW.target_kind='key' THEN PERFORM id FROM gridex_requested_changes.issuer_keys WHERE id=NEW.target_id FOR UPDATE;ELSE PERFORM id FROM gridex_requested_changes.issuer_representations WHERE id=NEW.target_id FOR UPDATE;END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'requested_change_issuer_revocation_target_required';END IF;RETURN NEW;END$$;
CREATE TRIGGER requested_change_issuer_revocation_lock BEFORE INSERT ON gridex_requested_changes.issuer_revocations FOR EACH ROW EXECUTE FUNCTION gridex_requested_changes.issuer_revocation_lock_v1();
-- HMAC-SHA256 uses only core immutable SHA256/byte operations. No extension,
-- secret export, client verification flag or caller-supplied digest is needed.
CREATE FUNCTION gridex_requested_changes.receipt_hmac_sha256_v1(payload bytea,key bytea) RETURNS bytea LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE block bytea;inner_pad bytea:=decode(repeat('00',64),'hex');outer_pad bytea:=decode(repeat('00',64),'hex');n int;
BEGIN block:=CASE WHEN octet_length(key)>64 THEN sha256(key) ELSE key END;block:=block||decode(repeat('00',64-octet_length(block)),'hex');
 FOR n IN 0..63 LOOP inner_pad:=set_byte(inner_pad,n,get_byte(block,n)#54);outer_pad:=set_byte(outer_pad,n,get_byte(block,n)#92);END LOOP;
 RETURN sha256(outer_pad||sha256(inner_pad||payload));END$$;
CREATE FUNCTION gridex_requested_changes.receipt_current_v1(a gridex_requested_changes.artifacts) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE k gridex_requested_changes.issuer_keys%rowtype;g gridex_requested_changes.issuer_representations%rowtype;p jsonb;raw bytea;r jsonb:=a.issuer_receipt;issued timestamptz;expires timestamptz;
BEGIN
 IF a.kind<>'death' OR r IS NULL OR jsonb_typeof(r)<>'object' OR coalesce(r->>'signatureHex','')!~'^[a-f0-9]{64}$' OR length(coalesce(r->>'payloadBase64','')) NOT BETWEEN 1 AND 32768 THEN RETURN false;END IF;
 SELECT * INTO k FROM gridex_requested_changes.issuer_keys WHERE id=(r->>'keyId')::uuid AND company_id=a.company_id AND environment=a.environment FOR SHARE;
 SELECT * INTO g FROM gridex_requested_changes.issuer_representations WHERE id=(r->>'representationId')::uuid AND issuer_key_id=k.id AND company_id=a.company_id AND environment=a.environment AND legal_actor_id=a.legal_actor_id AND permitted_kind='death' FOR SHARE;
 IF k.id IS NULL OR g.id IS NULL OR now()<k.valid_from OR now()>=k.valid_to OR now()<g.valid_from OR now()>=g.valid_to OR EXISTS(SELECT FROM gridex_requested_changes.issuer_revocations WHERE target_kind='key' AND target_id=k.id OR target_kind='representation' AND target_id=g.id) THEN RETURN false;END IF;
 raw:=decode(r->>'payloadBase64','base64');IF sha256(gridex_requested_changes.receipt_hmac_sha256_v1(raw,k.receipt_signing_key)) IS DISTINCT FROM sha256(decode(r->>'signatureHex','hex')) THEN RETURN false;END IF;
 p:=convert_from(raw,'UTF8')::jsonb;issued:=(p->>'issuedAt')::timestamptz;expires:=(p->>'expiresAt')::timestamptz;
 RETURN p->>'format'='ediel_requested_change_issuer_receipt_v1' AND p->>'issuerCode'=k.issuer_code AND p->>'receiptId'<>'' AND p->>'companyId'=a.company_id::text AND p->>'environment'=a.environment AND p->>'legalActorId'=a.legal_actor_id::text AND p->>'customerId'=a.customer_id::text AND p->>'meteringPointId'=a.metering_point_id::text AND p->>'kind'='death' AND (p->>'effectiveAt')::timestamptz=a.effective_at AND p->>'sourceHash'=a.source_hash AND p->>'sourceReference'=a.source_reference AND p->>'sourceVersion'=a.source_version AND p->'customerIdentity'=a.claims->'customerIdentity' AND isfinite(issued) AND isfinite(expires) AND issued<=now() AND expires>now() AND issued>=greatest(k.valid_from,g.valid_from) AND expires<=least(k.valid_to,g.valid_to);
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR invalid_datetime_format OR datetime_field_overflow OR character_not_in_repertoire THEN RETURN false;
END$$;
CREATE FUNCTION public.ediel_archive_requested_change_source_v1(p_company_id uuid,p_actor_user_id uuid,p_submission jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c public.customer_contracts%rowtype;u public.customers%rowtype;mp public.metering_points%rowtype;sp public.customer_supply_periods%rowtype;m public.ediel_messages%rowtype;supply jsonb;bytes bytea;hash text;claims jsonb;ch text;kind text;at timestamptz;sender text;brp text;tokens jsonb;a gridex_requested_changes.artifacts%rowtype;missing jsonb:='["separate_source_review_required"]';
BEGIN
 kind:=p_submission->>'kind';IF (kind IN('death','quarter_contract','method_contract')) IS NOT TRUE OR gridex_requested_changes.actor_v1(p_company_id,p_actor_user_id,'archive',kind) IS NOT TRUE THEN RAISE EXCEPTION 'requested_change_archive_actor_forbidden' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(p_submission)<>'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_submission) k WHERE k NOT IN('supplyPeriodId','contractId','kind','effectiveAt','source','customerIdentity','invoiceeProfile','issuerReceipt')) OR jsonb_typeof(p_submission->'source') IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_submission->'source') k WHERE k NOT IN('bytesBase64','mimeType','reference','version')) THEN RAISE EXCEPTION 'requested_change_archive_shape_required';END IF;
 IF length(coalesce(p_submission#>>'{source,bytesBase64}',''))>11184812 THEN RAISE EXCEPTION 'requested_change_source_bytes_limit';END IF;bytes:=decode(p_submission#>>'{source,bytesBase64}','base64');hash:=encode(sha256(bytes),'hex');at:=(p_submission->>'effectiveAt')::timestamptz;
 IF octet_length(bytes) NOT BETWEEN 1 AND 8388608 OR (p_submission#>>'{source,mimeType}' IN('application/pdf','text/plain','application/json')) IS NOT TRUE OR nullif(p_submission#>>'{source,reference}','') IS NULL OR length(p_submission#>>'{source,reference}')>2000 OR nullif(p_submission#>>'{source,version}','') IS NULL OR length(p_submission#>>'{source,version}')>200 OR NOT isfinite(at) OR extract(second FROM at)<>0 OR p_submission#>>'{source,mimeType}'='application/pdf' AND substring(bytes,1,5)<>decode('255044462d','hex') THEN RAISE EXCEPTION 'requested_change_source_bytes_or_minute_invalid';END IF;
 SELECT * INTO sp FROM public.customer_supply_periods WHERE id=(p_submission->>'supplyPeriodId')::uuid AND company_id=p_company_id FOR SHARE;
 SELECT * INTO c FROM public.customer_contracts WHERE id=(p_submission->>'contractId')::uuid AND company_id=p_company_id FOR SHARE;
 SELECT * INTO u FROM public.customers WHERE id=sp.customer_id AND company_id=p_company_id FOR SHARE;SELECT * INTO mp FROM public.metering_points WHERE id=sp.metering_point_id AND company_id=p_company_id FOR SHARE;
 supply:=gridex_received_sources.supply_period_source_basis_v1(p_company_id,sp.id,at,at+interval '1 minute');
 IF sp.id IS NULL OR c.id IS NULL OR u.id IS NULL OR mp.id IS NULL OR c.customer_id IS DISTINCT FROM sp.customer_id OR c.metering_point_id IS DISTINCT FROM sp.metering_point_id OR supply->>'qualified' IS DISTINCT FROM 'true' OR supply->>'customerId' IS DISTINCT FROM u.id::text OR supply->>'meteringPointId' IS DISTINCT FROM mp.id::text THEN RAISE EXCEPTION 'requested_change_archive_owned_current_supply_contract_required';END IF;
 SELECT identifier_value INTO sender FROM public.tenant_actor_identifiers WHERE company_id=p_company_id AND environment=supply->>'environment' AND actor_id=(supply->>'legalActorId')::uuid AND identifier_type='EdielId' AND valid_from<=now() AND (valid_to IS NULL OR valid_to>now()) ORDER BY id LIMIT 1 FOR SHARE;
 -- The source owner may omit environment in older approved supply snapshots;
 -- it is always taken from the actual initial received original, never input.
 SELECT * INTO m FROM public.ediel_messages WHERE company_id=p_company_id AND id=(supply->>'initialSourceMessageId')::uuid FOR SHARE;
 IF sender IS NULL THEN SELECT identifier_value INTO sender FROM public.tenant_actor_identifiers WHERE company_id=p_company_id AND environment=m.environment AND actor_id=(supply->>'legalActorId')::uuid AND identifier_type='EdielId' AND valid_from<=now() AND (valid_to IS NULL OR valid_to>now()) ORDER BY id LIMIT 1 FOR SHARE;END IF;
 tokens:=gridex_received_sources.closure_wire_tokens_v2(m.raw_payload);SELECT t#>>'{elements,2,0}' INTO brp FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='Z02' AND t#>>'{elements,2,1}'='160' AND t#>>'{elements,2,2}'='SVK';
 IF sender IS NULL OR brp IS NULL OR (SELECT count(*) FROM jsonb_array_elements(supply->'sourceObjects') x WHERE x->>'point'=mp.ediel_metering_point_id AND x->>'identityAgency' IN('9','89'))<>1 THEN RAISE EXCEPTION 'requested_change_archive_physical_original_identity_required';END IF;
 claims:=jsonb_build_object('kind',kind,'effectiveAt',at,'customerIdentity',p_submission->'customerIdentity','invoiceeProfile',p_submission->'invoiceeProfile');ch:=encode(sha256(convert_to(claims::text,'UTF8')),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended('requested_change_archive:'||p_company_id::text||hash||ch,0));
 SELECT * INTO a FROM gridex_requested_changes.artifacts WHERE company_id=p_company_id AND environment=m.environment AND source_hash=hash AND claims_hash=ch FOR SHARE;
 IF FOUND THEN IF a.supply_period_id IS DISTINCT FROM sp.id OR a.contract_id IS DISTINCT FROM c.id OR a.source_reference IS DISTINCT FROM p_submission#>>'{source,reference}' OR a.source_version IS DISTINCT FROM p_submission#>>'{source,version}' OR a.issuer_receipt IS DISTINCT FROM p_submission->'issuerReceipt' THEN RAISE EXCEPTION 'requested_change_archive_original_conflict';END IF;
 ELSE INSERT INTO gridex_requested_changes.artifacts(company_id,environment,supply_period_id,contract_id,customer_id,metering_point_id,legal_actor_id,legal_sender_id,legal_receiver_id,point_id,identity_agency,grid_area_code,brp_ediel_id,supply_source_message_id,supply_state_version,protected_contract_hash,customer_snapshot_hash,kind,effective_at,source_bytes,source_hash,mime_type,source_reference,source_version,claims,claims_hash,issuer_receipt,submitted_by)
 VALUES(p_company_id,m.environment,sp.id,c.id,u.id,mp.id,(supply->>'legalActorId')::uuid,sender,supply->>'dsoEdielId',mp.ediel_metering_point_id,(SELECT x->>'identityAgency' FROM jsonb_array_elements(supply->'sourceObjects') x WHERE x->>'point'=mp.ediel_metering_point_id),mp.grid_area_code,brp,(supply->>'sourceMessageId')::uuid,(supply->>'marketStateVersion')::bigint,gridex_received_sources.production_contract_hash_v1(c),encode(sha256(convert_to((to_jsonb(u)-'updated_at')::text,'UTF8')),'hex'),kind,at,bytes,hash,p_submission#>>'{source,mimeType}',p_submission#>>'{source,reference}',p_submission#>>'{source,version}',claims,ch,p_submission->'issuerReceipt',p_actor_user_id) RETURNING * INTO a;END IF;
 IF kind='death' AND gridex_requested_changes.receipt_current_v1(a) IS NOT TRUE THEN missing:=missing||'"authentic_current_issuer_and_representation_receipt"'::jsonb;END IF;
 RETURN jsonb_build_object('status','archived','artifactId',a.id,'sourceHash',a.source_hash,'claimsHash',a.claims_hash,'missing',missing);
END$$;
CREATE FUNCTION public.ediel_read_requested_change_artifact_v1(p_company_id uuid,p_artifact_id uuid,p_actor_user_id uuid,p_include_bytes boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE a gridex_requested_changes.artifacts%rowtype;r gridex_requested_changes.reviews%rowtype;o gridex_requested_changes.review_origins%rowtype;result jsonb;b jsonb;
BEGIN SELECT * INTO STRICT a FROM gridex_requested_changes.artifacts WHERE id=p_artifact_id AND company_id=p_company_id FOR SHARE;
 IF gridex_requested_changes.actor_v1(p_company_id,p_actor_user_id,'read',a.kind) IS NOT TRUE THEN RAISE EXCEPTION 'requested_change_artifact_read_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO r FROM gridex_requested_changes.reviews WHERE artifact_id=a.id ORDER BY reviewed_at DESC,id DESC LIMIT 1;SELECT * INTO o FROM gridex_requested_changes.review_origins WHERE artifact_id=a.id;
 IF o.event_id IS NOT NULL THEN SELECT reviewer_user_id INTO r.reviewer_user_id FROM gridex_requested_changes.reviews WHERE id=o.review_id;b:=gridex_requested_changes.context_v1(a.company_id,o.event_id,r.reviewer_user_id,'communication.write');END IF;
 IF a.source_bytes IS NULL THEN b:=jsonb_build_object('status','held','missing',ARRAY['requested_change_source_bytes_retention_tombstone']);END IF;
 result:=jsonb_build_object('artifactId',a.id,'kind',a.kind,'effectiveAt',a.effective_at,'sourceReference',a.source_reference,'sourceVersion',a.source_version,'sourceHash',a.source_hash,'claimsHash',a.claims_hash,'mimeType',a.mime_type,'byteLength',coalesce(octet_length(a.source_bytes),(to_jsonb(a)->>'source_byte_length')::int),'customerIdentity',a.claims->'customerIdentity','invoiceeProfile',a.claims->'invoiceeProfile','status',CASE WHEN o.event_id IS NOT NULL AND b->>'status'='authorized' THEN 'authorized' WHEN b->>'status'='held' THEN 'held' WHEN r.decision='approved' THEN 'held' WHEN r.id IS NOT NULL THEN r.decision ELSE 'archived' END,'eventId',o.event_id,'missing',coalesce(b->'missing',r.missing,'["separate_source_review_required"]'::jsonb));
 IF p_include_bytes THEN IF a.source_bytes IS NULL THEN RAISE EXCEPTION 'requested_change_artifact_bytes_retained_as_tombstone';END IF;result:=result||jsonb_build_object('bytesBase64',encode(a.source_bytes,'base64'));END IF;RETURN result;
END$$;
CREATE FUNCTION public.ediel_review_requested_change_artifact_v1(p_company_id uuid,p_artifact_id uuid,p_actor_user_id uuid,p_review jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE a gridex_requested_changes.artifacts%rowtype;c public.customer_contracts%rowtype;d public.customer_contract_documents%rowtype;o gridex_requested_changes.review_origins%rowtype;e gridex_requested_changes.events%rowtype;review_id uuid;missing jsonb:='[]';b jsonb;decision text;sig text;
BEGIN SELECT * INTO STRICT a FROM gridex_requested_changes.artifacts WHERE id=p_artifact_id AND company_id=p_company_id FOR UPDATE;
 IF gridex_requested_changes.actor_v1(p_company_id,p_actor_user_id,'review',a.kind) IS NOT TRUE THEN RAISE EXCEPTION 'requested_change_review_actor_forbidden' USING ERRCODE='42501';END IF;
 IF a.source_bytes IS NULL THEN RAISE EXCEPTION 'requested_change_artifact_bytes_retained_as_tombstone';END IF;
 decision:=p_review->>'decision';IF jsonb_typeof(p_review) IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_review) k WHERE k NOT IN('sourceHash','claimsHash','decision','reason','clause')) OR decision NOT IN('approve','hold','reject') OR p_review->>'sourceHash' IS DISTINCT FROM a.source_hash OR p_review->>'claimsHash' IS DISTINCT FROM a.claims_hash OR nullif(p_review->>'reason','') IS NULL OR length(p_review->>'reason')>4000 THEN RAISE EXCEPTION 'requested_change_review_actual_archived_candidate_required';END IF;
 IF decision='approve' AND a.submitted_by=p_actor_user_id THEN RAISE EXCEPTION 'requested_change_separate_reviewer_required';END IF;
 SELECT * INTO o FROM gridex_requested_changes.review_origins WHERE artifact_id=a.id FOR SHARE;
 IF FOUND THEN IF decision<>'approve' THEN RAISE EXCEPTION 'requested_change_authorized_origin_requires_revocation';END IF;b:=gridex_requested_changes.context_v1(p_company_id,o.event_id,p_actor_user_id,'communication.write');IF b->>'status' IS DISTINCT FROM 'authorized' THEN RETURN jsonb_build_object('status','held','artifactId',a.id,'missing',b->'missing');END IF;RETURN jsonb_build_object('status','authorized','artifactId',a.id,'eventId',o.event_id);END IF;
 IF decision='hold' THEN missing:='["explicit_source_review_hold"]';ELSIF decision='reject' THEN missing:='["explicit_source_review_rejection"]';
 ELSIF a.kind='death' THEN IF gridex_requested_changes.receipt_current_v1(a) IS NOT TRUE THEN missing:='["authentic_current_issuer_and_representation_receipt"]';END IF;
 ELSE
  SELECT * INTO c FROM public.customer_contracts WHERE id=a.contract_id AND company_id=a.company_id FOR SHARE;
  sig:=encode(sha256(convert_to(c.signature_snapshot::text,'UTF8')),'hex');SELECT * INTO d FROM public.customer_contract_documents WHERE company_id=a.company_id AND customer_contract_id=c.id AND document_type='signed_contract_pdf' AND document_sha256=a.source_hash AND verified_at IS NOT NULL ORDER BY id LIMIT 1 FOR SHARE;
  IF c.id IS NULL OR d.id IS NULL OR a.mime_type<>'application/pdf' OR c.document_sha256 IS DISTINCT FROM a.source_hash OR c.signed_at IS NULL OR c.signed_version IS DISTINCT FROM c.contract_version OR c.signature_snapshot_sha256 IS DISTINCT FROM sig OR c.signature_snapshot->>'company_id' IS DISTINCT FROM a.company_id::text OR c.signature_snapshot->>'customer_id' IS DISTINCT FROM a.customer_id::text OR c.signature_snapshot->>'contract_id' IS DISTINCT FROM c.id::text OR jsonb_typeof(p_review->'clause') IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_review->'clause') k WHERE k NOT IN('locator','quote')) OR nullif(p_review#>>'{clause,locator}','') IS NULL OR length(p_review#>>'{clause,locator}')>1000 OR nullif(p_review#>>'{clause,quote}','') IS NULL OR length(p_review#>>'{clause,quote}')>10000 THEN missing:='["actual_own_signed_contract_pdf_signature_and_verbatim_metering_clause"]';END IF;
 END IF;
 IF missing<>'[]'::jsonb THEN INSERT INTO gridex_requested_changes.reviews(artifact_id,company_id,reviewer_user_id,decision,reason,clause,missing) VALUES(a.id,a.company_id,p_actor_user_id,CASE decision WHEN 'reject' THEN 'rejected' ELSE 'held' END,p_review->>'reason',p_review->'clause',missing);RETURN jsonb_build_object('status',CASE decision WHEN 'reject' THEN 'rejected' ELSE 'held' END,'artifactId',a.id,'missing',missing);END IF;
 INSERT INTO gridex_requested_changes.events(company_id,environment,supply_period_id,supply_source_message_id,supply_state_version,contract_id,protected_contract_hash,customer_id,metering_point_id,customer_snapshot_hash,legal_actor_id,legal_sender_id,legal_receiver_id,point_id,identity_agency,grid_area_code,brp_ediel_id,variant,event_kind,effective_at,customer_identity,invoicee_profile,source_reference,source_sha256,source_version,approved_by,approved_at)
 VALUES(a.company_id,a.environment,a.supply_period_id,a.supply_source_message_id,a.supply_state_version,a.contract_id,a.protected_contract_hash,a.customer_id,a.metering_point_id,a.customer_snapshot_hash,a.legal_actor_id,a.legal_sender_id,a.legal_receiver_id,a.point_id,a.identity_agency,a.grid_area_code,a.brp_ediel_id,CASE a.kind WHEN 'death' THEN 'E' WHEN 'quarter_contract' THEN 'F' ELSE 'G' END,a.kind,a.effective_at,a.claims->'customerIdentity',a.claims->'invoiceeProfile',a.source_reference,a.source_hash,a.source_version,p_actor_user_id,now()) RETURNING * INTO e;
 b:=gridex_requested_changes.context_before_intake_v1(a.company_id,e.id,p_actor_user_id,'communication.write');IF b->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION 'requested_change_review_current_owned_source_required';END IF;
 INSERT INTO gridex_requested_changes.reviews(artifact_id,company_id,reviewer_user_id,decision,reason,clause) VALUES(a.id,a.company_id,p_actor_user_id,'approved',p_review->>'reason',p_review->'clause') RETURNING id INTO review_id;
 INSERT INTO gridex_requested_changes.review_origins(event_id,artifact_id,review_id,company_id,contract_document_id,contract_document_binding,signature_hash) VALUES(e.id,a.id,review_id,a.company_id,d.id,CASE WHEN d.id IS NULL THEN NULL ELSE to_jsonb(d) END,sig);
 RETURN jsonb_build_object('status','authorized','artifactId',a.id,'eventId',e.id);
END$$;
ALTER FUNCTION gridex_requested_changes.context_v1(uuid,uuid,uuid,text) RENAME TO context_before_intake_v1;
CREATE FUNCTION gridex_requested_changes.context_v1(c uuid,event uuid,actor uuid,permission text DEFAULT 'communication.write') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE b jsonb;o gridex_requested_changes.review_origins%rowtype;a gridex_requested_changes.artifacts%rowtype;r gridex_requested_changes.reviews%rowtype;contract public.customer_contracts%rowtype;doc public.customer_contract_documents%rowtype;
BEGIN b:=gridex_requested_changes.context_before_intake_v1(c,event,actor,permission);IF b->>'status' IS DISTINCT FROM 'authorized' THEN RETURN b;END IF;
 SELECT * INTO o FROM gridex_requested_changes.review_origins WHERE event_id=event AND company_id=c FOR SHARE;SELECT * INTO a FROM gridex_requested_changes.artifacts WHERE id=o.artifact_id AND company_id=c FOR SHARE;SELECT * INTO r FROM gridex_requested_changes.reviews WHERE id=o.review_id AND artifact_id=a.id AND company_id=c FOR SHARE;
 IF o.event_id IS NULL OR a.id IS NULL OR r.decision IS DISTINCT FROM 'approved' OR r.reviewer_user_id=a.submitted_by OR gridex_requested_changes.actor_v1(c,r.reviewer_user_id,'review',a.kind) IS NOT TRUE OR encode(sha256(a.source_bytes),'hex') IS DISTINCT FROM a.source_hash OR encode(sha256(convert_to(a.claims::text,'UTF8')),'hex') IS DISTINCT FROM a.claims_hash THEN RETURN jsonb_build_object('status','held','missing',ARRAY['requested_change_current_immutable_archived_review_authority']);END IF;
 IF a.kind='death' THEN IF gridex_requested_changes.receipt_current_v1(a) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','missing',ARRAY['authentic_current_issuer_and_representation_receipt']);END IF;
 ELSE SELECT * INTO contract FROM public.customer_contracts WHERE id=a.contract_id AND company_id=c FOR SHARE;SELECT * INTO doc FROM public.customer_contract_documents WHERE id=o.contract_document_id AND company_id=c AND customer_contract_id=contract.id FOR SHARE;
  IF doc.id IS NULL OR to_jsonb(doc) IS DISTINCT FROM o.contract_document_binding OR contract.document_sha256 IS DISTINCT FROM a.source_hash OR contract.signature_snapshot_sha256 IS DISTINCT FROM o.signature_hash OR encode(sha256(convert_to(contract.signature_snapshot::text,'UTF8')),'hex') IS DISTINCT FROM o.signature_hash THEN RETURN jsonb_build_object('status','held','missing',ARRAY['actual_current_signed_contract_document_signature']);END IF;
 END IF;RETURN b;
END$$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA gridex_requested_changes FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.ediel_archive_requested_change_source_v1(uuid,uuid,jsonb),public.ediel_read_requested_change_artifact_v1(uuid,uuid,uuid,boolean),public.ediel_review_requested_change_artifact_v1(uuid,uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ediel_archive_requested_change_source_v1(uuid,uuid,jsonb),public.ediel_read_requested_change_artifact_v1(uuid,uuid,uuid,boolean),public.ediel_review_requested_change_artifact_v1(uuid,uuid,uuid,jsonb) TO service_role;
COMMIT;

