DO $$DECLARE t text;spec record;column_name text;BEGIN
 FOREACH t IN ARRAY ARRAY['finance_class_catalog','finance_decisions','finance_reviews','finance_revocations','finance_tombstones','finance_events'] LOOP
 EXECUTE format('ALTER TABLE gridex_ediel_retention.%I OWNER TO gridex_ediel_retention_owner',t);EXECUTE format('ALTER TABLE gridex_ediel_retention.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE gridex_ediel_retention.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON gridex_ediel_retention.%I FROM PUBLIC,anon,authenticated,service_role',t);EXECUTE format('CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON gridex_ediel_retention.%I FOR EACH ROW EXECUTE FUNCTION gridex_received_sources.reject_mutation()',t);EXECUTE format('CREATE TRIGGER no_truncate BEFORE TRUNCATE ON gridex_ediel_retention.%I FOR EACH STATEMENT EXECUTE FUNCTION gridex_received_sources.reject_mutation()',t);END LOOP;
 FOR spec IN SELECT * FROM gridex_ediel_retention.finance_class_catalog LOOP
  IF to_regclass(format('%I.%I',spec.source_schema,spec.source_table)) IS NULL THEN RAISE EXCEPTION 'finance_retention_actual_table_required: %',spec.source_table;END IF;
  FOREACH column_name IN ARRAY spec.body_columns LOOP IF NOT EXISTS(SELECT FROM pg_attribute WHERE attrelid=format('%I.%I',spec.source_schema,spec.source_table)::regclass AND attname=column_name AND NOT attisdropped AND atttypid IN('jsonb'::regtype,'text'::regtype)) THEN RAISE EXCEPTION 'finance_retention_actual_body_column_required: %.%',spec.source_table,column_name;END IF;END LOOP;
  EXECUTE format('GRANT USAGE ON SCHEMA %I TO gridex_ediel_retention_owner',spec.source_schema);EXECUTE format('GRANT SELECT,UPDATE ON %I.%I TO gridex_ediel_retention_owner',spec.source_schema,spec.source_table);
 END LOOP;END$$;
