CREATE FUNCTION public.ediel_review_finance_copy_retention_v1(p_company_id uuid,p_actor_user_id uuid,p_decision_id uuid,p_outcome text,p_reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE d gridex_ediel_retention.finance_decisions%rowtype;basis jsonb;outcome text;r uuid;BEGIN
