CREATE FUNCTION gridex_ediel_retention.finance_redacted_v1(k text,oldrow jsonb,hash text) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE spec gridex_ediel_retention.finance_class_catalog%rowtype;col text;type oid;marker jsonb:=jsonb_build_object('retentionUnavailable',true,'sourceHash',hash,'complete',false,'authority','none');result jsonb:=oldrow;BEGIN SELECT * INTO STRICT spec FROM gridex_ediel_retention.finance_class_catalog WHERE retention_class=k;FOREACH col IN ARRAY spec.body_columns LOOP SELECT atttypid INTO STRICT type FROM pg_attribute WHERE attrelid=format('%I.%I',spec.source_schema,spec.source_table)::regclass AND attname=col;result:=jsonb_set(result,ARRAY[col],CASE WHEN type='jsonb'::regtype THEN marker ELSE to_jsonb(marker::text) END);END LOOP;RETURN result;END$$;
CREATE FUNCTION public.ediel_is_qualified_finance_retention_transition_v1(p_schema text,p_table text,p_old jsonb,p_new jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE spec gridex_ediel_retention.finance_class_catalog%rowtype;t gridex_ediel_retention.finance_tombstones%rowtype;BEGIN SELECT * INTO spec FROM gridex_ediel_retention.finance_class_catalog WHERE source_schema=p_schema AND source_table=p_table;IF NOT FOUND THEN RETURN false;END IF;SELECT * INTO t FROM gridex_ediel_retention.finance_tombstones WHERE retention_class=spec.retention_class AND target_id=p_old->>spec.id_column;RETURN t.target_id IS NOT NULL AND t.company_id::text=p_old->>'company_id' AND t.target_hash=encode(sha256(convert_to(p_old::text,'UTF8')),'hex') AND p_new=gridex_ediel_retention.finance_redacted_v1(spec.retention_class,p_old,t.source_hash);END$$;
CREATE FUNCTION gridex_ediel_retention.finance_target_guard_v1() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE spec gridex_ediel_retention.finance_class_catalog%rowtype;r jsonb;BEGIN SELECT * INTO STRICT spec FROM gridex_ediel_retention.finance_class_catalog WHERE source_schema=TG_TABLE_SCHEMA AND source_table=TG_TABLE_NAME;r:=CASE WHEN TG_OP='INSERT' THEN to_jsonb(NEW) ELSE to_jsonb(OLD) END;IF EXISTS(SELECT FROM gridex_ediel_retention.finance_tombstones WHERE retention_class=spec.retention_class AND target_id=r->>spec.id_column) AND NOT(TG_OP='UPDATE' AND public.ediel_is_qualified_finance_retention_transition_v1(TG_TABLE_SCHEMA,TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW))) THEN RAISE EXCEPTION 'finance_copy_retention_tombstoned';END IF;RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;END$$;
-- Clone only actual immutable guard bindings, not their owners or ACLs. The
-- bounded exception permits the one native authorized OLD/NEW body transition.
DO $$DECLARE spec record;f record;name text;body text;definition text;setting text;BEGIN FOR spec IN SELECT * FROM gridex_ediel_retention.finance_class_catalog LOOP
 FOR f IN SELECT t.oid trigger_oid,t.tgname,p.prosrc,p.proowner,p.proconfig,p.prosecdef FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE t.tgrelid=format('%I.%I',spec.source_schema,spec.source_table)::regclass AND NOT t.tgisinternal AND (t.tgtype & 2)=2 AND (t.tgtype & 16)=16 AND (p.prosrc~*'immutable|append.only|protected|already.*sent|locked.*settlement|new[.]updated_at|new[.]updated_by') LOOP
 IF f.prosrc!~*'\mBEGIN\M' THEN RAISE EXCEPTION 'finance_retention_guard_source_review_required';END IF;name:='finance_guard_'||f.trigger_oid;body:=regexp_replace(f.prosrc,'\mBEGIN\M','BEGIN IF TG_OP=''UPDATE'' AND public.ediel_is_qualified_finance_retention_transition_v1(TG_TABLE_SCHEMA,TG_TABLE_NAME,to_jsonb(OLD),to_jsonb(NEW)) THEN RETURN NEW;END IF;','i');EXECUTE format('CREATE FUNCTION gridex_ediel_retention.%I() RETURNS trigger LANGUAGE plpgsql SECURITY %s SET search_path=pg_catalog AS %L',name,CASE WHEN f.prosecdef THEN 'DEFINER' ELSE 'INVOKER' END,body);FOREACH setting IN ARRAY coalesce(f.proconfig,ARRAY[]::text[]) LOOP EXECUTE format('ALTER FUNCTION gridex_ediel_retention.%I() SET %I TO %L',name,split_part(setting,'=',1),substring(setting from position('=' in setting)+1));END LOOP;EXECUTE format('ALTER FUNCTION gridex_ediel_retention.%I() OWNER TO %I',name,(SELECT rolname FROM pg_roles WHERE oid=f.proowner));EXECUTE format('REVOKE ALL ON FUNCTION gridex_ediel_retention.%I() FROM PUBLIC,anon,authenticated,service_role',name);EXECUTE format('GRANT EXECUTE ON FUNCTION public.ediel_is_qualified_finance_retention_transition_v1(text,text,jsonb,jsonb) TO %I',(SELECT rolname FROM pg_roles WHERE oid=f.proowner));definition:=pg_get_triggerdef(f.trigger_oid);EXECUTE format('DROP TRIGGER %I ON %I.%I',f.tgname,spec.source_schema,spec.source_table);EXECUTE regexp_replace(definition,'EXECUTE (FUNCTION|PROCEDURE) .*$',format('EXECUTE FUNCTION gridex_ediel_retention.%I()',name));END LOOP;
 EXECUTE format('CREATE TRIGGER zz_finance_retention_target BEFORE INSERT OR UPDATE OR DELETE ON %I.%I FOR EACH ROW EXECUTE FUNCTION gridex_ediel_retention.finance_target_guard_v1()',spec.source_schema,spec.source_table);END LOOP;END$$;
-- The existing native financial audit owner must not re-copy the old body
-- solely because this exact class was lawfully redacted. The class event and
-- signed finite journal purpose above retain its qualified operation receipt.
DO $$DECLARE body text;definition text;BEGIN
 IF to_regprocedure('public.gridex_audit_portfolio_settlement_write()') IS NOT NULL THEN
  SELECT prosrc INTO STRICT body FROM pg_proc WHERE oid='public.gridex_audit_portfolio_settlement_write()'::regprocedure;definition:=pg_get_functiondef('public.gridex_audit_portfolio_settlement_write()'::regprocedure);
