 SELECT prosrc INTO STRICT body FROM pg_proc WHERE oid='gridex_billing_source.require_underlay_v1(uuid,uuid)'::regprocedure;definition:=pg_get_functiondef('gridex_billing_source.require_underlay_v1(uuid,uuid)'::regprocedure);body:=regexp_replace(body,'\mBEGIN\M','BEGIN PERFORM public.ediel_require_invoice_source_copies_available_v1(p_company,p_underlay);','i');EXECUTE replace(definition,(SELECT prosrc FROM pg_proc WHERE oid='gridex_billing_source.require_underlay_v1(uuid,uuid)'::regprocedure),body);
END$$;
CREATE FUNCTION gridex_ediel_retention.finance_fresh_consumption_guard_v1() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE r jsonb:=to_jsonb(NEW);source uuid;BEGIN
 IF TG_OP='UPDATE' AND public.ediel_is_qualified_finance_retention_transition_v1(TG_TABLE_SCHEMA,TG_TABLE_NAME,to_jsonb(OLD),r) IS TRUE THEN RETURN NEW;END IF;
 IF TG_TABLE_NAME='portfolio_monthly_settlements' THEN source:=(r->>'supersedes_settlement_id')::uuid;IF source IS NOT NULL THEN PERFORM public.ediel_require_finance_copy_available_v1(NEW.company_id,'settlement_calculation_body',source::text);END IF;
 ELSE source:=(r->>'billing_underlay_id')::uuid;IF source IS NOT NULL THEN PERFORM public.ediel_require_invoice_source_copies_available_v1(NEW.company_id,source);END IF;END IF;RETURN NEW;END$$;
