CREATE TRIGGER zz_finance_actual_source_consumption BEFORE INSERT OR UPDATE ON public.customer_invoices FOR EACH ROW EXECUTE FUNCTION gridex_ediel_retention.finance_fresh_consumption_guard_v1();
