20261023199000_final_month_pricing_contr.body:
-- FINDINGS H3 downstream (F108 end side, sidofynd 1), owner decision 2026-10-22 (H2/H3): a supply ended by a Z05 is
-- still billed for its final month, and a contract the supply-end follow-up (gridex_supply_end_followup_v1) terminated
-- because exactly that supply ended stays billable for it. The value gate (gridex_set_metering_billing_gate,
-- 20261022150000) and the underlay store (gridex_store_billing_underlay, 20261023196000) accept that, but the pricing
-- and export readers below them accepted only 'signed'/'active' contracts:
--   * gridex_read_interval_pricing_snapshot_v1 and gridex_persist_pricing_run read the exact contract's price snapshot
--     and contract_type only for 'active'/'signed'. For the final underlay they fell back to the underlay snapshot and
--     'monthly', so an hourly/quarterly contract whose resolution comes from its contract type or snapshot was refused
--     with interval_pricing_snapshot_underlay_selector_mismatch, and persist skipped the interval receipt requirement.
--   * billing_export_readiness_v joined only a 'signed'/'active' contract, so a priced and locked final underlay was
--     blocked with exact_signed_contract_missing and never queued (gridex_queue_billing_export_run).
-- (The pricing engine's loadContract and the export center apply the same rule in TypeScript: contractCarriesUnderlay /
-- contractCarriesBilledPeriod.)
--
-- Rule (exactly the gate's and the store's; their text is reused verbatim and checked against the installed gate and
-- store below): the contract is 'signed'/'active', or it is the contract of the underlay's own supply period (same
-- tenant, customer and metering point) and
--   NOT <gate/store status clause>  -- billed period status; 'terminated' + 'supply_end' + ended_at on sp.end_date
--   AND NOT <gate start clause>     -- billed period starts at/after civil midnight of the supply start date
--   AND NOT <gate end clause>       -- billed period ends at/before the supply end (a received Z05 at market_end_at, M5)
-- with the gate's n.period_start/n.period_end read as the billed period: the underlay's exact period (v_period_start/
-- v_period_end, computed and validated by both functions before the contract read) and, in the export view, the
-- period of the underlay's locked pricing run (written from that same exact period by persist). Another tenant's
-- contract, a contract terminated for another reason or by another supply end, and a billed period after the supply
-- end stay refused.
--
-- Exact-needle rewrites of the installed bodies (the 20261013093922 persist/read bodies) and of the installed view
-- definition. Owner, ACL, security mode, volatility and configuration (proconfig) of both functions and the owner, ACL
-- and options (security_invoker) of the view are preserved and checked. Not applied to any world; manifest unchanged.
begin;

do $h3p$
declare
  status_clause constant text := $c$NOT coalesce(sp.status IN ('active','confirmed_by_grid_owner','ending','ended'),false)
   OR (sp.status IN ('ending','ended') AND coalesce(sp.actual_end_date,sp.end_date) IS NULL)
   -- H3: a contract ended by exactly this period's end still carries the period up to that end.
   OR NOT coalesce(ct.status IN ('signed','active') OR (ct.status='terminated' AND ct.termination_reason='supply_end' AND sp.end_date IS NOT NULL AND ct.ended_at IS NOT NULL
    AND ((ct.ended_at AT TIME ZONE 'UTC')::date=sp.end_date OR (ct.ended_at AT TIME ZONE 'Europe/Stockholm')::date=sp.end_date)),false)$c$;
  start_clause constant text := $c$sp.start_date IS NULL OR (sp.start_date::timestamp AT TIME ZONE 'Europe/Stockholm')>n.period_start$c$;
  end_clause constant text := $c$(coalesce(sp.actual_end_date,sp.end_date) IS NOT NULL AND (CASE
     -- H1: a received market end at the start of its date is exclusive (end_date = first day not supplied).
     -- F108 M5: it ends at the market instant itself (00:00 +0100, 23:00Z in summer), as the qualified supply basis.
     WHEN sp.market_end_at IS NOT NULL AND sp.market_end_at<=(coalesce(sp.actual_end_date,sp.end_date)::timestamp AT TIME ZONE 'Europe/Stockholm')+interval '1 hour'
     THEN sp.market_end_at ELSE (coalesce(sp.actual_end_date,sp.end_date)+1)::timestamp AT TIME ZONE 'Europe/Stockholm' END)<n.period_end)$c$;
  fn_needle constant text := $n$where c.company_id=p_company_id and c.id=v_underlay.contract_id and c.status in ('active','signed');$n$;
  view_needle constant text := $n$(c.status = ANY (ARRAY['signed'::text, 'active'::text]))$n$;
  gate_src text;
  store_src text;
  fn_replacement text;
  view_replacement text;
  f record;
  v record;
  body text;
  definition text;
  target regprocedure;
begin
  -- The reused rule must be the installed gate's and store's own text (20261022150000, 20261023196000).
  select p.prosrc into strict gate_src from pg_proc p where p.oid = 'public.gridex_set_metering_billing_gate(uuid,uuid,uuid,jsonb)'::regprocedure;
  select p.prosrc into strict store_src from pg_proc p where p.oid = 'public.gridex_store_billing_underlay(uuid,jsonb,jsonb,uuid)'::regprocedure;
  if position(status_clause in gate_src) = 0 or position(status_clause in store_src) = 0
    or position(start_clause in gate_src) = 0 or position(end_clause in gate_src) = 0 then
    raise exception 'final_month_pricing_contract_rule_source_changed' using errcode = 'P0U01';
  end if;

  fn_replacement := $r$where c.company_id=p_company_id and c.id=v_underlay.contract_id and (c.status in ('active','signed')
    -- H3 (20261023199000): a contract terminated by exactly this underlay's supply end still carries its final period,
    -- by the rule of gridex_set_metering_billing_gate/gridex_store_billing_underlay (text-identical, n.period_* = v_period_*).
    or exists(select 1 from public.customer_supply_periods sp join public.customer_contracts ct on ct.id=c.id and ct.company_id=p_company_id
      where sp.id=v_underlay.supply_period_id and sp.company_id=p_company_id and sp.contract_id=ct.id
        and sp.customer_id=v_underlay.customer_id and sp.metering_point_id=v_underlay.metering_point_id
        and ct.customer_id=v_underlay.customer_id and ct.metering_point_id=v_underlay.metering_point_id
        and NOT (@status@)
        and NOT (@start@)
        and NOT @end@));$r$;
  fn_replacement := replace(replace(replace(fn_replacement, '@status@', status_clause),
    '@start@', replace(start_clause, 'n.period_start', 'v_period_start')),
    '@end@', replace(end_clause, 'n.period_end', 'v_period_end'));

  foreach target in array array[
    'public.gridex_read_interval_pricing_snapshot_v1(uuid,uuid,timestamp with time zone,timestamp with time zone,text,text,jsonb)'::regprocedure,
    'public.gridex_persist_pricing_run(uuid,uuid,jsonb,jsonb)'::regprocedure]
  loop
    select p.oid, to_jsonb(p) - 'prosrc' as metadata, p.prosrc, pg_get_functiondef(p.oid) as definition into strict f
    from pg_proc p where p.oid = target;
    if (length(f.prosrc) - length(replace(f.prosrc, fn_needle, ''))) / length(fn_needle) <> 1
      or position('Match engine.normalizePricingSnapshot and its interval-resolution fallback.' in f.prosrc) = 0
      or position('v_period_end' in f.prosrc) = 0
      or (length(f.definition) - length(replace(f.definition, f.prosrc, ''))) / length(f.prosrc) <> 1 then
      raise exception 'final_month_pricing_contract_predecessor_required:%', target using errcode = 'P0U01';
    end if;
    body := replace(f.prosrc, fn_needle, fn_replacement);
    execute replace(f.definition, f.prosrc, body);
    if (select to_jsonb(p) - 'prosrc' from pg_proc p where p.oid = f.oid) is distinct from f.metadata
      or (select p.prosrc from pg_proc p where p.oid = f.oid) is distinct from body then
      raise exception 'final_month_pricing_contract_metadata_changed:%', target using errcode = 'P0U01';
    end if;
  end loop;

  -- billing_export_readiness_v: the billed period is the underlay's locked pricing run period.
  view_replacement := $r$((c.status = ANY (ARRAY['signed'::text, 'active'::text]))
    OR EXISTS (SELECT 1 FROM public.customer_supply_periods sp JOIN public.customer_contracts ct ON ct.id = c.id AND ct.company_id = b.company_id
      JOIN public.pricing_runs n ON n.company_id = b.company_id AND n.billing_underlay_id = b.id AND n.status = 'locked'
      WHERE sp.id = b.supply_period_id AND sp.company_id = b.company_id AND sp.contract_id = ct.id
        AND sp.customer_id = b.customer_id AND sp.metering_point_id = b.metering_point_id
        AND ct.customer_id = b.customer_id AND ct.metering_point_id = b.metering_point_id
        AND NOT (@status@)
        AND NOT (@start@)
        AND NOT @end@))$r$;
  view_replacement := replace(replace(replace(view_replacement, '@status@', status_clause),
    '@start@', replace(start_clause, 'n.period_start', 'n.billing_period_start')),
    '@end@', replace(end_clause, 'n.period_end', 'n.billing_period_end'));

  select c.oid, c.relowner, c.relacl, c.reloptions, pg_get_viewdef(c.oid) as definition,
    (select jsonb_agg(jsonb_build_array(a.attname, format_type(a.atttypid, a.atttypmod)) order by a.attnum)
       from pg_attribute a where a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped) as columns
    into strict v
  from pg_class c where c.oid = 'public.billing_export_readiness_v'::regclass and c.relkind = 'v';
  if (length(v.definition) - length(replace(v.definition, view_needle, ''))) / length(view_needle) <> 1
    or position('exact_signed_contract_missing' in v.definition) = 0
    or position('LEFT JOIN customer_contracts c ON' in v.definition) = 0 then
    raise exception 'final_month_pricing_contract_predecessor_required:billing_export_readiness_v' using errcode = 'P0U01';
  end if;
  definition := regexp_replace(replace(v.definition, view_needle, view_replacement), ';\s*$', '');
  execute format('create or replace view public.billing_export_readiness_v%s as %s',
    case when v.reloptions is null then '' else ' with (' || array_to_string(v.reloptions, ', ') || ')' end, definition);
  if (select row(c.relowner, c.relacl, c.reloptions) from pg_class c where c.oid = v.oid) is distinct from row(v.relowner, v.relacl, v.reloptions)
    or (select jsonb_agg(jsonb_build_array(a.attname, format_type(a.atttypid, a.atttypmod)) order by a.attnum)
          from pg_attribute a where a.attrelid = v.oid and a.attnum > 0 and not a.attisdropped) is distinct from v.columns
    or position('supply_period_id' in pg_get_viewdef(v.oid)) = 0 then
    raise exception 'final_month_pricing_contract_metadata_changed:billing_export_readiness_v' using errcode = 'P0U01';
  end if;
end
$h3p$;

commit;

20261023232114_preserve_qualified_underl.body:
-- Preserve the immutable original commercial/source snapshot on qualified
-- underlays. Both success and failure diagnostics already live on pricing_runs.
-- Unbound legacy underlays retain their existing diagnostic snapshot behavior.
-- The source guard, exact identity, tenant and pricing receipt guards stay intact.
BEGIN;
DO $repair$ DECLARE f record;b text;needle text;replacement text;
BEGIN
 SELECT p.oid,to_jsonb(p)-'prosrc' metadata,p.prosrc,pg_get_functiondef(p.oid) definition INTO STRICT f
 FROM pg_proc p WHERE oid='public.gridex_persist_pricing_run(uuid,uuid,jsonb,jsonb)'::regprocedure;
 IF encode(sha256(convert_to(f.prosrc,'UTF8')),'hex') NOT IN ('c8676fd912b87e31db2fcef33acb495c0e2123a7318ea54f80e625320f943d3d','ee495118b1e4e568fae2032ba4fc6a0d8b709492b3c46354ba33c2bed819f618') THEN RAISE EXCEPTION 'source_bound_pricing_exact_predecessor_required';END IF;
 b:=f.prosrc;
 needle:=$needle$  v_rows integer;$needle$;replacement:=$replacement$  v_rows integer;
  v_source_bound boolean;$replacement$;
 IF (length(b)-length(replace(b,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION 'source_bound_pricing_exact_anchor_required';END IF;
 b:=replace(b,needle,replacement);
 needle:=$needle$  if not found then raise exception using errcode='P0002',message='billing_underlay_not_found_for_tenant'; end if;$needle$;replacement:=$replacement$  if not found then raise exception using errcode='P0002',message='billing_underlay_not_found_for_tenant'; end if;
  v_source_bound:=EXISTS(SELECT FROM gridex_billing_source.underlay_bindings b WHERE b.company_id=p_company_id AND b.underlay_id=p_billing_underlay_id);
  IF v_source_bound AND coalesce(p_pricing_snapshot,'{}'::jsonb) IS DISTINCT FROM coalesce(v_underlay.pricing_snapshot,'{}'::jsonb) THEN
    RAISE EXCEPTION 'source_bound_pricing_snapshot_mismatch' USING ERRCODE='23514';
  END IF;$replacement$;
 IF (length(b)-length(replace(b,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION 'source_bound_pricing_exact_anchor_required';END IF;
 b:=replace(b,needle,replacement);
 needle:=$needle$pricing_snapshot=coalesce(p_pricing_snapshot,'{}'::jsonb)||jsonb_build_object(
        'latest_pricing_run_id',v_run_id,'latest_pricing_warnings',coalesce(p_result->'warnings','[]'::jsonb),
        'latest_pricing_errors',coalesce(p_result->'errors','[]'::jsonb)
      )$needle$;replacement:=$replacement$pricing_snapshot=CASE WHEN v_source_bound THEN pricing_snapshot ELSE coalesce(p_pricing_snapshot,'{}'::jsonb)||jsonb_build_object(
        'latest_pricing_run_id',v_run_id,'latest_pricing_warnings',coalesce(p_result->'warnings','[]'::jsonb),
        'latest_pricing_errors',coalesce(p_result->'errors','[]'::jsonb)
      ) END$replacement$;
 IF (length(b)-length(replace(b,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION 'source_bound_pricing_exact_anchor_required';END IF;
 b:=replace(b,needle,replacement);
 needle:=$needle$pricing_snapshot=coalesce(pricing_snapshot,'{}'::jsonb)||jsonb_build_object(
        'latest_failed_pricing_run_id',v_run_id,'latest_pricing_errors',coalesce(p_result->'errors','[]'::jsonb)
      )$needle$;replacement:=$replacement$pricing_snapshot=CASE WHEN v_source_bound THEN pricing_snapshot ELSE coalesce(pricing_snapshot,'{}'::jsonb)||jsonb_build_object(
        'latest_failed_pricing_run_id',v_run_id,'latest_pricing_errors',coalesce(p_result->'errors','[]'::jsonb)
      ) END$replacement$;
 IF (length(b)-length(replace(b,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION 'source_bound_pricing_exact_anchor_required';END IF;
 b:=replace(b,needle,replacement);
 EXECUTE replace(f.definition,f.prosrc,b);
 IF (SELECT to_jsonb(p)-'prosrc' FROM pg_proc p WHERE oid=f.oid) IS DISTINCT FROM f.metadata THEN RAISE EXCEPTION 'source_bound_pricing_metadata_changed';END IF;
END$repair$;
COMMIT;

20261023205000_h3d_move_out_notice_and_t.body:
-- FINDINGS H3d slice 2 (reports/h3d-move-out-notice.md D1, D2, D3, D6, D8, D9; H3c open items 1 and 2), owner decisions
-- 2026-10-23 B1, B3 and 20 (OWNER-DECISIONS.md rows 16, 18, 20).
--
-- B1 (move-out): the CONTRACT ends by its notice period, counted from the customer's notice date, for every customer
--   type; the SUPPLY (energy and fixed fees, decision 20) ends on the move-out day. A customer whose grid contract
--   ended has no supply either: the new close mode 'grid_contract_ended' ends the supply like a move-out, with its own
--   reason. Contract end = greatest(last supplied day, notice date + notice_months + notice days) (20261023204000), so it
--   may lie after the supply end; billing carries only the supplied days (20261023203000, D8).
-- D3: the customer's notice date is kept: an earlier registered termination_notice_date stands; otherwise the notice
--   date the operator entered (p_notice_date), else the Stockholm day of the close. It is never overwritten by now().
-- D9: the close writes the actual reason: 'move_out', 'grid_contract_ended', or 'customer_termination' (mode
--   'terminate'), never 'move_out' for a termination.
-- B3 (termination without a move): the supply continues until a new supplier takes over (Z05 from the grid owner).
--   * gridex_register_customer_termination_v1 records the termination on the customer's signed/active contracts
--     (termination_notice_received: the notice date, and ended_at = the planned end by the rule "Uppsägning mottagen"
--     already uses, gridex_contract_termination_end_v1). Status, supply, sites, points and open work are untouched.
--   * The close's mode 'terminate' delegates to it while any supply is ongoing after the given date (it no longer ends
--     the supply and closes the customer). Without ongoing supply it closes as before, with 'customer_termination'.
--   * gridex_termination_notice_expiry_tasks_v1 (customer-operations cron): when the planned end has been reached and
--     the contract is still signed/active with an open supply period (no new supplier's Z05 has ended it), it creates
--     ONE operator task 'termination_end_of_supply_pending' per contract and planned end: send an end of supply (Z08)
--     to the grid owner. Nothing is sent automatically. This is where "Uppsägning mottagen" now leads.
-- Z05 after a manual end (H3c open 1): a received end on a period the close ended manually (planned_end_* marker, no
--   end_key) now (a) corrects the terminated manual-end contract's ended_at to the received end when that end is later,
--   so billing keeps carrying the supplied days, and (b) keeps ONE final invoice per supply period: the close's open
--   'final_invoice_pending' task is updated with the received end (received_end_key); an already resolved one gets a
--   'final_invoice_correction_review' instead of a second final invoice. The Z05 contract event is unchanged, except
--   that an earlier registered notice date and a later planned contract end (B1/B3) are kept.
-- H3c open 2 (documented, not changed): a Z05 after gridex_end_customer_supply_v1('move_out') is refused by the received
--   source owners (z05_accepted_relationship_baseline_required) because that writer marks the period 'ended' without a
--   received end. The refusal is raised in gridex_received_sources.other_supply_scope_effect_v1 (DB-05 protected) and
--   apply_supply_before_legal_context_v1 (the approved AT-Z05 owner); neither is changed here. The writer has no app
--   caller; the customer card's close (which keeps the period's status and so accepts the Z05) is the operator path.
-- D6: the close (mode 'move_out'/'grid_contract_ended') keeps a pending move-in at another address: a site whose
--   pending switch request is a move-in (process_type/request_type 'move_in') and that has no supply ongoing at the
--   move-out date keeps its site, metering points, future supply periods, contracts, switch request and open tasks, and
--   the customer keeps its status (only moved_out_at and the lifecycle fields record the move).
-- gridex_end_customer_supply_v1 'move_out': the same B1/D3 contract end and notice date ('supplier_switch' unchanged).
--
-- gridex_close_customer_lifecycle_v2 is v1 with the parameter p_notice_date (default null) and the changes above; v1
-- keeps its signature and delegates with p_notice_date null. Exact-needle rewrites of the installed bodies (after
-- 20261023202000); refuses (h3d_notice_termination_rule_source_changed) unless every needle is present exactly once and
-- the H3d slice-2 marker is absent. Owner, ACL, security definer, volatility and configuration are preserved and checked
-- (h3d_notice_termination_metadata_changed); v2 gets v1's owner, ACL and configuration.
begin;

-- The lifecycle event types of the new modes.
alter table public.customer_lifecycle_events drop constraint customer_lifecycle_events_type_check;
alter table public.customer_lifecycle_events add constraint customer_lifecycle_events_type_check
  check (event_type = any (array['move_out'::text, 'terminate'::text, 'restore'::text, 'note'::text,
    'grid_contract_ended'::text, 'termination_registered'::text]));

create index if not exists customer_contracts_pending_termination_idx
  on public.customer_contracts (company_id, ended_at)
  where status in ('signed', 'active') and termination_notice_date is not null;

create function pg_temp.h3d2_rewrite(p_body text, p_old text[], p_new text[], p_label text) returns text
language plpgsql as $rewrite$
declare
  body text := p_body;
  i integer;
begin
  if position('H3d (20261023205000)' in body) <> 0 or cardinality(p_old) <> cardinality(p_new) then
    raise exception 'h3d_notice_termination_rule_source_changed:%', p_label using errcode = 'P0U01';
  end if;
  for i in 1 .. cardinality(p_old) loop
    if (length(body) - length(replace(body, p_old[i], ''))) / length(p_old[i]) <> 1 then
      raise exception 'h3d_notice_termination_rule_source_changed:%:%', p_label, i using errcode = 'P0U01';
    end if;
    body := replace(body, p_old[i], p_new[i]);
  end loop;
  return body;
end
$rewrite$;

-- B3: register a termination without a move. The supply is not touched.
create function public.gridex_register_customer_termination_v1(
  p_company_id uuid, p_customer_id uuid, p_actor_user_id uuid, p_notice_date date, p_reason text, p_note text)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions, pg_catalog, pg_temp
as $$
declare
  v_customer public.customers%rowtype;
  v_contract record;
  v_notice_date date;
  v_planned_end date;
  v_contracts jsonb := '[]'::jsonb;
  v_metadata jsonb;
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode = '42501', message = 'customer_lifecycle_service_role_required';
  end if;
  if p_company_id is null or p_customer_id is null or p_actor_user_id is null or p_notice_date is null then
    raise exception using errcode = '22023', message = 'customer_lifecycle_payload_invalid';
  end if;
  select * into v_customer from public.customers
  where id = p_customer_id and company_id = p_company_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'customer_not_found_for_tenant';
  end if;
  if v_customer.status in ('archived', 'moved', 'terminated') then
    raise exception using errcode = '23514', message = 'customer_lifecycle_already_closed';
  end if;
  v_metadata := jsonb_build_object('mode', 'terminate', 'noticeDate', p_notice_date, 'reason', p_reason,
    'source', 'admin_customer_card', 'supplyContinues', true,
    'legalHandling', 'Termination without a move: the supply continues until a new supplier takes over (Z05); when the notice period has expired without a switch, an operator task asks for an end of supply (Z08) to the grid owner.');

  for v_contract in
    select c.id, c.status, c.starts_at, c.ends_at, c.binding_months, c.notice_months, c.termination_notice_date
    from public.customer_contracts c
    where c.company_id = p_company_id and c.customer_id = p_customer_id and c.status in ('signed', 'active')
    order by c.id
    for update
  loop
    -- D3: an earlier registered notice date stands.
    v_notice_date := coalesce(v_contract.termination_notice_date, p_notice_date);
    v_planned_end := public.gridex_contract_termination_end_v1(v_contract.starts_at, v_contract.ends_at,
      v_contract.binding_months, v_contract.notice_months,
      public.gridex_customer_contract_notice_days_v1(p_company_id, v_contract.id), v_notice_date);
    perform public.gridex_record_customer_contract_event_v1(
      p_company_id, v_contract.id, p_customer_id, 'termination_notice_received', v_notice_date::timestamptz,
      'Kunden sade upp avtalet utan flytt. Leveransen fortsätter tills en ny leverantör tar över.',
      v_metadata || jsonb_build_object('termination_reason', 'customer_termination', 'notice_end_date', v_planned_end),
      p_actor_user_id, v_planned_end::timestamptz,
      'customer-termination:' || v_contract.id::text || ':' || to_char(v_notice_date, 'YYYY-MM-DD'));
    v_contracts := v_contracts || jsonb_build_array(jsonb_build_object('contract_id', v_contract.id,
      'termination_notice_date', v_notice_date, 'planned_end_date', v_planned_end));
  end loop;
  if jsonb_array_length(v_contracts) = 0 then
    raise exception using errcode = '23514', message = 'customer_termination_contract_not_found';
  end if;

  if nullif(btrim(p_note), '') is not null then
    insert into public.customer_internal_notes (company_id, customer_id, body, created_by, updated_by)
    values (p_company_id, p_customer_id, p_note, p_actor_user_id, p_actor_user_id);
  end if;
  insert into public.customer_lifecycle_events (
    company_id, customer_id, event_type, event_status, effective_date, reason, payload, created_by
  ) values (
    p_company_id, p_customer_id, 'termination_registered', 'completed', p_notice_date, p_reason,
    v_metadata || jsonb_build_object('contracts', v_contracts), p_actor_user_id
  );

  return jsonb_build_object(
    'mode', 'terminate',
    'termination_registered', true,
    'supply_continues', true,
    'customer_before', to_jsonb(v_customer),
    'customer', to_jsonb(v_customer),
    'contracts', v_contracts,
    'failed_switch_request_ids', '[]'::jsonb,
    'lifecycle', v_metadata
